/** Exact pack from Salads, Sandwiches and Chafing-Dish Dainties. Protein enum only; ingredients cleaned to match steps. Free core. */
export const HILL_SALADS_RECIPES: Recipe[] = [
  h('hill-0001', 'How to Boil Eggs Hard for Garnishing', 'American', ["section-garnishes-and-preparations"], 'eggs', 'bowl', 45, 'Cover the eggs with boiling water.', [I('eggs', 1, '', 'Dairy & Eggs')], ['Cover the eggs with boiling water.', 'Set them on the back of the range, where the water will keep hot without boiling, about forty minutes.', 'Cool in cold water, and with a thin, sharp knife cut as desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0002', 'To Poach Whites of Eggs', 'American', ["section-garnishes-and-preparations"], 'eggs', 'bowl', 45, 'Turn the whites of the eggs into a well-buttered mould or cup, set upon a trivet in a dish of hot water, and cook until firm, either upon the back of the range or in the oven, and without letting the water boil.', [I('egg whites', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry')], ['Turn the whites of the eggs into a well-buttered mould or cup, set upon a trivet in a dish of hot water, and cook until firm, either upon the back of the range or in the oven, and without letting the water boil.', 'Turn from the mould, cut into slices, and then into fanciful shapes; or chop fine.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0003', 'Royal Custard for Moulds of Aspic', 'American', ["section-garnishes-and-preparations"], 'eggs', 'dessert', 45, 'Beat together one whole egg and three yolks; add one-fourth a teaspoonful, each, of mace, salt and paprica, and, when well mixed, add half a cup of cream.', [I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('mace', 1, '', 'Herbs & Spices'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry')], ['Beat together one whole egg and three yolks; add one-fourth a teaspoonful, each, of mace, salt and paprica, and, when well mixed, add half a cup of cream.', 'Bake in a buttered mould, set in a pan of water, until firm.', 'When cold cut in thin slices, then stamp out in fanciful shapes with French cutters.', 'Use in decorating a mould for aspic jelly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0004', 'How to Shell and Blanch Chestnuts', 'American', ["section-garnishes-and-preparations"], 'veg', 'skillet', 45, 'Score the shell of each nut, and put into a frying-pan with a teaspoonful of butter for each pint of nuts.', [I('butter', 1, '', 'Dairy & Eggs'), I('nuts', 1, '', 'Produce'), I('chestnuts', 1, '', 'Produce')], ['Score the shell of each nut, and put into a frying-pan with a teaspoonful of butter for each pint of nuts.', 'Shake the pan over the fire until the butter is melted; then set in the oven five minutes.', 'With a sharp knife remove the shells and skins together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0005', 'How to Blanch Walnuts and Almonds', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'Put the nut meats over the fire in cold water, bring quickly to the boiling-point, drain, and rinse with cold water, then the skins may be easily rubbed from the almonds; a small pointed knife will be needed for the…', [I('walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce')], ['Put the nut meats over the fire in cold water, bring quickly to the boiling-point, drain, and rinse with cold water, then the skins may be easily rubbed from the almonds; a small pointed knife will be needed for the walnuts.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0006', 'How to Blanch and Cook Vegetables for Salads', 'American', ["section-garnishes-and-preparations"], 'veg', 'green', 45, 'Cut the vegetables as desired, in cubes, lozenges, balls, _juliennes_, etc.', [I('vegetables', 1, '', 'Pantry')], ['Cut the vegetables as desired, in cubes, lozenges, balls, _juliennes_, etc.', 'Put over the fire in boiling water, and, after cooking three or four minutes, drain, rinse in cold water, and put on to cook in boiling salted water to cover.', 'Drain as soon as tender.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0007', 'How to Cook Sweetbreads and Brains', 'American', ["section-garnishes-and-preparations"], 'beef', 'bowl', 45, 'Remove the thin outer skin or membrane and soak in cold water, changing the water often, an hour or more.', [I('lemon juice', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('brains', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('sweetbreads', 1, '', 'Meat & Seafood')], ['Remove the thin outer skin or membrane and soak in cold water, changing the water often, an hour or more.', 'Cover with salted boiling water, acidulated with lemon juice and flavored with vegetables, and cook, just below the boiling-point, twenty minutes.', 'They are then ready for preparation in any of the ways mentioned.', 'Tie the brains in a cloth before cooking.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0008', 'How to Pickle Nasturtium Seeds', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'As the seeds are gathered wash and dry them; then put them into vinegar to which salt (half a teaspoonful to a pint) has been added.', [I('salt', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('nasturtium', 1, '', 'Pantry'), I('nasturtium seeds', 1, '', 'Pantry')], ['As the seeds are gathered wash and dry them; then put them into vinegar to which salt (half a teaspoonful to a pint) has been added.', 'When a sufficient quantity has been collected, scald fresh vinegar, add salt as before, and the seeds from which the first vinegar has been drained.', 'Pour scalding hot into bottles, having the seeds completely covered with vinegar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0009', 'Nasturtium Vinegar', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'Fill a quart jar loosely with nasturtium blossoms fully blown; add a shallot and one-third a clove of garlic, both finely chopped, half a red pepper, and cold cider vinegar to fill the jar; cover closely and set aside…', [I('garlic', 0.3333333333333333, 'clove', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('cider vinegar', 1, '', 'Pantry'), I('shallot', 1, '', 'Produce'), I('nasturtium', 1, '', 'Pantry'), I('nasturtium blossoms', 1, '', 'Pantry')], ['Fill a quart jar loosely with nasturtium blossoms fully blown; add a shallot and one-third a clove of garlic, both finely chopped, half a red pepper, and cold cider vinegar to fill the jar; cover closely and set aside two months.', 'Dissolve a teaspoonful of salt in the vinegar, then strain and filter.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0010', 'Tarragon Vinegar', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'Fill a fruit jar with fresh tarragon leaves or shoots, putting them in loosely; add the thin _yellow_ paring of half a lemon with two or three cloves, and fill the jar with white wine or cider vinegar.', [I('cloves', 3, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('cider vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('wine', 1, '', 'Pantry'), I('white wine', 1, '', 'Pantry')], ['Fill a fruit jar with fresh tarragon leaves or shoots, putting them in loosely; add the thin _yellow_ paring of half a lemon with two or three cloves, and fill the jar with white wine or cider vinegar.', 'Screw down the cover tightly, and allow the jar to stand in the sun two weeks; strain the vinegar through a cloth, pressing out the liquid from the leaves; then pass through filter paper, and bottle for future use.', 'If a quantity be prepared, it were better to seal the bottles.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0011', 'Fines Herbes Vinegar', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'INGREDIENTS.', [I('tarragon vinegar', 2, 'cups', 'Pantry'), I('garden cress', 2, 'tablespoonfuls', 'Produce'), I('sweet marjoram', 2, 'tablespoonfuls', 'Pantry'), I('garlic', 2, 'cloves', 'Produce'), I('small green capsicums', 4, '', 'Pantry'), I('shallots', 2, '', 'Produce'), I('cloves', 1, '', 'Herbs & Spices')], ['Mix the ingredients in a pint fruit jar, cover closely, and set in the sun; after two weeks strain, pass through filter paper and store in tightly corked bottles.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0012', 'Fines Herbes Vinegar, No. 2', 'American', ["section-garnishes-and-preparations"], 'veg', 'bowl', 45, 'INGREDIENTS.', [I('tarragon vinegar', 1, 'pint', 'Pantry'), I('seeds of garden cress', 2, 'tablespoonfuls', 'Produce'), I('celery seeds', 2, 'tablespoonfuls', 'Produce'), I('parsley seeds', 2, 'tablespoonfuls', 'Produce'), I('capsicums', 4, '', 'Pantry'), I('garlic', 2, 'cloves', 'Produce'), I('cloves', 1, '', 'Herbs & Spices'), I('garden cress', 1, '', 'Produce')], ['Prepare as in preceding recipe.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0013', 'French Dressing', 'American', ["section-salad-dressings"], 'veg', 'green', 45, 'INGREDIENTS.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('cayenne or paprica', 1, 'grains', 'Herbs & Spices'), I('pepper', 0.25, 'teaspoonful', 'Produce'), I('vinegar or lemon juice', 1, 'tablespoonfuls', 'Produce'), I('oil', 6, 'tablespoonfuls', 'Pantry'), I('prepared mustard', 0.5, 'teaspoonful', 'Herbs & Spices'), I('onion juice', 0.5, 'teaspoonful', 'Produce'), I('garlic', 1, '', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('vegetables', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Mix the condiments, add the oil and mix again; then add the acid, a few drops at a time, and beat until an emulsion is formed; then pour over the vegetables, toss with the spoon and fork, and serve.', 'In Chicago a method has obtained that is well worth a trial: Put a bit of ice into the bowl with the condiments, and, by means of a fork pressed against or into this, use in mixing.', 'Pour the oil over the vegetables, toss, until the oil is evenly distributed, and dust with salt and pepper; then add the acid and toss again.', 'When the salad is prepared at the table, the vegetables may be dressed in a bowl, then arranged on the serving-dish; or, if but one vegetable is used, it is preferable to serve from the dish in which it is dressed.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0014', 'Claret Dressing', 'American', ["section-salad-dressings"], 'veg', 'green', 45, '(_For lettuce or fruit salad.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('claret', 1, 'tablespoonful', 'Pantry'), I('lemon juice or vinegar', 1, 'tablespoonful', 'Produce'), I('pepper', 1, '', 'Produce'), I('paprica', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce')], ['Mix half a teaspoonful of salt, a dash of pepper, white or paprica, and four tablespoonfuls of oil; add gradually one tablespoonful of claret and one tablespoonful of lemon juice or vinegar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0015', 'Mayonnaise Dressing', 'American', ["section-salad-dressings"], 'eggs', 'green', 45, 'INGREDIENTS.', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('olive oil', 1, 'pint', 'Produce'), I('vinegar', 2, 'tablespoonfuls', 'Pantry'), I('lemon juice', 2, 'tablespoonfuls', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('cayenne or paprica', 1, 'grains', 'Herbs & Spices'), I('mustard', 1, 'teaspoonful', 'Herbs & Spices'), I('powdered sugar', 1, 'teaspoonful', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('mayonnaise', 1, '', 'Pantry')], ['An amateur will probably find it helpful to have all the utensils and ingredients thoroughly chilled, but the professional salad-maker thinks it expedient to have the ingredients and utensils of the same temperature as the room in which the dressing is to be served.', 'Beat the yolks with a small wooden spoon or silver fork, add the condiments and mix again; then add one teaspoonful of vinegar, and, when well mixed with the other ingredients, add the oil, at first drop by drop.', 'When the mixture has become of good consistency the oil may be added faster.', 'When it is too thick to beat well, add a little of the lemon juice, then more oil, and so on alternately, until the ingredients are used.', 'If a very heavy dressing is desired, as when it is to be put on with forcing-bag and tubes for a garnish, an additional half a cup of oil may be added without increasing the quantity of acid.', 'In preparing mayonnaise, there is absolutely no danger of curdling, if the eggs be fresh and the oil be added slowly, especially if the materials and utensils have been thoroughly chilled.', 'If the yolks do not thicken when beaten with the condiments, but spread out over the bowl, you have sufficient indication that they will not thicken upon the addition of the oil, and it were better to select others and begin again.', 'Take care to add the teaspoonful of acid to the yolks and condiments before beginning to drop in the oil, as this lessens the liability of the mixture to curdle.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0016', 'How to Make Mayonnaise in Quantity', 'American', ["section-salad-dressings"], 'eggs', 'dessert', 45, 'If four quarts or more of dressing be required, make the full amount at one time; cut down the number of yolks to one for each pint of oil, but keep the usual proportions of the other ingredients.', [I('oil', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('mayonnaise', 1, '', 'Pantry')], ['If four quarts or more of dressing be required, make the full amount at one time; cut down the number of yolks to one for each pint of oil, but keep the usual proportions of the other'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0017', 'Curdled Mayonnaise', 'American', ["section-salad-dressings"], 'eggs', 'green', 45, 'Occasionally a mayonnaise will assume a curdled appearance; under such circumstances, often the addition of a very little of white of egg or a few drops of lemon juice, with thorough beating, will cause the sauce to…', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('lemon juice', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry')], ['Occasionally a mayonnaise will assume a curdled appearance; under such circumstances, often the addition of a very little of white of egg or a few drops of lemon juice, with thorough beating, will cause the sauce to resume its former smoothness.', 'In case it does not become smooth, put the yolk of an egg into a cold bowl, beat well, and add to it the curdled mixture, a little at a time.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0018', 'Red Mayonnaise', 'American', ["section-salad-dressings"], 'veg', 'green', 45, 'Mix a level teaspoonful of Italian tomato pulp with a teaspoonful of mayonnaise dressing, and when well blended beat very thoroughly into a cup or more of the dressing, or add dressing until the desired tint is attained.', [I('tomato', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Mix a level teaspoonful of Italian tomato pulp with a teaspoonful of mayonnaise dressing, and when well blended beat very thoroughly into a cup or more of the dressing, or add dressing until the desired tint is attained.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0019', 'Red Mayonnaise, No. 2', 'American', ["section-salad-dressings"], 'seafood', 'green', 45, '(_For fish.', [I('fish', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry')], ['Pound dried lobster coral in a mortar, sift, and add gradually to the dressing, to secure the shade desired.', 'Or, after the salad is arranged in the bowl, or in nests, mask the top with mayonnaise of the usual color, and sift the coral over the centre, leaving a ring of yellow around the edge.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0020', 'Sauce Tartare', 'American', ["section-salad-dressings"], 'veg', 'dessert', 45, 'Make a mayonnaise dressing, using tarragon vinegar.', [I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('powdered tarragon', 0.25, 'teaspoonful', 'Pantry'), I('shallot', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('capers', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('tarragon', 1, '', 'Pantry'), I('cucumber', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('cucumber pickles', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Make a mayonnaise dressing, using tarragon vinegar.', 'To each cup of dressing add one shallot, chopped fine, two tablespoonfuls, each, of finely chopped capers, olives and cucumber pickles, one tablespoonful of chopped parsley, and one-fourth a teaspoonful of powdered tarragon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0021', 'Sardine Mayonnaise', 'American', ["section-salad-dressings"], 'fish', 'green', 45, 'Skin and bone three sardines and pound them to a pulp; sift the cooked yolks of three eggs and add to the pulp; work until smooth, then add to one cup of mayonnaise dressing.', [I('mayonnaise dressing', 1, 'cup', 'Pantry'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('sardines', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('sardine', 1, '', 'Meat & Seafood')], ['Skin and bone three sardines and pound them to a pulp; sift the cooked yolks of three eggs and add to the pulp; work until smooth, then add to one cup of mayonnaise dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0022', 'Jelly Mayonnaise', 'American', ["section-salad-dressings"], 'fish', 'dessert', 45, '(_Used for masking cold fish or salads, or as a garnish with forcing-bag and tube.', [I('chilled but liquid aspic', 0.3333333333333333, 'cup', 'Pantry'), I('fish', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['To a cup of mayonnaise dressing beat in gradually from two tablespoonfuls to one-third a cup of chilled but liquid aspic.', 'More seasoning may be needed.', 'Apply to a cold surface, or chill before using with forcing-bag.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0023', 'Livournaise Sauce', 'American', ["section-salad-dressings"], 'seafood', 'green', 45, 'To a cup of mayonnaise dressing add a grating of nutmeg, one tablespoonful of chopped parsley and the pulp of eight anchovies.', [I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('anchovies', 8, '', 'Pantry'), I('nutmeg', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['To a cup of mayonnaise dressing add a grating of nutmeg, one tablespoonful of chopped parsley and the pulp of eight anchovies.', 'To prepare the anchovies, wash, dry, remove skin and bones and pound to a pulp in a mortar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0024', 'Boiled Dressing for Chicken Salad', 'American', ["section-salad-dressings"], 'chicken', 'dessert', 45, 'INGREDIENTS.', [I('chicken stock, well reduced', 0.5, 'cup', 'Meat & Seafood'), I('vinegar', 0.5, 'cup', 'Pantry'), I('mixed mustard', 0.25, 'cup', 'Herbs & Spices'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('paprica', 0.5, 'teaspoonful', 'Pantry'), I('egg yolks', 5, '', 'Dairy & Eggs'), I('oil', 0.5, 'cup', 'Pantry'), I('thick, sweet cream', 0.5, 'cup', 'Dairy & Eggs'), I('chicken stock', 0.5, 'cup', 'Meat & Seafood'), I('eggs', 5, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('boiled dressing', 1, '', 'Pantry')], ['Simmer the liquor in which a fowl has been cooked, until it is well reduced.', 'Put the stock, vinegar and mustard into a double boiler, and add the salt and pepper.', 'Beat the yolks of the eggs and add carefully to the hot mixture, cooking in the same manner as a boiled custard.', 'When cold and ready to serve, beat in with a whisk the oil, and then fold in the cream, beaten stiff with a Dover egg-beater.', 'Melted butter, added before the dressing is cold, may be substituted for the oil.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0025', 'Boiled Salad Dressing', 'American', ["section-salad-dressings"], 'eggs', 'dessert', 45, 'INGREDIENTS.', [I('mustard', 1, 'teaspoonful', 'Herbs & Spices'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('melted butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('vinegar', 2, 'tablespoonfuls', 'Pantry'), I('thick cream', 0.5, 'cup', 'Dairy & Eggs'), I('lemon juice', 2, 'tablespoonfuls', 'Produce'), I('eggs', 3, '', 'Dairy & Eggs'), I('salad dressing', 1, '', 'Pantry')], ['Mix together the mustard, salt and paprica, and add the yolks of eggs; stir well and add slowly the butter, vinegar and lemon juice, and cook in the double boiler until thick as soft custard.', 'When cool and ready to serve, add the cream, beaten stiff with the Dover egg-beater.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0026', 'Cream Salad Dressing', 'American', ["section-salad-dressings"], 'eggs', 'green', 45, 'INGREDIENTS.', [I('thick cream', 0.75, 'cup', 'Dairy & Eggs'), I('vinegar or lemon juice', 2, 'tablespoonfuls', 'Produce'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('white pepper and paprica', 1, 'dash', 'Produce'), I('white pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('horseradish', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('radish', 1, '', 'Produce'), I('salad dressing', 1, '', 'Pantry')], ['Add the seasonings to the cream and beat with a Dover egg-beater until smooth and light.', 'Add a scant fourth a cup of grated horseradish, for a change.', 'The radish should be freshly grated, and added to the cream after it is beaten.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0027', 'Dressing for Cole-Slaw', 'American', ["section-salad-dressings"], 'eggs', 'green', 45, 'Beat the yolks of three eggs with half a teaspoonful of made mustard, a dash of pepper and one-fourth a teaspoonful of salt; add one-third a cup of vinegar and two tablespoonfuls of butter, and cook over hot water until…', [I('made mustard', 0.5, 'teaspoonful', 'Herbs & Spices'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('vinegar', 0.3333333333333333, 'cup', 'Pantry'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('mustard', 1, '', 'Herbs & Spices'), I('yolks', 1, '', 'Dairy & Eggs')], ['Beat the yolks of three eggs with half a teaspoonful of made mustard, a dash of pepper and one-fourth a teaspoonful of salt; add one-third a cup of vinegar and two tablespoonfuls of butter, and cook over hot water until slightly thickened.', 'Set aside to become cold before using.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0028', 'Bacon Sauce', 'American', ["section-salad-dressings"], 'pork', 'green', 45, 'Heat five tablespoonfuls of bacon fat; cook in it two tablespoonfuls of flour and a dash of paprica; add five tablespoonfuls of vinegar and half a cup of water; stir until boiling; then beat in the beaten yolks of two…', [I('bacon fat', 5, 'tablespoonfuls', 'Meat & Seafood'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('vinegar', 5, 'tablespoonfuls', 'Pantry'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('endive', 1, '', 'Produce'), I('bacon', 1, '', 'Meat & Seafood'), I('corn', 1, '', 'Produce')], ['Heat five tablespoonfuls of bacon fat; cook in it two tablespoonfuls of flour and a dash of paprica; add five tablespoonfuls of vinegar and half a cup of water; stir until boiling; then beat in the beaten yolks of two eggs, and a little salt if necessary.', 'Do not allow the sauce to boil after the eggs are added.', 'Add to salad after it has become thoroughly cold.', 'Good with dandelion, endive, chicory, corn salad or lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0029', 'Hollandaise Sauce', 'American', ["section-salad-dressings"], 'fish', 'green', 45, 'Beat half a cup of butter to a cream; add the yolks of four eggs, one at a time, beating in each thoroughly; add one-fourth a teaspoonful of salt, a dash of paprica or cayenne, and half a cup of boiling water.', [I('butter to a cream', 0.5, 'cup', 'Dairy & Eggs'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('egg yolks', 4, '', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('cayenne', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('hollandaise', 1, '', 'Pantry')], ['Beat half a cup of butter to a cream; add the yolks of four eggs, one at a time, beating in each thoroughly; add one-fourth a teaspoonful of salt, a dash of paprica or cayenne, and half a cup of boiling water.', 'Cook over hot water until thick, adding gradually the juice of half a lemon.', 'Chill before using.', 'This is good, especially for a fish salad, in the place of mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0030', 'Bernaise Sauce', 'American', ["section-salad-dressings"], 'veg', 'green', 45, 'Use tarragon instead of plain vinegar, omit the water, with the exception of one tablespoonful, and the hollandaise becomes bernaise sauce.', [I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('mayonnaise', 1, '', 'Pantry'), I('hollandaise', 1, '', 'Pantry'), I('bernaise', 1, '', 'Pantry')], ['Use tarragon instead of plain vinegar, omit the water, with the exception of one tablespoonful, and the hollandaise becomes bernaise sauce.', 'Oil may be used in the place of butter.', 'The sauce resembles a firm mayonnaise, and, as it keeps its shape well, is particularly adapted for garnishing with pastry bag and tube.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0031', 'Lettuce Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Wash and drain the lettuce leaves; toss lightly, so as to remove every drop of water.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('romaine', 1, '', 'Produce')], ['Wash and drain the lettuce leaves; toss lightly, so as to remove every drop of water.', 'Sprinkle them with oil, a few drops at a time, tossing the leaves about with spoon and fork after each addition.', 'When each leaf glistens with oil (there should be no oil in the bottom of the bowl) shake over them a few drops of vinegar, then dust with salt and freshly ground pepper.', 'The cutting of lettuce is considered a culinary sin; but, when the straight-leaved lettuce, or the Romaine, is to be used, better effects, at least as far as appearance is concerned, will be produced, if the lettuce be cut into ribbons.', 'To do this, wash the lettuce carefully, without removing the leaves from the stem; fold together across the centre, and with a sharp, thin knife cut into ribbons _less_ than half an inch in width.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0032', 'Endive Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Prepare as lettuce salad, first rubbing over the bowl with a clove of garlic cut in halves.', [I('garlic', 1, '', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('chives', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('endive', 1, '', 'Produce')], ['Prepare as lettuce salad, first rubbing over the bowl with a clove of garlic cut in halves.', 'A few sprigs of chives, chopped fine, are exceedingly palatable, sprinkled over a lettuce, endive, string-bean, or other bean salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0033', 'A Few Combinations', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'dessert', 45, 'Dress each vegetable separately with the dressing; then arrange upon the serving-dish.', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('vegetable', 1, 'pint', 'Pantry'), I('pepper', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('chives', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('powdered tarragon', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs'), I('neufchatel cheese', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('watercress', 1, '', 'Produce'), I('peppergrass', 1, '', 'Produce'), I('cabbage', 1, '', 'Produce'), I('cauliflower', 1, '', 'Pantry'), I('cucumbers', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('onions', 1, '', 'Produce'), I('radish', 1, '', 'Produce'), I('radishes', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('artichoke', 1, '', 'Pantry'), I('brussels sprouts', 1, '', 'Pantry'), I('spinach', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('green peppers', 1, '', 'Produce'), I('sweet peppers', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('pecan', 1, '', 'Pantry'), I('pecan nuts', 1, '', 'Produce'), I('chestnuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('sprouts', 1, '', 'Pantry'), I('neufchatel', 1, '', 'Pantry')], ['Dress each vegetable separately with the dressing; then arrange upon the serving-dish.', 'Or, have the salad arranged upon the serving-dish and pour the dressing over all; then toss together and serve.', 'About three tablespoonfuls of oil, with other ingredients in accordance, will be needed for one pint of vegetable.', '1.', 'Lettuce, tomatoes cut in halves, sprinkled with powdered tarragon, and parsley or chives.', '2.', 'Lettuce, moulded spinach and fine-chopped beets.', '3.', 'Lettuce, Boston baked beans and chives.', '4.', 'Lettuce and peppergrass.', '5.', 'Lettuce, shredded sweet peppers or pimentos, and sliced pecan nuts or almonds.', '6.', 'Lettuce, tomatoes stuffed with peas or string beans cut small, and chives chopped fine.', '7.', 'Lettuce, asparagus tips and sliced radishes.', 'Arrange the lettuce at the edge of dish, inside a ring of radishes sliced thin, without removing the red skins; centre of asparagus tips, with radish cut to resemble a flower.', '8.', 'Lettuce, shredded tomatoes and shredded green peppers.', '9.', 'Shredded lettuce, English walnuts, and almonds or cooked chestnuts, sliced.', '10.', 'Lettuce, Neufchatel cheese in slices and shredded pimentos.', '11.', 'Lettuce, cauliflower, string beans and shredded pimentos.', '12.', 'Lettuce or cress, artichoke slices and powdered tarragon.', '13.', 'Shredded cabbage and shredded green peppers.', '14.', 'Cauliflower broken into flowerets, string beans cut into small pieces, and beets cut in fancy shapes or chopped.', 'Arrange each vegetable in a mass by itself; surround with lettuce.', '15.', 'Cucumbers and new onions, sliced.', '16.', 'Watercress, diced boiled beets, and olives in centre.', '17.', 'Lettuce, Brussels sprouts and chopped pepper.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0034', 'Lentil Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'dessert', 45, 'Soak the lentils over night; wash and rinse thoroughly, then cook until tender, adding hot water as needed.', [I('oil', 5, 'tablespoonfuls', 'Pantry'), I('tarragon vinegar', 2, 'tablespoonfuls', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('capers', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('chives', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('lentils', 1, '', 'Pantry'), I('pickles', 1, '', 'Pantry'), I('cucumber pickles', 1, '', 'Produce')], ['Soak the lentils over night; wash and rinse thoroughly, then cook until tender, adding hot water as needed.', 'Drain, and when cold mix with each pint of lentils about five tablespoonfuls of oil, two tablespoonfuls of tarragon vinegar and one teaspoonful, each, of capers, parsley, chives and cucumber pickles, all, save the capers, chopped fine.', 'Serve in a mound, on a bed of lettuce leaves.', 'Garnish with heart leaves of lettuce at the top and sections of tomato, or diamonds of tomato jelly, at the base.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0035', 'White-Bean Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Toss one pint of white beans, cooked, with one tablespoonful of vinegar and three tablespoonfuls of oil, a little salt and a dash of cayenne or paprica.', [I('white beans', 1, 'pint', 'Produce'), I('vinegar', 1, 'tablespoonful', 'Pantry'), I('oil', 3, 'tablespoonfuls', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('chives', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('pim-ola', 1, '', 'Pantry'), I('pimentos', 1, '', 'Pantry')], ['Toss one pint of white beans, cooked, with one tablespoonful of vinegar and three tablespoonfuls of oil, a little salt and a dash of cayenne or paprica.', 'Arrange in a mound on a bed of shredded lettuce, and sprinkle with chives, parsley and pimentos, all finely chopped.', 'Finish the top of the salad with a large pim-ola.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0036', 'Potato Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'dessert', 45, '(MISS COHEN.', [I('cold boiled potatoes', 3, 'cups', 'Produce'), I('pecan nuts', 1, 'cup', 'Produce'), I('oil', 5, 'tablespoonfuls', 'Pantry'), I('salt', 1, 'tablespoonful', 'Herbs & Spices'), I('onion juice', 0.5, 'teaspoonful', 'Produce'), I('cayenne', 1, 'dash', 'Herbs & Spices'), I('or 3 tablespoonfuls of vinegar', 2, '', 'Pantry'), I('Watercress', 1, '', 'Produce'), I('boiled potatoes', 3, 'cups', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('potato', 1, '', 'Produce')], ['Mix the potatoes and nuts, add the oil and mix again; add the other seasonings, and, when well mixed, set aside in a cool place an hour or more.', 'Remove the coarse stalks from two bunches of watercress that have been well washed and dried.', 'Season with French dressing and arrange in a wreath about the edge of the salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0037', 'Potato Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'eggs', 'green', 45, '(CARRIE M.', [I('cold boiled potatoes', 12, '', 'Produce'), I('cooked eggs', 4, '', 'Dairy & Eggs'), I('small Bermuda onions', 2, '', 'Produce'), I('white pepper', 1, 'saltspoonful', 'Produce'), I('salt', 2, 'teaspoonfuls', 'Herbs & Spices'), I('oil', 6, 'tablespoonfuls', 'Pantry'), I('vinegar', 6, 'tablespoonfuls', 'Pantry'), I('powdered sugar', 0.5, 'teaspoonful', 'Pantry'), I('parsley', 1, '', 'Produce'), I('potato', 1, '', 'Produce')], ['Cut the potatoes into dice and chop the eggs fine.', 'Chop the onions, or slice them very thin.', 'Sprinkle the potatoes, eggs and onions with the salt and pepper, and mix thoroughly.', 'Pour the oil gradually over the mixture, stirring and tossing continually; lastly, mix with the other ingredients the vinegar, in which the sugar has been dissolved.', 'Sprinkle chopped parsley over the top.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0038', 'Potato Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'eggs', 'green', 45, 'INGREDIENTS.', [I('cubes of cold boiled potatoes', 1, 'quart', 'Produce'), I('salt', 1.5, 'teaspoonfuls', 'Herbs & Spices'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('vinegar', 3, 'tablespoonfuls', 'Pantry'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('Capers', 1, '', 'Pantry'), I('beets', 1, '', 'Produce'), I('whites', 1, '', 'Pantry'), I('yolks of eggs', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('pepper', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('potato', 1, '', 'Produce')], ['To the potato cubes add the salt, pepper and oil, and mix thoroughly; add the vinegar and mix again.', 'Pile the cubes in a mound in the salad-bowl.', 'Mark out the surface of the mound into quarters with capers; fill in two opposite sections with chopped beet; use chopped whites of eggs in a third, and sifted yolks of eggs in the fourth section.', 'Finish with a border of parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0039', 'Potato-and-Nasturtium Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, '(E.', [I('potatoes', 1, 'quart', 'Produce'), I('chopped gherkins', 0.5, 'cup', 'Meat & Seafood'), I('tender nasturtium shoots, cut in bits', 1, 'cup', 'Pantry'), I('pickled nasturtium seeds', 2, 'tablespoonfuls', 'Pantry'), I('Onion juice or garlic', 1, '', 'Produce'), I('oil', 6, 'tablespoonfuls', 'Pantry'), I('vinegar', 5, 'tablespoonfuls', 'Pantry'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('tender nasturtium shoots', 1, 'cup', 'Pantry'), I('onion juice', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('nasturtium blossoms', 1, '', 'Pantry'), I('nasturtium seeds', 1, '', 'Pantry'), I('potato', 1, '', 'Produce')], ['Mix the potatoes, gherkins, nasturtium shoots and seeds in a bowl rubbed over with garlic; add the oil, vinegar and seasonings, and mix again.', 'Pile in a mound on a serving-dish, dust with chopped parsley, and garnish with a wreath of nasturtium blossoms and leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0040', 'Stuffed Beets', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Boil new beets, of even size, until tender.', [I('chop fine a cucumber', 5, 'cups', 'Produce'), I('oil', 2, 'tablespoonfuls', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('radish', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry')], ['Boil new beets, of even size, until tender.', 'Set aside for some hours, or over night, covered with vinegar.', 'When ready to serve, rub off the skin, scoop out the centre of each to form a cup, and arrange the cups on lettuce leaves.', 'For each five cups chop fine a cucumber.', 'Make a French dressing of two tablespoonfuls of oil, half a tablespoonful (scant) of vinegar, one-fourth a teaspoonful, each, of paprica and salt.', 'Stir the dressing into the cucumber and fill the beets with the mixture.', 'Of the beet removed to form the cups, cut slices and stamp out from these stars or other fanciful shapes, and use to decorate the top of each cup.', 'Chopped radish, cress, olives or celery are all admissible for a filling.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0041', 'Salad of Brussels Sprouts and Beets', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Soak the sprouts in salted water; then drain and cook in salted boiling water about fifteen minutes, or until tender; drain and cool.', [I('beet', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('sprouts', 1, '', 'Pantry'), I('pickled beet', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('brussels sprouts', 1, '', 'Pantry')], ['Soak the sprouts in salted water; then drain and cook in salted boiling water about fifteen minutes, or until tender; drain and cool.', 'Dress with French dressing and pile in a mound.', 'Finish the top with a fanciful-shaped figure cut from a slice of pickled beet, and place a wreath of cooked beet, chopped and seasoned with French dressing, about the whole.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0042', 'Macedoine Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'dessert', 45, 'Cut pieces of carrot and turnip one inch long and half an inch thick.', [I('short stalks of asparagus', 0.5, 'dozen', 'Produce'), I('beet', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('carrots', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('turnip', 1, '', 'Produce'), I('turnips', 1, '', 'Produce'), I('gelatine', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Cut pieces of carrot and turnip one inch long and half an inch thick.', 'Put over the fire in boiling water and bring quickly to the boiling-point; drain, cover with fresh water, and cook until tender; score the top of each piece and insert an asparagus point.', 'Dip the pieces in a little melted gelatine and set alternately in a circle on the serving-dish.', 'Have carrots cut in small cubes or straws, turnips and beet root the same, green string beans cut in small pieces, asparagus and peas, all cooked separately until tender.', 'Mix with French dressing and dispose inside the circle.', 'Each vegetable may be massed by itself, or all may be mixed together.', 'Finish the top with half a dozen short stalks of asparagus.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0043', 'Tomato-and-Onion Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Peel and shred four tomatoes; slice thinly a very mild onion and separate into rings; dress freely with oil and tarragon vinegar, and season with salt and pepper.', [I('tomatoes', 4, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('green peppers', 1, '', 'Produce'), I('tomato', 1, '', 'Produce')], ['Peel and shred four tomatoes; slice thinly a very mild onion and separate into rings; dress freely with oil and tarragon vinegar, and season with salt and pepper.', 'Serve on lettuce leaves, sprinkling the whole with fine-chopped parsley and green peppers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0044', 'Endive,-Tomato-and-Green-String-Bean Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Dress the well-blanched stalks of a head of endive, three tomatoes, peeled, cut in halves and chilled, and a cup of cold cooked string beans, separately, with French dressing, using in the dressing tarragon vinegar and…', [I('tomatoes', 3, '', 'Produce'), I('onion juice', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('endive', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['Dress the well-blanched stalks of a head of endive, three tomatoes, peeled, cut in halves and chilled, and a cup of cold cooked string beans, separately, with French dressing, using in the dressing tarragon vinegar and a few drops of onion juice; then arrange on a serving-dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0045', 'Cucumber Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, '(_German style.', [I('salt', 1, '', 'Herbs & Spices'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('cucumber', 1, '', 'Produce'), I('cucumbers', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry')], ['Pare large cucumbers and cut them into thin slices; cut each slice round and round so as to form a long, narrow curling strip.', 'Let these strips stand two hours in salted ice water, drain, and dry in a soft cloth.', 'Serve with French dressing.', 'Toss first in the oil, then add the condiments, and lastly the vinegar.', 'Americans would prefer to omit the salt from the ice water, as it softens the cucumber.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0046', 'Cucumber Salad for Fish Course', 'American', ["section-vegetable-salads-with-french-dressing"], 'fish', 'green', 45, 'With a handy slicer remove the outside rind from the cucumbers, cut in thin slices, and let stand in ice-water to chill.', [I('oil', 6, 'tablespoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('cider vinegar', 1, '', 'Pantry'), I('cucumbers', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('cucumber', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood')], ['With a handy slicer remove the outside rind from the cucumbers, cut in thin slices, and let stand in ice-water to chill.', 'Wipe dry, and arrange the slices in the salad bowl in the form of a Greek cross.', 'Make a French dressing, in the proportion of three tablespoonfuls of cider vinegar to six tablespoonfuls of oil, half a teaspoonful of salt, and a dash of paprica.', 'Rub the inside of the salad bowl with the cut side of an onion before the salad is disposed in it.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0047', 'Cooked Vegetable Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'veg', 'green', 45, 'Dress cooked kidney beans, peas, and balls cut from potatoes, each separately with French dressing, to which a few drops of onion juice have been added.', [I('onion juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Dress cooked kidney beans, peas, and balls cut from potatoes, each separately with French dressing, to which a few drops of onion juice have been added.', 'Dispose upon a serving-dish and let stand in a cool place an hour or more.', 'Garnish at serving with heart leaves of lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0048', 'Potato Salad', 'American', ["section-vegetable-salads-with-french-dressing"], 'eggs', 'soup', 45, '(_German Style.', [I('potato slices or cubes', 1, 'quart', 'Produce'), I('beef broth', 0.5, 'cup', 'Meat & Seafood'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('paprica', 0.5, 'teaspoonful', 'Pantry'), I('oil', 8, 'tablespoonfuls', 'Pantry'), I('grated onion', 1, 'tablespoonful', 'Produce'), I('hard boiled eggs', 2, '', 'Dairy & Eggs'), I('vinegar', 4, 'tablespoonfuls', 'Pantry'), I('mustard', 1, 'teaspoonful', 'Herbs & Spices'), I('sugar', 1, 'teaspoonful', 'Pantry'), I('mushrooms', 1, 'cup', 'Produce'), I('egg whites', 1, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('potatoes', 1, '', 'Produce')], ['Boil the potatoes without paring.', 'German potatoes, which are waxy rather than mealy, may be procured in large cities especially for salads.', 'Peel the potatoes and cut them while hot into slices or cubes; pour over them as much beef broth as they will readily absorb and sprinkle with the salt and pepper, the oil and onion; mix lightly and set aside for some hours.', 'Then add the whites of the eggs chopped fine, the yolks passed through a sieve, and mix with the rest of the oil, stirred with the vinegar into the mustard and sugar.', 'After disposing in the dish, sprinkle with the parsley.', 'If mushrooms be at hand, simmer ten or fifteen minutes in broth, break in pieces, and add to the salad with the egg.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0049', 'Cauliflower Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Soak the cauliflower in salted water an hour; cook in boiling salted water until tender; drain and chill, then sprinkle with French dressing and set aside for half an hour.', [I('parsley', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('cauliflower', 1, '', 'Pantry'), I('pimentos', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Soak the cauliflower in salted water an hour; cook in boiling salted water until tender; drain and chill, then sprinkle with French dressing and set aside for half an hour.', 'Sever the flowerets partly from the stalk, but so as not to change their relative positions, and place on a serving-dish; put heart leaves of lettuce between the flowerets and about the base of the vegetable; pour a cup of mayonnaise dressing over the whole, and sprinkle with pimentos or fine-chopped parsley.', 'In serving, separate the flowerets with a sharp knife.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0050', 'Tomatoes Stuffed with Nuts and Celery', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Peel the tomatoes; cut out a circular piece at the stem end of each and scoop out the flesh so as to form cups.', [I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('walnut', 1, '', 'Produce'), I('pecan', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('nuts', 1, '', 'Produce')], ['Peel the tomatoes; cut out a circular piece at the stem end of each and scoop out the flesh so as to form cups.', 'Chill thoroughly, then fill with English walnut or pecan meats, broken into pieces, and celery, cut into small pieces and mixed with mayonnaise.', 'Serve on lettuce leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0051', 'Stuffed-Tomato Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, 'INGREDIENTS.', [I('smooth, small-sized tomatoes', 6, '', 'Produce'), I('chicken, veal or tongue', 6, 'tablespoonfuls', 'Meat & Seafood'), I('peas', 6, 'tablespoonfuls', 'Produce'), I('olives', 3, '', 'Produce'), I('gherkins', 3, '', 'Pantry'), I('capers', 2, 'tablespoonfuls', 'Pantry'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('Mayonnaise dressing', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('tomato', 1, '', 'Produce')], ['Remove a round piece from the stem end of the tomatoes and scoop out the seeds and centre.', 'Chill thoroughly.', 'When ready to serve, mix together the solid part removed from the tomatoes, cut fine, and the other ingredients; season to taste with salt and pepper, adding also mayonnaise to hold the mixture together.', 'With this fill the tomatoes, put them in nests of lettuce or cress, and force a star of mayonnaise on the top of each tomato.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0052', 'Tomato Salad, Horseradish Dressing', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Plunge the tomatoes, placed in a wire basket, into a kettle of hot water; remove at once and rub off the skin; chill thoroughly and cut in halves.', [I('horseradish', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('cream dressing', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce')], ['Plunge the tomatoes, placed in a wire basket, into a kettle of hot water; remove at once and rub off the skin; chill thoroughly and cut in halves.', 'Serve on lettuce leaves with a star of cream dressing, seasoned with grated horseradish, on the top of each slice.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0053', 'Tomato-and-Sweetbread Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'beef', 'green', 45, 'Cook two sweetbreads as directed on another page, or braise with vegetables.', [I('sweetbreads', 2, '', 'Meat & Seafood'), I('parsley', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('sweetbread', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry')], ['Cook two sweetbreads as directed on another page, or braise with vegetables.', 'Cool between two plates bearing a weight.', 'When cold cut into slices and stamp into rounds of suitable size to use with slices of tomato.', 'Cover the slices of sweetbread with chaud-froid sauce and decorate with fine-chopped parsley or sifted yolk of egg; pour over a little melted aspic.', 'When the aspic is set, trim neatly, and arrange each round of sweetbread on a slice of chilled tomato.', 'Serve inside a border of lettuce around a salad made of the trimmings of the sweetbreads and a cucumber cut in cubes and dressed with mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0054', 'Cress,-Cucumber-and-Tomato Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Wash the cress and shake dry; arrange as a bed on a serving-dish, discarding the coarse stems; above this make a smaller bed of cucumbers, cut in slices or dice and dressed with French dressing, using three…', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('cress', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('cucumbers', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['Wash the cress and shake dry; arrange as a bed on a serving-dish, discarding the coarse stems; above this make a smaller bed of cucumbers, cut in slices or dice and dressed with French dressing, using three tablespoonfuls of oil and one of vinegar or lemon juice to a pint of cucumber.', 'Arrange peeled tomatoes, chilled and cut in pieces, upon the cucumbers.', 'Serve with French, cream or mayonnaise dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0055', 'Tomatoes Stuffed with Cucumber', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Peel five tomatoes, cut off the stem ends and scoop out the pulp, thus forming cups; set, turned upside down, in a cool place.', [I('grated horseradish may be used', 2, 'tablespoonfuls', 'Produce'), I('tomatoes', 5, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('horseradish', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs')], ['Peel five tomatoes, cut off the stem ends and scoop out the pulp, thus forming cups; set, turned upside down, in a cool place.', 'Chop fine the solid pulp from the tomatoes and one cucumber, chilled before chopping; stir into a cup of cream dressing and fill the tomatoes with the mixture.', 'Salt and pepper will be needed in addition to that in the dressing.', 'If at hand, a pimento may be chopped with the other ingredients, or two tablespoonfuls of grated horseradish may be used.', 'Serve at once on lettuce leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0056', 'Tomatoes Stuffed with Jelly', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, 'Chop one sweetbread and one cucumber fine.', [I('granulated gelatine', 0.5, 'tablespoonful', 'Pantry'), I('cucumber', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('onion juice', 1, '', 'Produce'), I('capers', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('sweetbread', 1, '', 'Meat & Seafood'), I('brains', 1, '', 'Pantry'), I('gelatine', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs')], ['Chop one sweetbread and one cucumber fine.', 'To each cup (solid and liquid) add one-fourth a teaspoonful, each, of salt and paprica, a few drops of onion juice and a tablespoonful of capers; add also half a tablespoonful of granulated gelatine, soaked in two or three tablespoonfuls of cold water and melted over hot water.', 'Stir until the mixture begins to congeal, then fill into tomatoes prepared as above.', 'Set aside on the ice for half an hour, at least; then serve on lettuce leaves with either mayonnaise, boiled or cream dressing.', 'Calf\'s brains, chicken, veal, tongue or ham may be substituted for the sweetbread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0057', 'Tomatoes Farces a l\'Aspic', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, 'INGREDIENTS.', [I('even-sized ripe tomatoes', 6, '', 'Produce'), I('aspic jelly', 1, 'pint', 'Pantry'), I('lobster meat', 0.5, 'cup', 'Meat & Seafood'), I('capers', 1, 'tablespoonful', 'Pantry'), I('yolks of hard-boiled eggs', 2, '', 'Dairy & Eggs'), I('mayonnaise', 0.5, 'cup', 'Pantry'), I('parsley', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('chicken aspic', 0.5, 'cup', 'Meat & Seafood'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('anchovies', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs')], ['Scoop out the centres of the tomatoes, after removing the skin, and chill thoroughly.', 'Pass the yolks through a sieve, add to the lobster, with the capers, half a cup of mayonnaise and half a cup of chicken aspic, thick and cold, but not set; stir these in a dish standing in ice water until nearly set; then fill the cavities in the tomatoes with the mixture.', 'Brush over the outside of the tomatoes with half-set aspic; when the aspic is set, repeat twice, then set aside on ice for some time before serving.', 'Serve on a bed of lettuce seasoned with French dressing.', 'Garnish each tomato with a sprig of parsley and the salad-dish with blocks of aspic.', 'Anchovies or any cooked fish may be substituted for the lobster.', 'Serve with mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0058', 'Tomato Jelly', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Soak three-fourths a box of gelatine in half a cup of cold water.', [I('tarragon vinegar', 2, 'tablespoonfuls', 'Pantry'), I('cloves', 2, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('bay leaf', 1, '', 'Herbs & Spices'), I('tarragon', 1, '', 'Pantry'), I('celery', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('gelatine', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['Soak three-fourths a box of gelatine in half a cup of cold water.', 'Cook a can of tomatoes, half an onion, a stalk of celery, a bay leaf, two cloves, a teaspoonful of salt and a dash of paprica ten minutes.', 'Add two tablespoonfuls of tarragon vinegar and the gelatine, stir till dissolved, strain, and mould in a ring mould.', 'When cold turn from the mould and fill the centre with'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0059', 'CELERY-AND-NUT SALAD', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Cut fine tender stalks of celery and English walnuts and mix with French dressing.', [I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry')], ['Cut fine tender stalks of celery and English walnuts and mix with French dressing.', 'Garnish the centre of the salad and the border of the jelly with tender leaves of lettuce and bits of curled celery.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0060', 'Tomato-Jelly Salad, No. 2', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Make the jelly and mould as before.', [I('cabbage', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('pecan', 1, '', 'Pantry'), I('pecan nuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('boiled dressing', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['Make the jelly and mould as before.', 'Fill in the centre of the ring with shredded cabbage, pimentos and pecan nuts, mixed with boiled dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0061', 'Tomato Jelly with String Beans', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, 'Cook tiny string beans until tender in boiling salted water; season while hot with onion juice, salt, pepper and tarragon vinegar.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('onion juice', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('chives', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('oysters', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('turkey', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry')], ['Cook tiny string beans until tender in boiling salted water; season while hot with onion juice, salt, pepper and tarragon vinegar.', 'When cold add oil and toss the beans about until each bean is coated with the oil.', 'Fill the centre of the jelly, fashioned in a ring mould, with the beans, and sprinkle over them a fine-chopped pimento.', 'Garnish with lettuce leaves.', 'Fine-chopped chives may be used in the place of the onion juice; they are particularly appropriate in any bean salad.', 'If the beans are large, cut in halves lengthwise and the halves crosswise.', 'Tomato jelly may be served in a ring mould with turkey, oyster, plain chicken, French chicken, and other salads.', 'The oysters should be scalded and drained, then marinated with French dressing.', 'Chicken and turkey should also be marinated before mixing with celery and the mayonnaise or boiled dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0062', 'Tomato-and-Artichoke Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, '(MRS. E.', [I('salt', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('artichoke', 1, '', 'Pantry'), I('artichokes', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['(MRS.', 'E.', 'M.', 'LUCAS, IN BOSTON COOKING-SCHOOL MAGAZINE.)', 'Choose medium-sized tomatoes, firm and smooth skinned.', 'Peel them, cut a slice from the stem end and remove the seeds with a small spoon.', 'Sprinkle the interior of these cups with salt and set on ice.', 'When ready to serve, wipe them dry and fill with artichokes cut into dice and mixed with mayonnaise.', 'Serve on lettuce leaves.', 'Use tarragon vinegar in preparing the dressing.', 'Cook the artichoke hearts until just tender,--no longer,--in salted boiling water, then drain and cool.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0063', 'Artichoke Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, '(_For game.', [I('olive oil', 2, 'tablespoonfuls', 'Produce'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('oranges', 3, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('celery', 1, '', 'Produce'), I('artichokes', 1, '', 'Pantry'), I('olive', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('game', 1, '', 'Pantry'), I('artichoke', 1, '', 'Pantry')], ['(MRS.', 'E.', 'M.', 'LUCAS, IN BOSTON COOKING-SCHOOL MAGAZINE.)', 'Peel three oranges, remove the pith and white skin and slice lengthwise; use an equal amount of tender blanched celery stalks cut into inch lengths.', 'Mix together lightly with two tablespoonfuls of olive oil, one tablespoonful of lemon juice, half a teaspoonful of salt and a quarter a teaspoonful of paprica.', 'Heap together lightly on a serving-dish and surround with cooked hearts of artichokes cut into quarters; wreathe with blanched celery leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0064', 'Artichoke Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, '(_Used as a border for shrimp, lobster, chicken and other salads.', [I('olive oil', 1, 'tablespoonful', 'Produce'), I('tarragon vinegar', 0.5, 'tablespoonful', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('artichokes', 1, '', 'Pantry'), I('olive', 1, '', 'Produce'), I('walnut', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('shrimp', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('artichoke', 1, '', 'Pantry')], ['(MRS.', 'E.', 'M.', 'LUCAS, IN BOSTON COOKING-SCHOOL MAGAZINE.)', 'Cut boiled artichokes into quarter-inch slices and stamp out with a French vegetable cutter.', 'To half a pint add one tablespoonful of olive oil, half a tablespoonful of tarragon vinegar and one-fourth a teaspoonful of salt; toss lightly together and let stand one hour; drain, and arrange as a border with an outer layer of tiny blanched lettuce leaves.', '2.', 'Scoop out the centres of the artichokes and fill with mayonnaise, or with ravigote, tartare or tyrolienne sauce.', 'Serve on lettuce leaves as a border to a meat or fish salad.', '3.', 'Fill the centres with walnut meats, sliced, or tender celery stalks, cut fine and mixed with mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0065', 'Asparagus Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Cut cold cooked asparagus into pieces an inch long, mix lightly with cream dressing and serve, in individual portions, on curly lettuce leaves.', [I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('cream dressing', 1, '', 'Dairy & Eggs')], ['Cut cold cooked asparagus into pieces an inch long, mix lightly with cream dressing and serve, in individual portions, on curly lettuce leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0066', 'Asparagus-and-Salmon Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'fish', 'green', 45, 'Mix cold cooked salmon with mayonnaise, form in a mound and encircle with a wreath of cold cooked asparagus tips dressed with French dressing.', [I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('salmon', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Mix cold cooked salmon with mayonnaise, form in a mound and encircle with a wreath of cold cooked asparagus tips dressed with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0067', 'Asparagus-and-Cauliflower Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Break the cooked cauliflower into its flowerets, dispose in the centre of the serving-dish and surround with a wreath of cooked asparagus tips.', [I('capers', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('cauliflower', 1, '', 'Pantry'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs')], ['Break the cooked cauliflower into its flowerets, dispose in the centre of the serving-dish and surround with a wreath of cooked asparagus tips.', 'Pour over the whole a mayonnaise, a boiled or a cream dressing, and sprinkle with chopped capers or pimentos.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0068', 'Salad of Turnips with Asparagus Tips', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Cook the turnips in boiling salted water until tender; drain, and cut out the centres, forming cups.', [I('lemon', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('radishes', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('turnips', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Cook the turnips in boiling salted water until tender; drain, and cut out the centres, forming cups.', 'Sprinkle the inside with oil and a few grains of salt, and, when the oil is absorbed, pour over the cups a little lemon juice or vinegar.', 'Set aside to become cool.', 'When ready to serve, arrange the cups on shredded lettuce and fill with cooked asparagus tips, cold and mixed with mayonnaise or French dressing, as desired.', 'Peas, flageolets or wax beans, cut fine, may be used instead of the asparagus.', 'Garnish with radishes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0069', 'Green-Pea Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Mix the peas with a cream dressing; serve in nests of lettuce; garnish the top of each nest with a little chopped beet, or a fanciful figure cut from a pickled beet or pimento.', [I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs'), I('pickled beet', 1, '', 'Produce')], ['Mix the peas with a cream dressing; serve in nests of lettuce; garnish the top of each nest with a little chopped beet, or a fanciful figure cut from a pickled beet or pimento.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0070', 'Green-Pea-and-Potato Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Mix equal parts of cold cooked peas and potatoes cut in very small cubes; season with salt and pepper, and serve as green-pea salad.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('potato', 1, '', 'Produce')], ['Mix equal parts of cold cooked peas and potatoes cut in very small cubes; season with salt and pepper, and serve as green-pea salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0071', 'Asparagus Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'eggs', 'green', 45, 'Scrape the scales from the stalks, and cook, standing upright in boiling salted water, until tender; drain and chill thoroughly.', [I('eggs', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('asparagus', 1, '', 'Produce')], ['Scrape the scales from the stalks, and cook, standing upright in boiling salted water, until tender; drain and chill thoroughly.', 'Serve on lettuce leaves with French dressing.', 'Garnish the lettuce with hard-boiled eggs cut in quarters lengthwise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0072', 'Macedoine of Vegetable Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'chicken', 'dessert', 45, 'Dress one cup, each, of cooked carrots and turnips, cut in dice, string beans, cut small, green peas, and half a cup of cooked beets, cut small, with French dressing; add two tablespoonfuls of chopped gherkins; drain,…', [I('cooked beets', 0.5, 'cup', 'Produce'), I('chopped gherkins', 2, 'tablespoonfuls', 'Meat & Seafood'), I('aspic will be sufficient', 1, 'pint', 'Pantry'), I('beet', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('carrots', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('green peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('turnips', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('jelly mayonnaise', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Dress one cup, each, of cooked carrots and turnips, cut in dice, string beans, cut small, green peas, and half a cup of cooked beets, cut small, with French dressing; add two tablespoonfuls of chopped gherkins; drain, and mix with sufficient jelly mayonnaise to hold the vegetables together.', 'Arrange in dome shape and cover with more jelly mayonnaise.', 'Set a row of sliced gherkins near the top, and fill in the space to the top with string beans or asparagus tips.', 'Surround the base with alternate rounds of beet and potato overlapping one another.', 'Decorate the space above with slices of potato and beet cut in diamonds, and surround the base with light-green aspic cut in diamonds.', 'One pint of aspic will be sufficient; use chicken stock, and tint with color paste.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0073', 'Russian Vegetable Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'dessert', 45, 'Select two moulds of suitable shape and size (tin basins or earthen bowls will do) and chill in ice water.', [I('lettuce', 1, '', 'Produce'), I('cauliflower', 1, '', 'Pantry'), I('carrots', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('turnips', 1, '', 'Produce'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('jelly mayonnaise', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Select two moulds of suitable shape and size (tin basins or earthen bowls will do) and chill in ice water.', 'Have ready cooked balls, cut from carrots and turnips, and cooked string beans and cauliflower, all marinated with French dressing.', 'Drain the vegetables, dip them into half-set aspic, and arrange against the chilled sides of the moulds; then fill the moulds with aspic jelly.', 'When set, with a hot spoon scoop out the aspic from the centre of each mould and fill in the space with a mixture of the vegetables and jelly mayonnaise, leaving an open space at the top to be filled with half-set aspic.', 'When thoroughly chilled and set, turn from the moulds, the smaller mould above the other.', 'Garnish with flowerets of cauliflower, dipped in aspic and chilled, and lettuce.', 'Serve with mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0074', 'Stuffed-Cucumber Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, 'Pare a short cucumber and cut it lengthwise in two parts; remove the seeds and let chill in ice water for an hour.', [I('new onion', 0.5, 'slice', 'Produce'), I('parsley', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry')], ['Pare a short cucumber and cut it lengthwise in two parts; remove the seeds and let chill in ice water for an hour.', 'Chop together the solid part of a peeled and seeded tomato, half a slice of new onion, a stalk of celery and a sprig of parsley; mix with mayonnaise or a boiled dressing and use as a filling for the well-dried halves of cucumber.', 'Serve on cress or lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0075', 'Cowslip-and-Cream-Cheese Salad', 'American', ["section-vegetable-salads-with-mayonnaise"], 'veg', 'green', 45, '(See cut facing page 58.', [I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('cowslip', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('neufchatel', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Cook the cowslip leaves until tender in boiling salted water, reserving a few choice leaves with blossoms for a garnish.', 'Chop fine, season to taste with salt and paprica, press into a mould, and set aside to become chilled.', 'Slice chilled cream cheese (Neufchatel or cottage) in uniform slices, and arrange at the sides of the mound.', 'Serve with French or mayonnaise dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0076', 'Cauliflower Salad, Egg Garnish', 'American', ["section-vegetable-salads-with-mayonnaise"], 'eggs', 'dessert', 45, 'Separate a cauliflower into flowerets and boil in salted water until tender, _not longer_.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('cauliflower', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('sauce tartare', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('mayonnaise dressing', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Separate a cauliflower into flowerets and boil in salted water until tender, _not longer_.', 'Drain carefully.', 'Season with oil, vinegar, salt, pepper, and a sprinkling of chopped tarragon leaves (or use tarragon vinegar).', 'Arrange symmetrically in an earthen bowl, having the upper surface level.', 'Let stand to become thoroughly chilled, then turn on to a serving-dish; the shape of the mould will be retained.', 'Cover with mayonnaise dressing or Sauce Tartare, and surround with lengthwise quarters of hard-boiled eggs.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0077', 'Potato Salad with Mayonnaise', 'American', ["section-vegetable-salads-with-mayonnaise"], 'eggs', 'green', 45, 'Boil the potatoes and let cool without paring.', [I('onion', 1, '', 'Produce'), I('onion juice', 1, '', 'Produce'), I('capers', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Boil the potatoes and let cool without paring.', 'Then remove the skins and cut into slices, balls, or cubes.', 'Squeeze over them a little onion juice, sprinkle with fine-chopped parsley, and let stand in a French dressing several hours.', 'Mix the dressing after the usual formula, and use enough to moisten well the potato.', 'When ready to serve, make nests of heart leaves of lettuce, put a spoonful of the potato in each, with a teaspoonful of mayonnaise above, sprinkle the mayonnaise with capers, and press the quarter of a hard-boiled egg into the top of the mayonnaise.', 'Or add the chopped white of egg to the potato before marinating, and sift the yolk over the mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0078', 'Brook-Trout Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Dress the trout without removing the heads; boil as previously indicated.', [I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('trout', 1, '', 'Meat & Seafood'), I('claret', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('brook trout', 1, '', 'Meat & Seafood')], ['Dress the trout without removing the heads; boil as previously indicated.', 'Remove the backbone without destroying the shape of the fish.', 'Serve, thoroughly chilled, on crisp lettuce leaves dressed with claret or French dressing.', 'Prepare the latter with tarragon vinegar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0079', 'Brook Trout Moulded in Aspic', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Pour a little chicken aspic into a pickle or other dish of suitable shape and size for a single fish; when nearly set, lay a trout, prepared as above, upon the aspic, add a few spoonfuls of aspic, let it harden so that…', [I('chicken', 1, '', 'Meat & Seafood'), I('capers', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('cucumber pickles', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('trout', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('chicken aspic', 1, '', 'Meat & Seafood'), I('brook trout', 1, '', 'Meat & Seafood')], ['Pour a little chicken aspic into a pickle or other dish of suitable shape and size for a single fish; when nearly set, lay a trout, prepared as above, upon the aspic, add a few spoonfuls of aspic, let it harden so that the fish may become fixed in place, then add aspic to cover.', 'Slices of cucumber pickles, capers, or other ornaments, may be used.', 'When the aspic is thoroughly set and chilled, remove from the mould and serve on two lettuce leaves, with any dressing desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0080', 'Halibut Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Flake the fish and marinate with French dressing (three tablespoonfuls of oil, one tablespoonful of lemon juice or vinegar, a dash of salt and pepper, for each pint of fish); drain, and add half as much boiled potato,…', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('lemon juice or vinegar', 1, 'tablespoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('sardine', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('halibut', 1, '', 'Meat & Seafood')], ['Flake the fish and marinate with French dressing (three tablespoonfuls of oil, one tablespoonful of lemon juice or vinegar, a dash of salt and pepper, for each pint of fish); drain, and add half as much boiled potato, cut in small cubes and dressed with French dressing.', 'Serve on a bed of lettuce leaves.', 'Garnish with sardine dressing.', 'Shredded lettuce or peas may be used in place of the potato.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0081', 'Halibut-and-Cucumber Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'INGREDIENTS.', [I('cooked halibut', 1, 'pound', 'Meat & Seafood'), I('oil', 2, 'tablespoonfuls', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('onion juice', 1, 'drops', 'Produce'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('pimentos', 2, '', 'Pantry'), I('Cucumbers', 1, '', 'Produce'), I('French dressing', 1, '', 'Pantry'), I('capers', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('cucumber', 1, '', 'Produce')], ['Flake one pound of cooked halibut while hot, and marinate with the oil, lemon juice, onion juice, salt and pepper.', 'When cold drain and mix with the pimentos, shredded, after cutting from the same a few star-shaped or other fanciful figures.', 'Arrange heart leaves of lettuce in an upright position in the centre of a serving-dish, the fish and pimentos around the lettuce, and, around these, one large or two small cucumbers, cut in small cubes and mixed with French dressing.', 'With salmon use capers instead of pimentos.', 'Use enough dressing to moisten the cucumbers thoroughly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0082', 'Halibut Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Steam a thick slice of chicken halibut, until the flesh separates easily from the bone.', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('vinegar or lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('endive', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry')], ['Steam a thick slice of chicken halibut, until the flesh separates easily from the bone.', 'Remove the skin and bones without disturbing the shape of the fish.', 'Marinate, while hot, with three tablespoonfuls of oil, one tablespoonful of vinegar or lemon juice, and salt and pepper.', 'When cold put the fish on a serving-dish, and, using endive or Boston Market lettuce, put the ends of the leaves beneath the fish, so that the tops of the leaves will fall over upon the fish.', 'Garnish the top with stars of mayonnaise.', 'Between the leaves dispose sliced pim-olas and fans cut from small gherkins.', 'Serve mayonnaise with the salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0083', 'Fillets of Halibut in Aspic, with Cucumber-and-Radish Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'INGREDIENTS.', [I('halibut', 2, 'slices', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('butter', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 0.25, 'cup', 'Pantry'), I('cream', 0.25, 'cup', 'Dairy & Eggs'), I('stock', 0.25, 'cup', 'Pantry'), I('paprica', 1, 'dash', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('salt', 0.25, 'tablespoonful', 'Herbs & Spices'), I('aspic', 1, 'quart', 'Pantry'), I('Olives', 1, '', 'Produce'), I('radishes', 1, 'bunch', 'Produce'), I('cucumbers', 2, '', 'Produce'), I('French dressing', 1, '', 'Pantry'), I('fillets', 8, '', 'Pantry'), I('pepper', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('fish', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('cucumber', 1, '', 'Produce'), I('radish', 1, '', 'Produce')], ['Remove the skin and bone from the halibut, thus securing eight fillets.', 'Season with salt, pepper, onion and lemon juice.', 'Chop the lobster meat fine; melt the butter, cook in it the flour and seasonings, add the cream and lobster stock, and, when cooked, stir in the chopped lobster.', 'When cool spread upon one side of the fillets, roll up the fillets and fasten with wooden toothpicks that have been dipped in melted butter.', 'Bake on a fish-sheet about fifteen minutes, basting with butter melted in hot water.', 'Set a plain border-mould in ice water; decorate the bottom and sides with pim-olas or gherkins cut in slices and dipped in half-set aspic; cover the decoration on the bottom with aspic, and, when set and the decorations on the side are "fixed" in place, arrange on the aspic the cold fillets of fish and fill the mould with more aspic.', 'When cold turn from the mould and fill the centre with diced cucumbers and sliced radishes dressed with French dressing.', 'Pass mayonnaise or French dressing in a separate dish.', 'Surround the aspic with shredded lettuce if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0084', 'Fillets of Halibut in Aspic with Cole-Slaw', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Use a generous half-pint of oysters in the place of the lobster, parboiling and draining before chopping, and fill in the centre of the aspic with coleslaw.', [I('lobster', 1, '', 'Meat & Seafood'), I('oysters', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('halibut', 1, '', 'Meat & Seafood')], ['Use a generous half-pint of oysters in the place of the lobster, parboiling and draining before chopping, and fill in the centre of the aspic with coleslaw.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0085', 'Miroton of Fish and Potato', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, 'Marinate one pint of cold cooked fish--salmon, cod, haddock, halibut, etc.', [I('cooked fish--salmon', 1, 'pint', 'Meat & Seafood'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('lemon juice', 2, 'tablespoonfuls', 'Produce'), I('cold potatoes', 1, 'pint', 'Produce'), I('onion juice', 1, 'teaspoonful', 'Produce'), I('capers', 3, 'tablespoonfuls', 'Pantry'), I('hard-boiled eggs', 6, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('aspic', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('gelatine', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry')], ['Marinate one pint of cold cooked fish--salmon, cod, haddock, halibut, etc.--with three or four tablespoonfuls of oil, half a teaspoonful of salt, a dash of pepper and two tablespoonfuls of lemon juice.', 'Marinate, separately, one pint of cold potatoes, cooked in their skins and cut in cubes, with the same quantity of dressing, adding also one teaspoonful of onion juice.', 'Let stand in a cool place one hour or more.', 'Have ready six hard-boiled eggs; cut a thin slice from the round end of each egg, that it may stand upright, then cut in quarters lengthwise.', 'Dip into a little aspic jelly or melted gelatine and arrange the quarters in the form of a circle, with the yolks outside.', 'Toss together the fish, potato and three tablespoonfuls of capers, and fill in the centre of the circle.', 'Dust with fine-chopped parsley or beets; add a tuft of lettuce at the top and a few heart leaves of lettuce above the crown of eggs.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0086', 'Fish Salad Moulded in Aspic', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, 'Cover the bottom of a mould with aspic to the depth of one-fourth an inch.', [I('cooked peas', 0.5, 'cup', 'Produce'), I('capers', 3, 'tablespoonfuls', 'Pantry'), I('mayonnaise made with jelly', 1, 'cup', 'Pantry'), I('cold cooked peas', 0.5, 'cup', 'Produce'), I('lettuce', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('turnip', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry')], ['Cover the bottom of a mould with aspic to the depth of one-fourth an inch.', 'Set the mould in ice water, and, when the aspic is set, arrange upon it a decoration of cooked vegetables cut in shapes with French cutter, or fashion a conventional design or some flower.', 'Dogwood blossoms provide a simple pattern, and one easily carried out.', 'Cut the four petals from a thin slice of cooked turnip and the centre of the blossom from carrot or lemon peel.', 'Fasten each piece in place with liquid jelly, and, when set, cover with more jelly.', 'To decorate the sides of the mould, take the figures on the point of a skewer, dip in jelly, then set in position against the _chilled_ sides of the mould, and they will remain in place.', 'After the jelly covering the figures on the bottom of the mould has "set," place a smaller mould in the centre of the aspic in the first, and fill this with ice and water.', 'Pour in aspic to fill the space about the smaller mould, and, when this aspic is firm, dip out the water and ice.', 'Fill with _warm_ water and quickly remove the mould.', 'Separate a pound of cooked fish into flakes, add half a cup of cold cooked peas, three or four gherkins, cut very fine, and three tablespoonfuls of capers.', 'Mix together and then mix with one cup of mayonnaise made with jelly; with this fill the vacant space in the mould.', 'When ready to serve, dip the mould very quickly into warm water, letting the water rise to the top of the mould, and invert over a serving-dish; remove the mould, and garnish with lettuce, tiny gherkins cut to resemble fans, blocks of aspic, or aspic moulded in shells, and mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0087', 'Fish Salad Moulded in Aspic, No. 2', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Decorate the mould as before; then put in a layer of the fish and dressing; when set, add a layer of aspic; alternate the layers until the materials are used or the mould is filled.', [I('fish', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry')], ['Decorate the mould as before; then put in a layer of the fish and dressing; when set, add a layer of aspic; alternate the layers until the materials are used or the mould is filled.', 'Individual moulds may be prepared in the same way.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0088', 'Salad of Mackerel or Bluefish', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Separate a cooked fish into flakes and mix with the chopped whites and sifted yolks of three hard-boiled eggs.', [I('hard-boiled eggs', 3, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('fish', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('pickled beet', 1, '', 'Produce'), I('mackerel', 1, '', 'Meat & Seafood'), I('bluefish', 1, '', 'Meat & Seafood')], ['Separate a cooked fish into flakes and mix with the chopped whites and sifted yolks of three hard-boiled eggs.', 'Season with French dressing, mix lightly and turn on to a bed of lettuce or cress, also seasoned with the dressing.', 'Garnish with fans cut from small gherkins, or with pickled beet cut in fanciful shape or chopped.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0089', 'Salad of Salt Mackerel', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Freshen the fish carefully before cooking.', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('cress', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('beef', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('mackerel', 1, '', 'Meat & Seafood')], ['Freshen the fish carefully before cooking.', 'Use equal parts of fish, flaked, and cold boiled potatoes.', 'If potatoes are specially prepared for the purpose, cut them in cubes or balls, blanch, and cook in well-seasoned beef stock; drain, and add, when cold, to the fish.', 'Season with French dressing.', 'Arrange on a bed of cress and sift the yolk of an egg over the whole.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0090', 'Salad of Shad Roe and Cucumber', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Cook two shad roes with an onion, sliced, and a bay leaf, in salted, acidulated water twenty minutes; drain, and marinate with about two tablespoonfuls of oil, one tablespoonful of lemon juice and a dash of pepper and…', [I('oil', 2, 'tablespoonfuls', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('garlic', 1, '', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('bay leaf', 1, '', 'Herbs & Spices'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('shad', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('pickled beet', 1, '', 'Produce'), I('shad roe', 1, '', 'Pantry')], ['Cook two shad roes with an onion, sliced, and a bay leaf, in salted, acidulated water twenty minutes; drain, and marinate with about two tablespoonfuls of oil, one tablespoonful of lemon juice and a dash of pepper and salt.', 'When cold cut in small cubes.', 'Rub the salad-bowl with a clove of garlic cut in halves.', 'Cut a thoroughly chilled cucumber in dice; put the cucumber on a bed of lettuce leaves in the bottom of the bowl, and the roe, well drained, above; mask with mayonnaise,--nearly a cup will be required,--in the top insert a few heart leaves of lettuce, and place around the centre of the mound a circle of cucumber slices overlapping one another; or alternate these with lozenges cut from pickled beet.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0091', 'Boudins-de-Saumon Salad', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, 'Butter four small dariole moulds, or small cups; sprinkle the butter with chopped parsley.', [I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('milk', 0.5, 'cup', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('onion juice', 1, '', 'Produce'), I('anchovy essence', 1, '', 'Meat & Seafood'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('anchovy', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Butter four small dariole moulds, or small cups; sprinkle the butter with chopped parsley.', 'Select four small pieces of cooked salmon, dry on a soft cloth so as to remove all oily liquor, and put a piece in each mould.', 'Beat two eggs (or, better, one egg and the yolks of two) slightly, season with one-fourth a teaspoonful of salt, a dash of paprica and a few drops of anchovy essence or onion juice; add half a cup of milk, and, when well mixed, pour into the moulds around the fish.', 'Set the moulds in a pan of hot water and bake until the custard is set.', 'Do not let the water boil.', 'Chill thoroughly, then turn from the moulds on to lettuce leaves.', 'Serve with a star of mayonnaise dressing on the top of each _boudin_.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0092', 'Russian Salad', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, '(BOSTON COOKING-SCHOOL.', [I('carrots', 1, 'cup', 'Produce'), I('potatoes', 1, 'cup', 'Produce'), I('peas', 1, 'cup', 'Produce'), I('beans', 1, 'cup', 'Produce'), I('oil', 6, 'tablespoonfuls', 'Pantry'), I('vinegar', 3, 'tablespoonfuls', 'Pantry'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('pepper', 0.25, 'teaspoonful', 'Produce'), I('head of lettuce', 1, '', 'Produce'), I('mayonnaise', 1, 'cup', 'Pantry'), I('shrimps', 1, 'cup', 'Meat & Seafood'), I('smoked salmon', 0.25, 'lb', 'Meat & Seafood'), I('hard-boiled egg', 1, '', 'Dairy & Eggs'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('egg whites', 1, '', 'Dairy & Eggs'), I('french dressing', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Marinate the carrots and potatoes, cut in small pieces, also the peas and beans, with French dressing.', 'Arrange on a dish in four sections, having lettuce for the foundation of each.', 'Cover each vegetable with mayonnaise.', 'Strew the tops of two sections with small pieces of smoked salmon; on a third section strew the sifted yolk of the egg, and on the fourth, the white of the egg, cut rather coarsely.', 'Outline the inner side of each section with shrimps, by lightly pressing the ends of the shrimps into the mayonnaise.', 'Finish with a tuft of lettuce in the centre of the dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0093', 'Spanish Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'In the centre of a flat serving-dish arrange a mound of endive.', [I('egg whites', 1, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('endive', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('shallot', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('salmon', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('shrimp', 1, '', 'Meat & Seafood'), I('anchovies', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs')], ['In the centre of a flat serving-dish arrange a mound of endive.', 'Peel tomatoes, divide into sections or cut in slices, and arrange these around the endive.', 'Shell cold, hard-boiled eggs; cut in halves, crosswise, and in points; remove the yolks and pound to a paste with an equal amount of the flesh of lobster, shrimp, anchovies or salmon.', 'With this paste, seasoned to taste with oil, lemon juice, salt and pepper, fill the cups fashioned from the whites of the eggs, and arrange them around the tomatoes.', 'Strew chopped shallot and sweet pepper over the endive.', 'Mix equal portions of oil and vinegar, add salt and pepper to taste, and pour over the salad.', 'Serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0094', 'Salmon Salad', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, '(_For evening company, or fish course at a dinner party.', [I('Hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('gelatine', 1, 'teaspoonful', 'Pantry'), I('cold water', 1, 'tablespoonful', 'Pantry'), I('string beans or asparagus tips', 1, 'pint', 'Produce'), I('cooked peas', 1, 'pint', 'Produce'), I('French dressing', 1, '', 'Pantry'), I('salmon, 2 inches thick', 2, 'slices', 'Meat & Seafood'), I('Jelly mayonnaise', 1, '', 'Pantry'), I('or fancy butter', 1, '', 'Dairy & Eggs'), I('Capers', 1, '', 'Pantry'), I('whites', 1, '', 'Pantry'), I('asparagus tips', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('vegetables', 1, '', 'Pantry')], ['Cut the eggs into halves lengthwise; cut a thin slice from the round ends, that the pieces may be set upright; dip lightly in the gelatine dissolved over hot water, and arrange _miroton_ fashion around an oval serving-dish.', 'Set aside, that the eggs may become fixed in position.', 'Marinate the vegetables, separately, with French dressing; cook the salmon by the directions previously given; remove the skin and cover the sides with jelly mayonnaise or fancy butter.', 'When cold decorate with whites of eggs and capers.', 'Use the trimmings from the eggs, and fix them in place by dipping in jelly mayonnaise.', 'Set aside for the decorations to become fixed.', 'Drain the vegetables and arrange inside the border, higher in the centre.', 'Lay the decorated slices of fish upon opposite sides of the mound, and serve either with or without mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0095', 'Halibut Salad', 'American', ["section-fish-salads"], 'fish', 'dessert', 45, '(_For evening company, or fish course at a dinner party.', [I('chicken halibut, 3 inches thick', 1, 'slice', 'Meat & Seafood'), I('cooked peas', 3, 'cups', 'Produce'), I('French dressing', 1, '', 'Pantry'), I('Hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('pickled beet', 3, 'slices', 'Produce'), I('gelatine', 1, 'teaspoonful', 'Pantry'), I('Jelly mayonnaise', 1, '', 'Pantry'), I('or green butter', 1, '', 'Dairy & Eggs'), I('Heart leaves of lettuce', 1, '', 'Produce'), I('olives', 2, '', 'Produce'), I('egg whites', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('green butter', 1, '', 'Dairy & Eggs')], ['Prepare the eggs and fasten to the plate as in salmon salad.', 'Dip diamond-shaped pieces of pickled beet in the dissolved gelatine and place upon the front and top of each half of egg.', 'Spread the edge of the fish, after removing the skin, with jelly mayonnaise, or green butter, and, when set, decorate with figures cut from the cooked white of an egg.', 'With forcing-bag and tube shape a pattern around the upper edge of the fish.', 'Place the fish in the centre of the crown or _miroton_ of eggs, with the peas seasoned with French dressing around it; cover the place from which the bone was taken with the centre of a head of lettuce, cut in halves, and two fine olives.', 'Serve with a bowl of mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0096', 'Shells of Fish and Mushrooms', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Cut cold fish--salmon, halibut, lobster, etc.', [I('gherkins', 1, 'tablespoonful', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Cut cold fish--salmon, halibut, lobster, etc.--into small cubes, mix with one-third in measure of cooked mushrooms, also cut small, and add for each cup of mushrooms and fish one tablespoonful of gherkins cut fine.', 'Season with French dressing and let stand one hour; then drain, and mix with jellied mayonnaise.', 'Fill chilled shells with this preparation, rounding it on the top.', 'Make smooth, and mask with jellied mayonnaise.', 'Decorate with gherkins and the white of a hard-boiled egg cut in fanciful shapes, and with stars of mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0097', 'Oysters in Aspic Jelly', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Parboil, drain, cool, and wipe dry one quart of oysters.', [I('oysters', 1, 'quart', 'Meat & Seafood'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('chicken aspic', 1, '', 'Meat & Seafood')], ['Parboil, drain, cool, and wipe dry one quart of oysters.', 'Make a pint of mayonnaise sauce with aspic jelly and coat the well-dried oysters with the sauce.', 'Prepare a quart of chicken aspic.', 'Dip in half-set aspic the white of egg, poached and cut in fanciful shapes, and small gherkins cut in thin slices, and decorate the bottom and sides of a charlotte or cylindrical mould standing in ice water.', 'Pour in jelly to the depth of half an inch; when set, arrange the oysters on it in a circle, one overlapping another; pour in more jelly, and, when set, dispose upon it another circle of oysters.', 'Continue this order until the mould is filled.', 'When removed from the mould, garnish with chopped aspic and fans cut from gherkins and lettuce.', 'Serve with the remainder of the pint of mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0098', 'Oyster-and-Celery Salad', 'American', ["section-fish-salads"], 'seafood', 'green', 45, 'Parboil the oysters (heating them to the boiling-point in their own liquor), drain, and, if large, halve each; marinate with a French dressing (_i.', [I('lemon', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('capers', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cabbage', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('nasturtium', 1, '', 'Pantry'), I('nasturtium seeds', 1, '', 'Pantry'), I('oysters', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry')], ['Parboil the oysters (heating them to the boiling-point in their own liquor), drain, and, if large, halve each; marinate with a French dressing (_i.e._, toss the bits of oyster in oil enough to coat them nicely; then toss them in a little lemon juice, dust with salt and pepper, and set aside to become thoroughly chilled).', 'When ready to serve, drain again and add about one-third as much in bulk of fine-chopped celery and one or two tablespoonfuls of pickled nasturtium seeds or capers; then mix with mayonnaise or a boiled dressing.', 'Serve on a bed of lettuce leaves.', 'Cabbage, sliced as for slaw, may be used in the place of celery.', 'Garnish with small pickles cut in thin slices and spread to resemble a fan.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0099', 'Oyster-and-Sweetbread Salad', 'American', ["section-fish-salads"], 'seafood', 'green', 45, 'Cut a pair of cold cooked sweetbreads into cubes.', [I('oysters', 1, 'pint', 'Meat & Seafood'), I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('cucumbers', 1, '', 'Produce'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('oyster', 1, '', 'Meat & Seafood'), I('sweetbread', 1, '', 'Meat & Seafood')], ['Cut a pair of cold cooked sweetbreads into cubes.', 'Parboil one pint of oysters, drain, cool, and cut in halves; marinate the sweetbreads and oysters with French dressing, and allow them to stand at least half an hour; drain, mix with mayonnaise, and serve on a bed of lettuce or cress.', 'Or, surround with a circle of chopped cucumbers seasoned with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0100', 'Shrimp Salad in Cucumber Boats', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Pare the cucumbers, which should be rather short, and cut them in halves lengthwise; remove the seeds and steam until tender; chill, and arrange on lettuce leaves, or on a bed of watercress.', [I('lettuce', 1, '', 'Produce'), I('watercress', 1, '', 'Produce'), I('cucumbers', 1, '', 'Produce'), I('shrimps', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('cucumber', 1, '', 'Produce'), I('shrimp', 1, '', 'Meat & Seafood')], ['Pare the cucumbers, which should be rather short, and cut them in halves lengthwise; remove the seeds and steam until tender; chill, and arrange on lettuce leaves, or on a bed of watercress.', 'Clean and marinate the shrimps.', 'If large, divide into two or three pieces.', 'Mix with mayonnaise and place in the cucumbers.', 'Decorate with stars of mayonnaise and whole shrimps.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0101', 'Shrimp Salad with Aspic Border', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Set a border mould in ice water; dip hard-boiled eggs, cut in halves lengthwise and trimmed to fit the mould, in aspic jelly, and press against the sides of the mould alternately with small vegetable balls, or peas…', [I('shrimps', 1, 'pint', 'Meat & Seafood'), I('eggs', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('jelly mayonnaise', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('shrimp', 1, '', 'Meat & Seafood')], ['Set a border mould in ice water; dip hard-boiled eggs, cut in halves lengthwise and trimmed to fit the mould, in aspic jelly, and press against the sides of the mould alternately with small vegetable balls, or peas dipped in half-set aspic; fill gradually the empty space in the mould with partly cooled jelly, adding vegetables here and there if desired.', 'Dip in hot water and turn from the mould.', 'Fill in the centre with lettuce, torn in pieces, and one pint of shrimps, broken in pieces and dressed with French dressing.', 'Smooth the mound and mask with jelly mayonnaise.', 'Decorate with shrimps and small heart leaves of lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0102', 'Shrimp Salad with Aspic Border, No. 2', 'American', ["section-fish-salads"], 'seafood', 'green', 45, 'Decorate the sides of a ring mould, chilled, with hard-boiled eggs cut in halves, alternated with hearts of lettuce cut in halves; dip the egg and lettuce in half-set aspic, and they will adhere to the sides of the…', [I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('aspic', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('shrimp', 1, '', 'Meat & Seafood')], ['Decorate the sides of a ring mould, chilled, with hard-boiled eggs cut in halves, alternated with hearts of lettuce cut in halves; dip the egg and lettuce in half-set aspic, and they will adhere to the sides of the mould.', 'Then proceed as above.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0103', 'Shrimp Salad', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Take the shrimps from the shells, reserve the most perfect for garnishing, and break the others into pieces; marinate with French dressing.', [I('egg whites', 1, '', 'Dairy & Eggs'), I('capers', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('shrimps', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('shrimp', 1, '', 'Meat & Seafood')], ['Take the shrimps from the shells, reserve the most perfect for garnishing, and break the others into pieces; marinate with French dressing.', 'When ready to serve, drain, and mix with shredded lettuce, or celery cut fine, and mayonnaise.', 'Shape in a mound on a bed of lettuce leaves and mask with mayonnaise.', 'Use capers or olives, chopped very fine, to mark out five or six designs on the mound; a scroll effect is always pretty.', 'Fill in the designs with shrimps and the rest of the mound with capers, sifted yolks or chopped whites of cooked eggs; or fill the designs with the capers or eggs and the rest of the mound with shrimps.', 'Finish with a tuft of lettuce at the top.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0104', 'Scallop Salad', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Soak the scallops in salted water (a tablespoonful of salt to a quart of water) one hour; rinse in cold water, cover with boiling water, and let simmer five or six minutes.', [I('salt', 1, '', 'Herbs & Spices'), I('capers', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('celery', 1, '', 'Produce'), I('beets', 1, '', 'Produce'), I('scallops', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry'), I('scallop', 1, '', 'Pantry')], ['Soak the scallops in salted water (a tablespoonful of salt to a quart of water) one hour; rinse in cold water, cover with boiling water, and let simmer five or six minutes.', 'Rinse again in cold water, drain, and when cold cut into slices.', 'Cut white stalks of celery into small pieces.', 'Mix the celery and scallops--half as much celery as scallops--with mayonnaise or boiled dressing, and shape in a mound.', 'Mask the mound with a thin coating of mayonnaise.', 'With large-sized capers outline a design on each of the four sides of the mound, fill these with whites of eggs, cooked and chopped fine.', 'Ornament with figures cut from slices of boiled beets.', 'Fill in the spaces around the designs with capers, and garnish with green celery leaves and white stalks of celery, fringed.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0105', 'Sardine Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Lay the sardines upon soft paper, that they may be freed from oil.', [I('lemon', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('mayonnaise dressing', 1, '', 'Pantry'), I('sardine', 1, '', 'Meat & Seafood')], ['Lay the sardines upon soft paper, that they may be freed from oil.', 'Scrape off the skin and remove the bones; squeeze over them a little lemon juice.', 'Arrange upon a bed of crisp lettuce leaves, or upon shredded lettuce, and dress with either French or mayonnaise dressing.', 'Garnish with hard-boiled eggs cut in slices.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0106', 'Sardine Salad, No. 2', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Arrange a pint of cold cooked fish, flaked, on a bed of lettuce leaves and cover with sardine dressing.', [I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('sardines', 1, '', 'Meat & Seafood'), I('sardine', 1, '', 'Meat & Seafood')], ['Arrange a pint of cold cooked fish, flaked, on a bed of lettuce leaves and cover with sardine dressing.', 'Carefully split six selected sardines; remove the bones and arrange the halves on the top of the salad, with the heads at the centre.', 'Garnish with slices of lemon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0107', 'Sardine-and-Egg Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Skin and bone a dozen sardines and put them in a mortar; remove the shells from an equal number of hard-boiled eggs and cut them into halves crosswise, so as to form cups with pointed edges; put the yolks into the…', [I('pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('watercress', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('salad dressing', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('sardine', 1, '', 'Meat & Seafood')], ['Skin and bone a dozen sardines and put them in a mortar; remove the shells from an equal number of hard-boiled eggs and cut them into halves crosswise, so as to form cups with pointed edges; put the yolks into the mortar with the sardines, add a tablespoonful, or less, of chopped parsley, a dash of pepper and salt, and work to a smooth paste; moisten with salad dressing and season to taste with salt and pepper.', 'Cut a thin slice from the ends of the egg cups, that they may be set upright on the serving-dish, and fill with the mixture, making it round on the top like a whole yolk.', 'Arrange these on a bed of watercress, or shredded lettuce, and sprinkle plentifully with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0108', 'Lobster Salad', 'American', ["section-fish-salads"], 'seafood', 'green', 45, 'Cut lobster meat in dice and marinate with French dressing.', [I('bouquet', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Cut lobster meat in dice and marinate with French dressing.', 'Keep on ice until ready to serve, then drain carefully.', 'Make cups of the inside leaves of lettuce, put a spoonful of the lobster meat in the centre of each cup, and press mayonnaise dressing through a pastry bag with star tube attached on the top of the lobster in each nest.', 'Or, arrange the lobster in a mound on a bed of lettuce leaves, and mask the mound with mayonnaise.', 'Finish the centre with a little bouquet of the heart leaves of lettuce; sift dried coral in a circle about it, and below that arrange circles of sifted yolk or chopped white of egg alternately with the coral.', 'Garnish with the fans and feelers of the lobster.', 'Or, arrange as before, then finish the centre with a bouquet of heart leaves of lettuce and the head of the lobster.', 'Garnish with stars of mayonnaise and fans from the tail.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0109', 'Lobster Salad, No. 2', 'American', ["section-fish-salads"], 'seafood', 'green', 45, 'Remove the flesh carefully from the shell of a lobster, so as to keep the shell of body and tail intact; wash and dry the shell and arrange on a bed of lettuce leaves.', [I('lettuce', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Remove the flesh carefully from the shell of a lobster, so as to keep the shell of body and tail intact; wash and dry the shell and arrange on a bed of lettuce leaves.', 'Marinate the flesh, cut into cubes, with French dressing.', 'After an hour drain, mix with an equal quantity of shredded lettuce, and replace in the shell.', 'Garnish with mayonnaise and the lobster coral.', 'Dry the coral thoroughly, after which it may be passed readily through a sieve.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0110', 'Lobster Salad, No. 3', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'INGREDIENTS.', [I('good-sized lobsters', 2, '', 'Meat & Seafood'), I('Mayonnaise', 1, '', 'Pantry'), I('or sauce tartare', 1, '', 'Pantry'), I('Lobster cutlets', 1, '', 'Meat & Seafood'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('flour', 0.3333333333333333, 'cup', 'Pantry'), I('Salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('Lobster coral', 1, '', 'Meat & Seafood'), I('yolk of egg', 1, '', 'Dairy & Eggs'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('lobster meat', 2, 'cups', 'Meat & Seafood'), I('aspic jelly', 3, 'cups', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('sauce tartare', 1, '', 'Pantry'), I('white sauce', 1, '', 'Pantry')], ['Make a white sauce of the butter, flour, seasonings and milk; add the coral and butter, after pounding until smooth in a mortar, also the yolk of egg, beaten and diluted with the lemon juice, and the lobster meat chopped rather coarsely.', 'When cold shape into cutlets, dust over with sifted coral, and insert a bit of feeler or claw into the small end of each.', 'Pour a little aspic into a dish, and, when it sets, arrange the cutlets upon it a little distance apart; pour over each a few spoonfuls of aspic, and when set cover with more aspic.', 'When cold and very firm cut out the cutlets, giving a border of aspic to each.', 'Marinate the flesh of the other lobster, cut into cubes, with French dressing; pile in a mound on a bed of lettuce leaves.', 'Insert a tuft of leaves in the top, and arrange the cutlets against the mound.', 'Garnish with feelers and claws.', 'Serve mayonnaise or sauce tartare with the salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0111', 'Lobster Salad in Ring of Aspic', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Set a ring mould in ice water.', [I('lemon juice', 1, '', 'Produce'), I('capers', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('turnip', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('lobsters', 1, '', 'Meat & Seafood'), I('caviare', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery'), I('aspic', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood')], ['Set a ring mould in ice water.', 'In the bottom of the mould arrange pitted olives or pim-olas an inch apart.', 'Dip figures, cut from slices of royal custard, or from cooked carrot or turnip, into liquid aspic, and place them on the sides of the mould, to which they will adhere; dip large-sized capers (a larding-needle or skewer is of assistance in this work) in aspic and with them ornament the mould; then fill with aspic and set aside to become fixed.', 'When ready to serve, dip the mould in hot water and invert on a serving-dish.', 'Cut the meat from two two-pound lobsters into small cubes.', 'Season with French dressing.', 'Fill the open space in the aspic with the salad; garnish the top with the feelers and delicate lettuce leaves, and arrange a wreath of lettuce leaves around the aspic.', 'Stamp out rounds of bread; stamp again with the same cutter to form crescents, spread delicately with butter, and then with caviare seasoned with a few drops of lemon juice, and dispose symmetrically on the lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0112', 'Mousseline of Lobster as a Salad', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Chill timbale moulds in ice water; dip thin slices of gherkins into half-set aspic, and arrange them symmetrically against the sides of the moulds, and brush over the decoration with aspic.', [I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('gelatine', 0.25, 'package', 'Pantry'), I('cold lobster liquor', 0.25, 'cup', 'Meat & Seafood'), I('whipped cream', 1, 'cup', 'Dairy & Eggs'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('lobster', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Chill timbale moulds in ice water; dip thin slices of gherkins into half-set aspic, and arrange them symmetrically against the sides of the moulds, and brush over the decoration with aspic.', 'Cut the claw meat of a two-pound lobster into small cubes; chop fine, and pound the remaining meat in a mortar; then add to it the liver and fat, and pass through a sieve.', 'There should be about one cup.', 'Simmer the shell in water to cover half an hour.', 'Beat the yolks of three eggs, slightly, with one-fourth a teaspoonful of salt and a dash of paprica; add one cup of the lobster liquor very gradually, and cook over hot water as a boiled custard.', 'Remove from the fire and add one-fourth a package of gelatine, softened in one-fourth a cup of cold lobster liquor, or chicken stock; strain over the sifted lobster meat and stir occasionally over ice water; when it begins to set, add the lobster dice, and fold in carefully one cup of whipped cream.', 'Turn the mixture into the decorated mould, and, when set, turn out on to lettuce leaves.', 'Decorate with the head, feelers and claws of the lobster.', 'Serve with French or mayonnaise dressing.', 'French dressing is preferable with so rich a mixture.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0113', 'Anchovy Salad', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'INGREDIENTS.', [I('anchovies', 8, '', 'Pantry'), I('hard-boiled eggs', 4, '', 'Dairy & Eggs'), I('head of lettuce', 1, '', 'Produce'), I('French or mayonnaise dressing', 1, '', 'Pantry'), I('or Sauce tartare', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('onion juice', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('sauce tartare', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry'), I('anchovy', 1, '', 'Meat & Seafood')], ['If salt anchovies are to be used, soak them in cold water two hours, then drain, dry, and remove skin and bones; divide the flesh into small pieces and squeeze the lemon juice over them.', 'When ready to serve, arrange the lettuce leaves upon a serving-dish, stalk ends at the centre, cut the eggs in slices, mix with the bits of anchovies, and arrange upon the lettuce.', 'Pour a French or mayonnaise dressing made with onion juice, or a sauce tartare, over the salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0114', 'Salad of Lettuce, Bamboo Sprouts, and Shrimps', 'American', ["section-fish-salads"], 'seafood', 'dessert', 45, 'Marinate a cup of shrimps, broken in small pieces, with three tablespoonfuls of oil, one tablespoonful of lemon juice, a dash of salt and pepper.', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('bamboo sprouts', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('shrimps', 1, '', 'Meat & Seafood'), I('sprouts', 1, '', 'Pantry')], ['Marinate a cup of shrimps, broken in small pieces, with three tablespoonfuls of oil, one tablespoonful of lemon juice, a dash of salt and pepper.', 'Select the tender bamboo sprouts in a can, and cut them into small pieces of the shape desired.', 'When ready to serve, dress these with salt, pepper, oil, and lemon juice.', 'Use three measures of oil to one of acid.', 'Begin with the oil.', 'Continue mixing and adding oil, until each piece is glossy.', 'Then add the acid.', 'Mix the prepared sprouts and the drained shrimps, and turn them onto a bed of lettuce, cut in narrow shreds, and dressed with oil and acid.', 'Decorate the salad with heart leaves of lettuce, whole shrimps, and hollow sections of bamboo, cut in thin slices.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0115', 'Bluefish Salad (excellent)', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Separate the remnants of a baked bluefish into flakes, discarding skin and bones.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('beet', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('bluefish', 1, '', 'Meat & Seafood'), I('boiled dressing', 1, '', 'Pantry'), I('pickled beet', 1, '', 'Produce')], ['Separate the remnants of a baked bluefish into flakes, discarding skin and bones.', 'Set aside, covered, until cold.', 'About an hour before serving, sprinkle with salt and pepper and (for a generous pint of fish) the juice of a lemon.', 'When ready to serve, dispose heart leaves of lettuce on the edge of a salad plate, and turn the fish into the centre, letting it come out over the stems of the lettuce leaves.', 'Pour a boiled dressing over the top, and spread evenly (with a silver knife) over the fish.', 'Put a tablespoonful of chopped pickled beet at the stems of each group of leaves, a ring of the beet near the top, and figures, cut from the beet, between.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0116', 'Moulded Salmon Salad', 'American', ["section-fish-salads"], 'fish', 'green', 45, 'Use a pound of salmon, fresh-cooked or canned.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('mustard', 0.5, 'teaspoonful', 'Herbs & Spices'), I('hot milk', 0.75, 'cup', 'Dairy & Eggs'), I('hot vinegar', 0.25, 'cup', 'Pantry'), I('butter creamed', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('sugar', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('cucumber', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('flour', 1, '', 'Pantry'), I('gelatine', 1, '', 'Pantry'), I('salad dressing', 1, '', 'Pantry')], ['Use a pound of salmon, fresh-cooked or canned.', 'Remove skin and bone, and pick the flesh fine with a silver fork.', 'Mix half a teaspoonful of salt, a teaspoonful of sugar, a teaspoonful of flour, half a teaspoonful of mustard, and a dash of paprica.', 'Over these pour very gradually three-fourths a cup of hot milk and stir and cook over hot water ten minutes, then add one-fourth a cup of hot vinegar and two tablespoonfuls of butter creamed and mixed with the beaten yolks of two eggs; stir until the egg is set, then add one level tablespoonful of granulated gelatine, softened in one-fourth a cup of cold water, and strain over the salmon; mix thoroughly, and turn into a mould.', 'When chilled serve with Cream Salad Dressing (page 27), to which half a cucumber, chopped fine and drained, has been added.', 'Reserve a part of the dressing, omitting the cucumber, and use with slices of cucumber as a garnish.', 'To prepare the cucumber, pare with a handy slicer and cut from it a section three-fourths an inch thick; pare this round and round very thin and roll loosely to form a cup.', 'Dispose this on the top of the fish and fill with dressing.', '(Use a pastry bag and tube.) Cut the rest of the cucumber in thin slices.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0117', 'Sweetbread-and-Cucumber Salad', 'American', ["section-various-compound-salads"], 'beef', 'dessert', 45, 'Arrange the leaves of a head of cabbage lettuce loosely upon a serving-dish, without destroying its shape.', [I('lettuce', 1, '', 'Produce'), I('cabbage', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('sweetbread', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('jelly mayonnaise', 1, '', 'Pantry')], ['Arrange the leaves of a head of cabbage lettuce loosely upon a serving-dish, without destroying its shape.', 'Have ready a pair of sweetbreads cooked in salted, acidulated water twenty minutes, and cooled and cut in small cubes and marinated; also the same quantity of cucumber cut in dice, chilled in ice water and dried upon a cloth.', 'Drain the French dressing from the sweetbread and scatter the bits of sweetbread and cucumber through the lettuce.', 'Press three-fourths a cup of firm jelly mayonnaise through a pastry bag with small tube, in little stars, here and there, throughout the lettuce, and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0118', 'Sweetbread-and-Cucumber Salad, No. 2', 'American', ["section-various-compound-salads"], 'beef', 'green', 45, 'Cook, marinate and drain the sweetbreads as before; mix with an equal quantity of cucumber cut in dice, and then with cream dressing.', [I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('radish', 1, '', 'Produce'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('cream dressing', 1, '', 'Dairy & Eggs'), I('sweetbread', 1, '', 'Meat & Seafood')], ['Cook, marinate and drain the sweetbreads as before; mix with an equal quantity of cucumber cut in dice, and then with cream dressing.', 'Line the inner side of lettuce nests with slices of radish, one overlapping another (do not remove the pink skin from the radish).', 'Put in a spoonful of the salad and garnish each nest with a small radish cut to resemble a flower.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0119', 'Chicken Salad', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, 'Use two parts of cold cooked chicken to one part of celery.', [I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('pim-ola', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry')], ['Use two parts of cold cooked chicken to one part of celery.', 'Marinate and drain the chicken, add the celery, and mix with mayonnaise or boiled dressing.', 'Arrange the salad in nests of lettuce leaves and put a pim-ola in the centre of each nest.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0120', 'Chicken Salad, No. 2', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, 'Prepare the salad as before; dispose in a mound on a bed of lettuce leaves and mask with mayonnaise.', [I('capers', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood')], ['Prepare the salad as before; dispose in a mound on a bed of lettuce leaves and mask with mayonnaise.', 'By the use of stoned olives, cut in halves, divide the surface into quarters.', 'Fill two opposite sections with whites of eggs chopped fine, a third with capers or olives chopped fine, and the fourth with sifted yolks of eggs.', 'Garnish with lettuce and curled celery.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0121', 'French Chicken Salad', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Cook the meats of English walnuts in well-seasoned chicken stock until tender; remove the brown skin and break in pieces; when cold mix with chicken and celery, and proceed as in preceding recipes.', [I('celery', 1, '', 'Produce'), I('truffles', 1, '', 'Pantry'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood')], ['Cook the meats of English walnuts in well-seasoned chicken stock until tender; remove the brown skin and break in pieces; when cold mix with chicken and celery, and proceed as in preceding recipes.', 'The walnuts give the salad a flavor similar to that produced in France by the use of truffles.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0122', 'Chicken-and-Fresh-Mushroom Salad', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Peel mushroom caps, break in pieces, and saute in melted butter five or six minutes with a slice of onion; add chicken liquor or hot water and let simmer until tender.', [I('butter', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('mushroom', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('chicken liquor', 1, '', 'Meat & Seafood')], ['Peel mushroom caps, break in pieces, and saute in melted butter five or six minutes with a slice of onion; add chicken liquor or hot water and let simmer until tender.', 'Remove from the liquor, cover, and set aside to cool.', 'Add the liquor and the peelings and stalks of the mushrooms to the liquid in which the chicken is to be cooked.', 'Use the chicken and mushrooms with celery or lettuce in any recipe for chicken salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0123', 'Chicken Salad, No. 3', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Arrange the salad upon the centre of the dish and mask with mayonnaise; then with pastry bag and tube pipe the dressing in some fanciful design.', [I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood')], ['Arrange the salad upon the centre of the dish and mask with mayonnaise; then with pastry bag and tube pipe the dressing in some fanciful design.', 'Surround with a border of aspic jelly, tinted a delicate green.', 'The jelly may be cut in blocks or triangles, or into small cubes, and then massed about the salad.', 'Cut the aspic in a cold room; first dip the knife in hot water and wipe dry.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0124', 'Chicken Salad, No. 4', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, 'Cut one cucumber and one bunch of round radishes in thin slices, and add two-thirds a cup of shredded celery.', [I('round radishes in thin slices', 1, 'bunch', 'Produce'), I('shredded celery', 0.6666666666666666, 'cup', 'Produce'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('vinegar or lemon juice', 2, 'tablespoonfuls', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('chicken', 3, 'cups', 'Meat & Seafood'), I('lemon juice or vinegar', 2, 'tablespoonfuls', 'Produce'), I('cucumber', 1, '', 'Produce'), I('paprica', 1, '', 'Pantry'), I('pepper', 1, '', 'Produce'), I('white pepper', 1, '', 'Produce'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('radishes', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry')], ['Cut one cucumber and one bunch of round radishes in thin slices, and add two-thirds a cup of shredded celery.', 'Season with four tablespoonfuls of oil, two tablespoonfuls of vinegar or lemon juice, half a teaspoonful of salt and a dash of paprica.', 'Put on a bed of shredded lettuce or on heart leaves of lettuce; cover with three cups of chicken cut in cubes and marinated an hour or more with four tablespoonfuls of oil, two tablespoonfuls of lemon juice or vinegar, half a teaspoonful of salt and a dash of white pepper.', 'Mask with mayonnaise.', 'Arrange some bits of celery, an inch and a half in length and curled on one end, about the salad, with a bit of yolk of egg in the centre of each.', 'Or, instead of the celery and yolk of egg, use sliced radishes (do not remove the red skin), having the slices overlap one another.', 'Finish the top with tuft of lettuce or curled celery and yolk of egg.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0125', 'Mushroom Salad with Medallions of Chicken', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Bone a chicken, fill with forcemeat, and cook until tender in stock; then press between two dishes until cold.', [I('butter', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('truffles', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('green butter', 1, '', 'Dairy & Eggs'), I('mushroom', 1, '', 'Produce')], ['Bone a chicken, fill with forcemeat, and cook until tender in stock; then press between two dishes until cold.', 'Cut in slices and stamp in rounds.', 'Stamp out an equal number of rounds from cooked tongue.', 'Spread these with "green butter" (see Green-Butter Sandwiches) and place the rounds of chicken evenly on the tops.', 'Coat these with white chaud-froid sauce and decorate in some design with truffles, ham or tongue.', 'When the sauce has set, brush over the medallions with aspic jelly, cold but not set.', 'When thoroughly cold stamp out with a round cutter.', 'Drain and dry a can of white button mushrooms; toss them about in cold aspic until they are well coated.', 'When the jelly has become fixed about them, pile high in the centre of a serving-dish; arrange the medallions about them, resting on delicate leaves of lettuce.', 'Serve mayonnaise or tartare sauce with the salad.', 'Sweetbreads may be substituted for the chicken, and fresh mushrooms for the canned.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0126', 'Mousse-de-Poulet Salad', 'American', ["section-various-compound-salads"], 'chicken', 'soup', 45, 'Scald one cup of milk, cream or _well-reduced_ chicken stock (the last is preferable); beat the yolks of three eggs slightly, add one-fourth a teaspoonful, each, of common salt and celery salt, and a dash of paprica,…', [I('milk', 1, 'cup', 'Dairy & Eggs'), I('chicken liquor or water', 0.25, 'cup', 'Meat & Seafood'), I('whipped cream', 1, 'cup', 'Dairy & Eggs'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('celery salt', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('gelatine', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('chicken liquor', 1, '', 'Meat & Seafood')], ['Scald one cup of milk, cream or _well-reduced_ chicken stock (the last is preferable); beat the yolks of three eggs slightly, add one-fourth a teaspoonful, each, of common salt and celery salt, and a dash of paprica, and cook as a boiled custard.', 'Remove from the fire and add one-fourth a package of gelatine (one tablespoonful of granulated gelatine), softened in one-fourth a cup of chicken liquor or water.', 'Strain over half a cup of cooked chicken (white meat), chopped and pounded in a mortar and passed through a sieve.', 'Stir over ice water until the mixture is perfectly smooth and begins to set, then fold into it one cup of whipped cream.', 'Turn into a ring mould, and, when chilled and well set, turn on to a bed of lettuce and fill in the centre with equal parts of celery and English walnuts, blanched, sliced and mixed with a French dressing.', 'The half-cup of chicken, well pressed down, should weigh four ounces.', 'The chicken broth should be strong and well flavored.', 'Either one cup of whipped cream, or one cup of cream, whipped, may be used.', 'The latter gives a firmer mousse, more pronounced in flavor; the former, a mousse of a lighter and more delicate consistency, and one more delicate in flavor.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0127', 'Mousse-de-Poulet, No. 2', 'American', ["section-various-compound-salads"], 'veg', 'green', 45, 'Mould the mousse in small cups; turn out on to a slice of chilled tomato resting upon a lettuce leaf; garnish with mayonnaise dressing, decorating both the tomato and the mousse.', [I('lettuce', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Mould the mousse in small cups; turn out on to a slice of chilled tomato resting upon a lettuce leaf; garnish with mayonnaise dressing, decorating both the tomato and the mousse.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0128', 'Mousse-de-Poulet, No. 3', 'American', ["section-various-compound-salads"], 'beef', 'green', 45, 'Mould the mousse in a ring mould and fill in the centre with equal parts of cucumber or asparagus tips and diced sweetbread; marinate the sweetbread with French dressing, and drain thoroughly before mixing with the…', [I('cucumber', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('sweetbread', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Mould the mousse in a ring mould and fill in the centre with equal parts of cucumber or asparagus tips and diced sweetbread; marinate the sweetbread with French dressing, and drain thoroughly before mixing with the cucumber or asparagus.', 'Garnish with mayonnaise dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0129', 'Mousse-de-Poulet, No. 4', 'American', ["section-various-compound-salads"], 'veg', 'green', 45, 'Fill in the centre of the ring with diced cucumbers and sliced radishes, mixed with cream dressing.', [I('cream', 1, '', 'Dairy & Eggs'), I('cucumbers', 1, '', 'Produce'), I('radishes', 1, '', 'Produce'), I('cream dressing', 1, '', 'Dairy & Eggs')], ['Fill in the centre of the ring with diced cucumbers and sliced radishes, mixed with cream dressing.', 'Garnish with cream dressing, using pastry bag and tube, and radishes cut to resemble roses.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0130', 'Mousse-de-Poulet, No. 5', 'American', ["section-various-compound-salads"], 'beef', 'dessert', 45, 'Fill in the centre of the ring with mushrooms and sweetbread dressed with a French dressing.', [I('butter', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('sweetbread', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Fill in the centre of the ring with mushrooms and sweetbread dressed with a French dressing.', 'If the button mushrooms (canned) are used, cut in quarters; if fresh mushrooms are at hand, remove the stems and peel the caps; break into pieces and saute in a little hot butter; then add hot water or stock and let simmer until tender (fifteen or twenty minutes).', 'Drain and chill before using.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0131', 'Turkey-and-Chestnut Salad', 'American', ["section-various-compound-salads"], 'turkey', 'green', 45, 'Prepare the chestnuts as previously directed, using twice as much turkey meat, light or dark, cut into small cubes.', [I('lettuce', 1, '', 'Produce'), I('chestnuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('turkey', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('mayonnaise dressing', 1, '', 'Pantry'), I('chestnut', 1, '', 'Produce')], ['Prepare the chestnuts as previously directed, using twice as much turkey meat, light or dark, cut into small cubes.', 'Serve with lettuce and French, boiled or mayonnaise dressing, as desired.', 'Marinate and drain the meat before adding the nuts.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0132', 'Duck-and-Olive Salad', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Cut the meat from a duck in small pieces, and slice pim-olas very thin; use two tablespoonfuls of pim-olas to a cup of meat.', [I('pim-olas to a cup of meat', 2, 'tablespoonfuls', 'Meat & Seafood'), I('cress', 1, '', 'Produce'), I('duck', 1, '', 'Meat & Seafood'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('olive', 1, '', 'Produce')], ['Cut the meat from a duck in small pieces, and slice pim-olas very thin; use two tablespoonfuls of pim-olas to a cup of meat.', 'Serve on a bed of cress with a French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0133', 'Duck-and-Orange Salad', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, 'Slice the oranges lengthwise; use twice as much flesh as fruit.', [I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('oil', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('oranges', 1, '', 'Produce'), I('orange', 1, '', 'Produce'), I('duck', 1, '', 'Meat & Seafood')], ['Slice the oranges lengthwise; use twice as much flesh as fruit.', 'Dress with oil, salt and paprica, and serve on lettuce leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0134', 'Ham Salad', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, 'Soak half a tablespoonful of granulated gelatine in one tablespoonful and a half of cold water, and dissolve in three-fourths a cup of hot chicken liquor.', [I('cold water', 1.5, 'tablespoonfuls', 'Pantry'), I('hot chicken liquor', 0.75, 'cup', 'Meat & Seafood'), I('chopped ham', 1, 'cup', 'Meat & Seafood'), I('_thick_ cream', 1, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('gelatine', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('chicken liquor', 1, '', 'Meat & Seafood')], ['Soak half a tablespoonful of granulated gelatine in one tablespoonful and a half of cold water, and dissolve in three-fourths a cup of hot chicken liquor.', 'Strain over one cup of chopped ham and stir until the mixture begins to thicken, then fold in one cup of _thick_ cream beaten stiff; add, also, a few grains of paprica and salt, if needed.', 'Mould in a ring mould, and, when set and cold, turn from the mould; fill in the centre with lettuce arranged like a cup, and fill the cup with mayonnaise.', 'Or, serve with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0135', 'Bacon Salad', 'American', ["section-various-compound-salads"], 'pork', 'green', 45, 'Cut six or eight slices of tender bacon into small squares and fry until they are delicately browned; then drain on soft paper.', [I('fat', 6, 'tablespoonfuls', 'Pantry'), I('vinegar or lemon juice', 2, 'tablespoonfuls', 'Produce'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('mustard', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('bacon', 1, '', 'Meat & Seafood')], ['Cut six or eight slices of tender bacon into small squares and fry until they are delicately browned; then drain on soft paper.', 'Heat six tablespoonfuls of the fat and two tablespoonfuls of vinegar or lemon juice; beat together the yolks of three eggs and one-fourth a teaspoonful, each, of paprica and mustard, and cook with the fat and vinegar over hot water until the mixture thickens slightly.', 'When the dressing is cold cut a head of lettuce into narrow ribbons, toss the lettuce and bits of bacon together, and mix with the dressing.', 'Serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0136', 'Italian Salad', 'American', ["section-various-compound-salads"], 'chicken', 'green', 45, '(MISS COHEN.', [I('herrings, soaked in milk over night', 2, '', 'Meat & Seafood'), I('boiled potatoes, cut in very small dice', 3, '', 'Produce'), I('cucumber pickles', 2, 'tablespoonfuls', 'Produce'), I('capers', 1, 'tablespoonful', 'Pantry'), I('small boiled beets', 2, '', 'Produce'), I('1 cup) of cold roast chicken', 0.5, 'pound', 'Meat & Seafood'), I('1 cup) of boiled tongue', 0.5, 'pound', 'Meat & Seafood'), I('apples, pared and finely', 2, '', 'Produce'), I('carrots, cooked and finely', 2, '', 'Produce'), I('celery root, cooked and', 1, '', 'Produce'), I('pecan nuts, broken fine', 0.5, 'cup', 'Produce'), I('little onion juice', 1, '', 'Produce'), I('pecan nuts', 0.5, 'cup', 'Produce'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('onion juice', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('beet', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('pickled beet', 1, '', 'Produce')], ['Mix the ingredients together thoroughly; add mayonnaise to moisten well.', 'Serve on a flat dish.', 'Mask the top with mayonnaise, then divide into squares like a checker-board, using fine-shredded pimento or pickled beet to mark the divisions; fill in alternate squares with sifted yolk of hard-boiled egg and the remaining squares with chopped white of egg.', 'Garnish the edge with parsley, and set in the centre half a hard-boiled egg cut lengthwise in points and filled with capers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0137', 'Pate de Foie Gras, Moulded in Aspic', 'American', ["section-various-compound-salads"], 'veg', 'dessert', 45, 'Cover the bottoms of small-sized timbale moulds with a little aspic jelly; decorate the jelly with bits of royal custard and capers; cover with more aspic; then add, alternately, layers of _pate de foie gras_ and aspic,…', [I('aspic', 1, '', 'Pantry'), I('capers', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('aspic jelly', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('pate de foie gras', 1, '', 'Pantry'), I('foie gras', 1, '', 'Pantry')], ['Cover the bottoms of small-sized timbale moulds with a little aspic jelly; decorate the jelly with bits of royal custard and capers; cover with more aspic; then add, alternately, layers of _pate de foie gras_ and aspic, until the mould is filled.', 'Turn on to shredded lettuce and garnish with mayonnaise, using pastry bag and tube.', 'Arrange on individual dishes, so as not to disarrange the dressing in serving.', 'Or, garnish with a chopped cucumber dressed with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0138', 'Spinach-and-Tongue Salad', 'American', ["section-various-compound-salads"], 'beef', 'dessert', 45, 'INGREDIENTS.', [I('peck of spinach', 0.25, '', 'Produce'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('paprica', 1, 'dash', 'Pantry'), I('oil or butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('Sauce tartare', 1, '', 'Pantry'), I('pepper', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('tongue', 1, '', 'Meat & Seafood')], ['Cook the spinach in salted boiling water until tender; drain, and chop very fine, and season with salt, pepper, oil and lemon juice.', 'Press into small, well-buttered moulds or cups.', 'Have ready thin, round slices of cold boiled or braised tongue, the slices a trifle larger than the cups of spinach.', 'When the spinach is cold turn it from the moulds on to the rounds of tongue, and press a star of sauce tartare on the top of each mould.', 'Garnish with parsley and slices of lemon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0139', 'Spinach-and-Egg Salad', 'American', ["section-various-compound-salads"], 'eggs', 'green', 45, '(See cut facing page 84.', [I('egg whites', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('spinach', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Prepare and mould the spinach as in the preceding recipe.', 'Have ready, also, some cold boiled eggs and mayonnaise.', 'Turn the spinach from the moulds on to nests of shredded lettuce.', 'Dispose, chain fashion, around the base of the spinach, the whites of the eggs cut in rings, and press a star of mayonnaise in the centre of each ring.', 'Pass the yolks through a sieve and sprinkle over the tops of the mounds, and place above this the round ends of the whites.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0140', 'Marguerite Salad', 'American', ["section-various-compound-salads"], 'eggs', 'green', 45, '(See cut facing page 84.', [I('egg whites', 1, '', 'Dairy & Eggs'), I('garden cress', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('cress', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs')], ['Arrange garden cress on a serving-dish; in the centre dispose whites of hard-boiled eggs cut in eighths lengthwise, to resemble the petals of a flower, and sift the yolks into the centre.', 'When ready to serve, sprinkle with French dressing and toss together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0141', 'Easter Salad', 'American', ["section-various-compound-salads"], 'eggs', 'green', 45, 'With the smooth sides of butter-hands roll Neufchatel cheese into small egg shapes.', [I('paprica', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('neufchatel cheese', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('radishes', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('neufchatel', 1, '', 'Pantry')], ['With the smooth sides of butter-hands roll Neufchatel cheese into small egg shapes.', 'Cut long radishes into straws and season with French dressing.', 'Scatter the straws in lettuce nests, arrange the eggs in the nests, sprinkle with dressing, and fleck with chopped parsley or paprica.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0142', 'Easter Salad, No. 2', 'American', ["section-various-compound-salads"], 'eggs', 'dessert', 45, 'Arrange flat nests of shredded lettuce on individual plates.', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('paprica', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs'), I('neufchatel cheese', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('neufchatel', 1, '', 'Pantry')], ['Arrange flat nests of shredded lettuce on individual plates.', 'Cut a five-cent Neufchatel cheese in three pieces; roll each piece into a ball and flatten to resemble the white of a poached egg, having the cheese about one-fourth an inch in thickness.', 'These may be shaped upon a plate and then removed carefully with a spatula to the nests of lettuce.', 'With pastry bag and plain tube put a mound of mayonnaise on the centre of each cake of cheese, to represent the yolk of an egg.', 'Serve thoroughly chilled.', 'A dash of pepper (paprica preferred) may decorate the top of the dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0143', 'Country Salad', 'American', ["section-various-compound-salads"], 'beef', 'soup', 45, '(See cut facing page 86.', [I('parsley', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('cucumber', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('turnip', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('cucumber pickles', 1, '', 'Produce'), I('tongue', 1, '', 'Meat & Seafood'), I('corned beef', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Cut cold boiled corned beef or tongue into thin strips and pile in the centre of a serving-dish.', 'Cook potato balls in meat broth until tender; blanch and cool, roll in mayonnaise or boiled dressing, and dispose about the meat.', 'About these put a ring of celery cut fine, then cooked carrot and turnip cut in straws.', 'Garnish with parsley and cucumber pickles cut in fans.', 'Serve with additional dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0144', 'Orange-and-Litchi Nut Salad', 'American', ["section-various-compound-salads"], 'veg', 'green', 45, 'Peel the oranges and cut them into lengthwise slices.', [I('lemon', 1, '', 'Produce'), I('sugar', 1, '', 'Pantry'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('orange', 1, '', 'Produce'), I('oranges', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('raisins', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('litchi', 1, '', 'Pantry'), I('litchi nut', 1, '', 'Produce')], ['Peel the oranges and cut them into lengthwise slices.', 'Crush the shells of the nuts, take out the meats, and remove the stones; cut the nut meats in halves.', 'Mix the nuts with oil, a tablespoonful to a cup, and sprinkle the orange slices with oil; add also a little lemon juice if the oranges are sweet.', 'Garnish with slices of orange from which the skin has not been taken, also, if desired, with lettuce dressed with French dressing.', 'The oil and lettuce may be omitted, using sugar in place; little, however, will be needed, as the nuts are sweet, tasting much like raisins.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0145', 'Green-and-White Salad', 'American', ["section-various-compound-salads"], 'chicken', 'dessert', 45, 'Cut cooked chicken or sweetbreads in half-inch cubes; remove the skin and seeds from white grapes, and cut each grape in halves; cut tender blanched celery stalks in small pieces.', [I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs'), I('meat', 1, '', 'Meat & Seafood')], ['Cut cooked chicken or sweetbreads in half-inch cubes; remove the skin and seeds from white grapes, and cut each grape in halves; cut tender blanched celery stalks in small pieces.', 'Take equal portions of celery and meat and half as much of seeded grapes.', 'Mix with French dressing; the meat should stand in the dressing an hour or more, when ready to serve.', 'Serve in nests of lettuce.', 'Dispose a little white mayonnaise or cream dressing on each nest.', 'Garnish with halves of blanched pistachio nuts.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0146', 'Fruit Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'dessert', 45, '(_Sweet, to serve with cake.', [I('bananas', 4, '', 'Produce'), I('oranges', 4, '', 'Produce'), I('pineapple', 1, '', 'Produce'), I('strawberries', 1, '', 'Pantry')], ['Peel and slice four bananas, also four oranges, lengthwise, carefully removing pith and seeds.', 'Dissect half a ripe pineapple, taking the pulp from the core in small pieces with a silver fork.', 'Hull and wash a part of a basket of strawberries.', 'Arrange the fruit in the salad-bowl, making each layer smaller than the preceding.', 'Pour over the dressing given below, and serve thoroughly chilled.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0147', 'Dressing for Fruit Salad', 'American', ["section-fruit-and-nut-salads"], 'eggs', 'green', 45, '(_Sweet.', [I('sugar', 1, 'cup', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('lemons', 2, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('wine', 1, '', 'Pantry')], ['Boil one cup of sugar and half a cup of water five minutes, then pour on to the beaten yolks of three eggs; return to the fire and cook over hot water, stirring constantly until thickened slightly; cool, and add the juice of two lemons.', 'Half a cup of wine may be used in the place of the lemon juice, retaining one tablespoonful of the lemon juice.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0148', 'Fruit Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, '(_June.', [I('strawberries', 1, 'cup', 'Pantry'), I('olive oil', 0.25, 'cup', 'Produce'), I('honey', 1, 'tablespoonful', 'Pantry'), I('bananas', 2, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('olive', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('oranges', 1, '', 'Produce'), I('pineapple', 1, '', 'Produce'), I('figs', 1, '', 'Produce')], ['Pare lengthwise a _ripe_ pineapple and remove the eyes.', 'With a fork dislodge from the hard centre the single fruits (the lines left by the bracts will indicate the places where the divisions should be made).', 'Slice _lengthwise_ three sweet oranges, after removing the peel and white skin.', 'Peel and slice two bananas, and cut in halves lengthwise one cup of strawberries.', 'If the fruit be sweet, use the juice of half a lemon, otherwise omit it.', 'Beat to an emulsion one-fourth a cup of olive oil, one tablespoonful of honey, and, if needed, the lemon juice; toss the fruit, together or separately, in the dressing, and serve on delicate leaves of lettuce.', 'The most striking effect is produced by dressing each kind of fruit separately, thus massing each color by itself.', 'When new figs are seasonable, they may be used in fruit salads to take the place of the honey.', 'If the pineapple be of large size, more dressing will be required.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0149', 'Fruit-and-Nut Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Peel neatly three oranges and slice them lengthwise; also cut three bananas in thin slices.', [I('white grapes', 0.5, 'pound', 'Produce'), I('English walnuts', 0.25, 'pound', 'Produce'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('lemon juice--less', 2, 'tablespoonfuls', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('oranges', 3, '', 'Produce'), I('bananas', 3, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce')], ['Peel neatly three oranges and slice them lengthwise; also cut three bananas in thin slices.', 'Skin and seed half a pound of white grapes, and blanch and slice the meats of one-fourth a pound of English walnuts.', 'Serve very cold on lettuce leaves, dressed with four tablespoonfuls of oil, two tablespoonfuls of lemon juice--less, if the oranges are sour--and half a teaspoonful of salt.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0150', 'Fruit-and-Nut Salad, No. 2', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Skin and seed half a pound of white grapes; blanch and slice half a pound of English walnuts or almonds.', [I('white grapes', 0.5, 'pound', 'Produce'), I('English walnuts or almonds', 0.5, 'pound', 'Produce'), I('oil', 4, 'tablespoonfuls', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('lemon juice', 2, 'tablespoonfuls', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('cherries', 1, '', 'Pantry'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('maraschino', 1, '', 'Pantry')], ['Skin and seed half a pound of white grapes; blanch and slice half a pound of English walnuts or almonds.', 'Toss with four tablespoonfuls of oil, one-fourth a teaspoonful of salt and two tablespoonfuls of lemon juice.', 'Serve in nests of lettuce.', 'Garnish the nests with maraschino cherries.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0151', 'Cherry Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, '(MRS. PETERSON.', [I('salt', 1, '', 'Herbs & Spices'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('cherries', 1, '', 'Pantry'), I('cherry', 1, '', 'Pantry')], ['(MRS.', 'PETERSON.)', 'Marinate as many hazelnuts as cherries with plenty of oil, half as much lemon juice as oil, and a little salt, one or two hours.', 'Put a nut in the place of the stone in the cherries.', 'Sprinkle with oil and a very little lemon juice, and serve in lettuce nests.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0152', 'Fruit Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, '(_Winter.', [I('English walnuts', 0.25, 'pound', 'Produce'), I('oil', 3, 'tablespoonfuls', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('oranges', 2, '', 'Produce'), I('bananas', 3, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('cherries', 1, '', 'Pantry'), I('figs', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry')], ['Peel two oranges; with a sharp knife cut between the pulp and the skin and remove the section entire.', 'Slice the meats of one-fourth a pound of English walnuts.', 'Of one-fourth a pound of figs select a few for a garnish and cut the rest in thin slices.', 'Slice three bananas.', 'Toss half the ingredients with two or three tablespoonfuls of oil, and, if the oranges are sweet, toss again with one tablespoonful of lemon juice.', 'Arrange in a mound on a salad-dish.', 'Put the rest of the fruit, each kind separately, on the mound in sections; garnish the edge and top with heart leaves of lettuce, and add stars of mayonnaise and candied cherries here and there.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0153', 'Orange-and-Walnut Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'This is a particularly good salad to serve with game.', [I('oil', 3, 'tablespoonfuls', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('watercress', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('orange', 1, '', 'Produce'), I('oranges', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('game', 1, '', 'Pantry'), I('walnut', 1, '', 'Produce')], ['This is a particularly good salad to serve with game.', 'Select fine oranges, remove the peel and every particle of white skin, and slice very thin lengthwise.', 'Slice English walnuts, blanched or plain.', 'To each pint of orange slices add half a pint (scant) of the sliced nuts; dress with three tablespoonfuls of oil, one-fourth a teaspoonful of salt, and, if the oranges are particularly sweet, a tablespoonful of lemon juice.', 'Serve on a bed of watercress or lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0154', 'Celery-and-Chestnut Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Shell and blanch the chestnuts; then boil about fifteen minutes, or until tender; drain and cool.', [I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('chestnuts', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('chestnut', 1, '', 'Produce')], ['Shell and blanch the chestnuts; then boil about fifteen minutes, or until tender; drain and cool.', 'When cool cut into quarters, add an equal quantity of fine-sliced celery, dress with French dressing, and serve on lettuce leaves.', 'Sliced pimentos may be added.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0155', 'Apple,-Celery-and-English-Walnut Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'dessert', 45, 'Peel and cut the apples in small cubes; blanch the nuts and break in pieces, and cut the celery in thin slices; marinate the apple and nuts with oil and lemon juice half an hour; drain, add the celery and mayonnaise…', [I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('apple', 1, '', 'Produce'), I('apples', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry'), I('walnut', 1, '', 'Produce')], ['Peel and cut the apples in small cubes; blanch the nuts and break in pieces, and cut the celery in thin slices; marinate the apple and nuts with oil and lemon juice half an hour; drain, add the celery and mayonnaise dressing, and serve in cups made by removing the pulp from red apples.', 'Cut the edges of the apples in small vandykes; keep fresh in cold water until ready to serve.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0156', 'Orange-and-Banana Salad', 'American', ["section-fruit-and-nut-salads"], 'eggs', 'green', 45, '(_Sweet.', [I('sherry wine', 0.5, 'cup', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('sugar', 0.5, 'cup', 'Pantry'), I('dessicated cocoanut', 0.5, 'cup', 'Produce'), I('egg whites', 1, '', 'Dairy & Eggs'), I('oranges', 2, '', 'Produce'), I('bananas', 3, '', 'Produce'), I('cheese', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry'), I('orange', 1, '', 'Produce'), I('banana', 1, '', 'Produce')], ['Stir the juice of two oranges, half a cup of sherry wine, one tablespoonful of lemon juice, half a cup of sugar and the unbeaten white of an egg, over the fire, until the boiling-point is reached; let simmer slowly ten minutes, strain through a cheese-cloth, and, when thoroughly chilled, pour over three bananas and three oranges, sliced and mixed together in a salad-bowl.', 'Sprinkle with half a cup of dessicated cocoanut.', 'Serve thoroughly chilled.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0157', 'Fig-and-Nut Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Slice pulled figs, cooked and cooled, and mix with them a few slices of walnuts or blanched almonds.', [I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('figs', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('claret', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('cream dressing', 1, '', 'Dairy & Eggs'), I('fig', 1, '', 'Produce')], ['Slice pulled figs, cooked and cooled, and mix with them a few slices of walnuts or blanched almonds.', 'Serve with French dressing made of claret and lemon juice instead of vinegar, or with a cream dressing.', 'In using the cream dressing, mix the ingredients with a little of the dressing and dispose additional dressing here and there, using the forcing-bag and tube.', 'When available, fresh figs are preferable to those that have been cooked.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0158', 'Grapefruit Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Cut the chilled fruit in halves, crosswise, and take out the pulp with a spoon; dress with French dressing.', [I('lettuce', 1, '', 'Produce'), I('grapefruit', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry')], ['Cut the chilled fruit in halves, crosswise, and take out the pulp with a spoon; dress with French dressing.', 'The juice of the grapefruit may be used in the place of other acid, and mayonnaise in the place of French dressing.', 'Serve on lettuce leaves, or return to the skin from which the pulp was removed.', 'The edge of the grapefruit cup may be cut in vandykes, or otherwise ornamented.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0159', 'Turquoise Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'dessert', 45, 'Mix together equal parts of celery and tart apple cut in match-like pieces, and one or two pimentos cut in similar pieces.', [I('cream', 1, '', 'Dairy & Eggs'), I('whipped cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('apple', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry')], ['Mix together equal parts of celery and tart apple cut in match-like pieces, and one or two pimentos cut in similar pieces.', 'Dress with mayonnaise made light with whipped cream.', 'Serve in nests of lettuce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0160', 'Turquoise Salad, No. 2', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Use pineapple in the place of the apple; serve in a mound on a bed of lettuce leaves.', [I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('apple', 1, '', 'Produce'), I('pineapple', 1, '', 'Produce')], ['Use pineapple in the place of the apple; serve in a mound on a bed of lettuce leaves.', 'Garnish with stars cut from the pimentos with French cutter, curled celery, and heart leaves of celery.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0161', 'Salad Chiffonade', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Seed two green peppers, boil two or three minutes, then cut in shreds.', [I('tomatoes', 3, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('endive', 1, '', 'Produce'), I('green peppers', 1, '', 'Produce'), I('grapefruit', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry')], ['Seed two green peppers, boil two or three minutes, then cut in shreds.', 'Shred the light and dark leaves of a head of lettuce, or endive, separately.', 'Cut three tomatoes in shreds.', 'Remove the peel and skin from one large grapefruit.', 'Serve with French dressing, seasoning, and then arranging each article separately upon the serving-dish, having a circle of light and then dark green material about the edge.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0162', 'Peach-and-Almond Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Blanch the almonds and cut in thin slices.', [I('cream', 1, '', 'Dairy & Eggs'), I('whipped cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('peaches', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('peach', 1, '', 'Produce'), I('almond', 1, '', 'Produce')], ['Blanch the almonds and cut in thin slices.', 'Chill the peaches, peel, and cut in slices; use one-fifth as much in bulk of sliced nuts as sliced peaches.', 'Serve with French dressing, or with mayonnaise made white with whipped cream.', 'Garnish the edge with delicate lettuce leaves and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0163', 'Peach Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, '(_English style.', [I('peaches', 1, '', 'Produce'), I('tea', 1, '', 'Pantry'), I('rose petals', 1, '', 'Pantry'), I('tea-rose petals', 1, '', 'Pantry'), I('champagne', 1, '', 'Meat & Seafood'), I('peach', 1, '', 'Produce')], ['Cut ripe, fine-flavored peaches into quarters, after removing the skins.', 'Cover with champagne, thoroughly chilled, and sprinkle with tea-rose petals.', 'Serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0164', 'Peach,-Strawberry-and-Cherry Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, '(_London style.', [I('rose', 1, '', 'Pantry'), I('sugar', 1, '', 'Pantry'), I('powdered sugar', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('peaches', 1, '', 'Produce'), I('cherries', 1, '', 'Pantry'), I('strawberries', 1, '', 'Pantry'), I('wine', 1, '', 'Pantry'), I('rose petals', 1, '', 'Pantry'), I('hungarian wine', 1, '', 'Pantry'), I('peach', 1, '', 'Produce'), I('cherry', 1, '', 'Pantry'), I('strawberry', 1, '', 'Produce')], ['Let a large handful of fresh rose petals stand an hour or two in a cool place in a cup of Hungarian wine.', 'Strain out the leaves and pour the wine over a quart of mixed fruit,--peaches pared and cut in quarters, strawberries hulled and cut in halves, and cherries stoned,--all thoroughly chilled.', 'Let a handful of rose petals stand an hour or two in a cup of thick cream; then strain the cream, sweeten slightly with powdered sugar, whip to a stiff froth, and use as a garnish for the fruit.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0165', 'Grapefruit, Pineapple, and Pimento Salad', 'American', ["section-fruit-and-nut-salads"], 'veg', 'green', 45, 'Cut a large grapefruit in halves and remove the pulp with a sharp knife to avoid crushing it; remove half the pulp of a large pineapple from the core with a fork, after carefully removing the unedible outside.', [I('sugar', 1, '', 'Pantry'), I('lettuce', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('pineapple', 1, '', 'Produce'), I('grapefruit', 1, '', 'Produce'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry')], ['Cut a large grapefruit in halves and remove the pulp with a sharp knife to avoid crushing it; remove half the pulp of a large pineapple from the core with a fork, after carefully removing the unedible outside.', 'Dress with white mayonnaise and serve upon crisp lettuce hearts.', 'Garnish with tiny bits of pimento. 2d.--Omit the pimento, lettuce and mayonnaise, and dress with sherry wine and sugar.', 'For a Christmas salad, use the first formula and canned pineapple if the fresh be not at hand.', 'Dispose the dressed pineapple and grapefruit upon shredded lettuce, having a circle of heart leaves around the edge.', 'Dot here and there with small stars cut from the red pimento with a French cutter.', 'Or chop the pimento fine and dispose in the shape of a large five-pointed star in the centre of the dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0166', 'Aspic Jelly', 'American', ["section-aspic-jelly"], 'eggs', 'dessert', 45, 'To one quart of highly seasoned stock, freed from all fat, add the juice of a lemon, a bay leaf, half a cup of wine and one box of gelatine soaked in a cup of cold water.', [I('highly seasoned stock', 1, 'quart', 'Pantry'), I('wine', 0.5, 'cup', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('bay leaf', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('gelatine', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('aspic', 1, '', 'Pantry')], ['To one quart of highly seasoned stock, freed from all fat, add the juice of a lemon, a bay leaf, half a cup of wine and one box of gelatine soaked in a cup of cold water.', 'Beat into the mixture the slightly beaten whites and crushed shells of two eggs.', 'Heat to the boiling-point, stirring constantly, and let boil five minutes.', 'After standing ten minutes skim off the froth, etc., and strain through a cheese-cloth folded double and held in a colander.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0167', 'Aspic for Garnishing', 'American', ["section-aspic-jelly"], 'veg', 'dessert', 45, 'Pour the liquid jelly into a new tin to the depth of half an inch.', [I('aspic', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Pour the liquid jelly into a new tin to the depth of half an inch.', 'Wring a napkin out of cold water and spread it smoothly over the meat-board.', 'Dip the pan in warm water and turn the jelly onto the napkin; stamp in rounds, diamonds or other fanciful shapes.', 'If blocks of greater thickness be required, fill the pan to the required depth with the liquid aspic.', 'When turned from the mould, cut in squares or diamonds with a knife, wiped dry after having been dipped in hot water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0168', 'Consomme for Aspic Jelly', 'American', ["section-aspic-jelly"], 'chicken', 'soup', 45, 'Cut two pounds of beef from the under part of the round and two pounds of shin of veal into small pieces; crack the bones in the shin.', [I('shin of veal into small pieces', 2, 'pounds', 'Meat & Seafood'), I('lean ham', 1, 'ounce', 'Meat & Seafood'), I('cloves', 4, '', 'Herbs & Spices'), I('salt', 1, '', 'Herbs & Spices'), I('mace', 1, '', 'Herbs & Spices'), I('thyme', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('turnip', 1, '', 'Produce'), I('ham', 1, '', 'Meat & Seafood'), I('beef', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('consomme', 1, '', 'Pantry'), I('bay leaves', 2, '', 'Herbs & Spices')], ['Cut two pounds of beef from the under part of the round and two pounds of shin of veal into small pieces; crack the bones in the shin.', 'Place over the fire with two and a half quarts of cold water; add one ounce of lean ham.', 'Heat slowly, and cook just below the boiling-point two or three hours; then add to the kettle a three-pound fowl, and allow it to remain till tender.', 'Put some marrow into the frying-pan, and when hot saute in it a small onion cut fine, two tablespoonfuls, each, of chopped celery, carrot and turnip; add to the soup kettle, removing the fowl, together with a sprig, each, of parsley, thyme and summer savory, two bay leaves, a small blade of mace, four cloves, two peppercorns and one scant tablespoonful of salt.', 'Let simmer about an hour and a half; then strain and let cool.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0169', 'Chicken Stock for Aspic Jelly', 'American', ["section-aspic-jelly"], 'chicken', 'dessert', 45, 'Put a four-pound fowl and a few bits of veal from the neck over the fire in three pints of cold water.', [I('cloves', 2, '', 'Herbs & Spices'), I('salt', 1, '', 'Herbs & Spices'), I('mace', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('veal', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood')], ['Put a four-pound fowl and a few bits of veal from the neck over the fire in three pints of cold water.', 'Heat slowly to the boiling-point, let boil five minutes, then skim and let simmer until the fowl is nearly tender.', 'Now add an onion and half a sliced carrot, a stalk of celery, a teaspoonful of sweet herbs tied in a bag with a sprig of parsley, two cloves, a blade of mace, eight peppercorns and a teaspoonful of salt.', 'Remove the fowl when tender, and let the stock simmer until reduced to about one quart; strain, and set aside to become cool.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0170', 'Second Stock for Use in Sauces, Etc', 'American', ["section-aspic-jelly"], 'beef', 'dessert', 45, 'Break the bones from roasts; add the tough or browned bits of meat and fat; add also the flank ends from chops and steaks, cut small (there should always be a few bits of fresh meat), and cover with cold water.', [I('water used', 2, 'quarts', 'Pantry'), I('celery', 2, 'stalks', 'Produce'), I('sweet herbs', 2, 'teaspoonfuls', 'Produce'), I('butter or drippings', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('stock', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('chops', 1, '', 'Meat & Seafood')], ['Break the bones from roasts; add the tough or browned bits of meat and fat; add also the flank ends from chops and steaks, cut small (there should always be a few bits of fresh meat), and cover with cold water.', 'Heat slowly and let simmer two or three hours, then add, for each two quarts of water used, one-fourth a cup, each, of chopped onion and carrot, two stalks of celery and a tomato cut small, two teaspoonfuls of sweet herbs, two sprigs of parsley browned in two tablespoonfuls of butter or drippings, and cook about an hour.', 'Strain and let cool.', 'Stock will keep a day or two in summer and nearly a week in winter, if the cake of fat that forms upon the top be left undisturbed.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0171', 'Fish Stock', 'American', ["section-aspic-jelly"], 'fish', 'dessert', 45, '(_For use in fish aspic, or any fish dish.', [I('inexpensive fish', 2, 'pounds', 'Meat & Seafood'), I('sweet herbs', 1, 'teaspoonful', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry')], ['Cover the bones and trimmings from the fish that is to be used for the salad with cold water; add, if convenient, the body bones of a lobster or two.', 'Add also one or two pounds of an inexpensive fish, and a pint of water for each pound of fish.', 'All must be fresh.', 'Bring the water slowly to the boiling-point and let simmer an hour, then add, for each quart of water, one tablespoonful, each, of chopped onion and carrot, a sprig of parsley and one teaspoonful of sweet herbs, sauted delicately in two tablespoonfuls of butter.', 'Season to taste with salt and cayenne.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0172', 'Aspic Jelly from Bouillon Capsules, Etc', 'American', ["section-aspic-jelly"], 'beef', 'dessert', 45, 'Put over the fire one-fourth a cup, each, of onion and carrot, sauted in two tablespoonfuls of butter, two stalks of celery, a bay leaf, half a dozen peppercorns and two or three cloves, with one quart of water; add…', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('celery', 2, 'stalks', 'Produce'), I('peppercorns', 0.5, 'dozen', 'Produce'), I('cloves', 3, '', 'Herbs & Spices'), I('egg', 1, '', 'Dairy & Eggs'), I('bay leaf', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('carrot', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood'), I('gelatine', 1, '', 'Pantry'), I('bouillon', 1, '', 'Pantry'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry')], ['Put over the fire one-fourth a cup, each, of onion and carrot, sauted in two tablespoonfuls of butter, two stalks of celery, a bay leaf, half a dozen peppercorns and two or three cloves, with one quart of water; add three bouillon capsules, or three teaspoonfuls of beef extract (not home-made) dissolved in two cups of boiling water; let simmer about half an hour, then add one box of gelatine softened in one cup of cold water, any additional flavoring desired, and the slightly beaten white and crushed shell of one egg (more shells will be advantageous).', 'Bring slowly to the boiling-point, stirring constantly meanwhile, and let simmer five minutes; let stand in a hot place ten minutes, then skim and strain through a cheese-cloth folded double.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0173', 'White Chaud-froid Sauce', 'American', ["section-aspic-jelly"], 'chicken', 'dessert', 45, '(_For coating joints of fowl or game, or medallions of fowl, tongue or sweetbreads.', [I('white sauce', 1, 'pint', 'Pantry'), I('aspic jelly', 0.75, 'cup', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('game', 1, '', 'Pantry'), I('tongue', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry')], ['To one pint of white sauce, made of white stock, add three-fourths a cup of aspic jelly and one tablespoonful of lemon juice; let simmer until reduced to the consistency of very thick cream; remove the butter from the top and let cool slightly before using.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0174', 'Cheese Custard', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'dessert', 45, '(MRS. DIMON.', [I('cheese', 1, 'cup', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('cayenne', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['(MRS.', 'DIMON.)', 'Butter a baking-dish, put in a layer of bread cut in pieces one inch square with crust removed, sprinkle thin-sliced cheese over the bread, dust with salt and paprica, or a few grains of cayenne.', 'Add other layers of bread and cheese, seasoning as before, using in all half a small loaf of bread, one cup of cheese and half a teaspoonful of salt.', 'Beat two eggs slightly, add one pint of milk, and pour the mixture over the bread and cheese.', 'Bake about half an hour in a moderate oven.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0175', 'Cheese Souffle', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'dessert', 45, 'Cook together four tablespoonfuls of butter and two tablespoonfuls of flour, into which have been sifted one-fourth a teaspoonful, each, of soda and mustard and a few grains of cayenne.', [I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('milk', 0.5, 'cup', 'Dairy & Eggs'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('egg whites', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('cayenne', 1, '', 'Herbs & Spices'), I('mustard', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('grated cheese', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery'), I('soda', 1, '', 'Pantry')], ['Cook together four tablespoonfuls of butter and two tablespoonfuls of flour, into which have been sifted one-fourth a teaspoonful, each, of soda and mustard and a few grains of cayenne.', 'Add gradually half a cup of milk.', 'When the sauce boils, remove from the fire and stir into it one cup of grated cheese (half a pound) and the yolks of three eggs, beaten until light.', 'When well mixed, fold in the stiffly beaten whites of three eggs.', 'Bake in a buttered pudding-dish, in a moderate oven, about twenty-five minutes, or in individual dishes, paper cases, or china shirring-cups, about twelve minutes.', '_Serve at once_ from the dish or dishes.', 'The souffle will "stand up" a little better, if three-fourths a cup of milk be used in place of the half-cup as given, and half a cup of stale grated bread be added before the cheese; but it will not be quite so delicate.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0176', 'Cheese Ramequins', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'dessert', 45, 'Put four tablespoonfuls of butter and half a cup of water into a saucepan.', [I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('water into a saucepan', 0.5, 'cup', 'Pantry'), I('flour', 0.5, 'cup', 'Pantry'), I('grated Parmesan cheese', 2, 'ounces', 'Dairy & Eggs'), I('milk or water', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('milk', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Put four tablespoonfuls of butter and half a cup of water into a saucepan.', 'When these boil, add half a cup of flour and a few grains, each, of salt and paprica; cook and stir until the mixture cleaves from the pan.', 'Turn into a mixing-bowl and beat in two ounces of grated Parmesan cheese; then beat in, one at a time, two eggs.', 'On a well-buttered baking-sheet shape the paste into flat circular pieces about an inch in diameter.', 'Brush over the tops with beaten egg, diluted with one or two tablespoonfuls of milk or water, and put three or four dice of cheese on each.', 'Bake about fifteen minutes.', 'Serve very hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0177', 'Cheese Straws', 'American', ["section-cheese-dishes-served-with-salads"], 'veg', 'green', 45, 'Roll plain or puff paste into a rectangular sheet one-fourth an inch thick.', [I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('grated cheese', 1, '', 'Dairy & Eggs'), I('flour', 1.5, 'cups', 'Pantry'), I('puff paste', 1, '', 'Pantry')], ['Roll plain or puff paste into a rectangular sheet one-fourth an inch thick.', 'Sprinkle one-half with grated cheese (any kind of cheese will do, but Parmesan is preferred); also add a few grains of cayenne and salt.', 'Fold the other half over this and press the edges together closely.', 'Fold again to make three layers, turn half-way round, pat and roll out to the thickness of one-fourth an inch.', 'Sprinkle one half with cheese and proceed as before.', 'Continue rolling and adding the cheese, until, to one cup and a half of flour, from half to a whole cup of cheese has been used.', 'After the last rolling, cut into bands half an inch wide, or into rings and straws one-fourth an inch wide.', 'The straws and bands should be four or five inches in length, and the rings large enough to hold three or four straws.', 'Serve the bands piled in log-cabin style on a doylie-covered plate.', 'If the paste be made expressly for the straws, the cheese and cayenne may be mixed into the flour with the butter, thus diminishing time in making.', 'Bake in a moderate oven until delicately browned.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0178', 'Gnochi a la Romaine', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'green', 45, 'Melt four tablespoonfuls of butter; cook in it four tablespoonfuls, each, of cornstarch and flour and half a teaspoonful of salt, then add gradually one pint of milk.', [I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('grated Parmesan cheese', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('yolks', 1, '', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry'), I('romaine', 1, '', 'Produce')], ['Melt four tablespoonfuls of butter; cook in it four tablespoonfuls, each, of cornstarch and flour and half a teaspoonful of salt, then add gradually one pint of milk.', 'When thick and smooth stir in the beaten yolks of two eggs, add four tablespoonfuls of grated Parmesan cheese, and spread on a buttered pan to cool.', 'Just before serving, cut the paste in shapes, lay on a baking-sheet, and brown delicately in the oven.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0179', 'Cheese Balls', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'green', 45, 'Mix together thoroughly one cup and a half of grated cheese, one tablespoonful of flour, one-fourth, a teaspoonful of salt and a few grains of cayenne; then add the whites of three eggs, beaten stiff.', [I('flour', 1, 'tablespoonful', 'Pantry'), I('egg whites', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('grated cheese', 1.5, 'cups', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('cracker crumbs', 1, '', 'Bakery')], ['Mix together thoroughly one cup and a half of grated cheese, one tablespoonful of flour, one-fourth, a teaspoonful of salt and a few grains of cayenne; then add the whites of three eggs, beaten stiff.', 'Shape in small balls and roll in cracker crumbs, sifted or crushed to a fine meal; fry in deep fat and drain on soft paper.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0180', 'Individual Souffles of Cheese, Iced', 'American', ["section-cheese-dishes-served-with-salads"], 'chicken', 'green', 45, '(See cut facing page 106.', [I('grated Parmesan', 0.5, 'cup', 'Pantry'), I('grated Gruyere cheese', 0.25, 'cup', 'Dairy & Eggs'), I('chicken aspic', 0.6666666666666666, 'cup', 'Meat & Seafood'), I('whipped cream', 1, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry')], ['Mix half a cup of grated Parmesan and one-fourth a cup of grated Gruyere cheese and one-fourth a teaspoonful of paprica with two-thirds a cup of chicken aspic, cold, but not set.', 'Stir over ice water until just beginning to form, then fold into it one cup of whipped cream.', 'Fasten strips of white paper around paper souffle cases, letting the strips rise an inch and a half above the cases, fixing in place with sealing-wax, mucilage, or a stitch.', 'Fill the cases and the papers surrounding them with the cheese mixture, and set them in a pail or mould that is thoroughly chilled.', 'Press the cover down over a paper, and pack in equal parts of ice and salt.', 'Let stand an hour.', 'Before serving, remove the paper, sprinkle the tops with buttered crumbs, browned, and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0181', 'Cheese Croquettes', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'green', 45, '(TOURAINE.', [I('butter', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 0.25, 'cup', 'Pantry'), I('milk', 0.6666666666666666, 'cup', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('mild cheese, cut in small cubes', 1, 'cup', 'Dairy & Eggs'), I('grated Gruyere cheese', 0.5, 'cup', 'Dairy & Eggs'), I('Salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('mild cheese', 1, 'cup', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('grated cheese', 1, '', 'Dairy & Eggs')], ['Make a sauce of the butter, flour and milk; add the yolks, slightly beaten, and beat thoroughly; add the grated cheese, and, when melted, remove from the fire; add the seasonings and cubes of cheese.', 'Spread in a shallow pan to cool.', 'Cut in any shape desired, dip in crumbs, then in egg, and again in crumbs; fry in deep fat and drain on brown paper.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0182', 'Cheese Aigrettes', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'green', 45, 'INGREDIENTS.', [I('water', 0.5, 'cup', 'Pantry'), I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('flour', 0.5, 'cup', 'Pantry'), I('eggs, with yolk of a third', 2, '', 'Dairy & Eggs'), I('cayenne and salt', 1, 'grains', 'Herbs & Spices'), I('1/4 a cup) of', 2, 'ounces', 'Pantry'), I('Hot fat', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Boil the water and butter, sift in the flour with the salt and cayenne; stir and cook until the mixture cleaves from the side of the pan.', 'When the mixture has slightly cooled, add the eggs, one at a time, beating in each egg thoroughly before another is added.', 'Lastly, add the cheese.', 'Drop, by teaspoonfuls, into hot fat and fry a golden brown.', 'Drain on soft paper and serve piled on a folded napkin.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0183', 'Cheese d\'Artois', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'dessert', 45, 'INGREDIENTS.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg whites', 1, '', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('Salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('grated Parmesan cheese', 2, 'ounces', 'Dairy & Eggs'), I('plain or puff paste', 0.25, 'pound', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('puff paste', 1, '', 'Pantry')], ['Cream the butter, beat in the eggs, and add the cheese with a few grains, each, of salt and paprica.', 'Roll the pastry very thin and cut it into two rectangular pieces; lay one of these on a baking-sheet and spread with the cheese mixture; cover this with the second piece of pastry.', 'Score with a knife in strips one inch wide and about three inches long, brush over with beaten egg, and bake about fifteen minutes.', 'Cut out the strips while hot.', 'Serve at once, or reheat before serving.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0184', 'Cheese Fritters', 'American', ["section-cheese-dishes-served-with-salads"], 'eggs', 'dessert', 45, 'Slice thin half a dozen large tart apples (select apples that cook quickly), and prepare half as many thin slices of cheese.', [I('apple', 2, 'slices', 'Produce'), I('eggs', 2, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('mustard', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('apples', 1, '', 'Produce')], ['Slice thin half a dozen large tart apples (select apples that cook quickly), and prepare half as many thin slices of cheese.', 'Beat up one or two eggs, and season with salt, mustard and pepper.', 'Soak the cheese in the egg mixture, then put each slice between two slices of apple, sandwich style; dip in the beaten egg, saute in hot butter, and serve hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0185', 'Salad of Lettuce with Cheese and Vegetable Macedoine', 'American', ["section-cheese-dishes-served-with-salads"], 'veg', 'dessert', 45, 'Mix together a ten-cent cream cheese, a canned pimento (red) cut in tiny cubes, one-fourth a cup of small green string beans, cut in cubes, five olives, chopped fine, and enough cream to hold the mixture together.', [I('small green string beans', 0.25, 'cup', 'Produce'), I('olives', 5, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('pimento', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('french dressing', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Mix together a ten-cent cream cheese, a canned pimento (red) cut in tiny cubes, one-fourth a cup of small green string beans, cut in cubes, five olives, chopped fine, and enough cream to hold the mixture together.', 'When thoroughly mixed, use a piece of paraffine or confectioner\'s paper to handle and give the mixture the original shape.', 'Let stand in a cold place, wrapped in the paper, until ready to serve, then dispose in the centre of a salad dish, lined with lettuce leaves, dressed with French dressing.', 'Slice the cheese with a silver knife before sending to table.', 'At luncheon, mayonnaise may be served in a dish apart.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0186', 'Ham-and-Tongue Sandwiches', 'American', ["section-savory-sandwiches"], 'pork', 'dessert', 45, 'Chop two parts of cold tongue and one part of cold ham (one-fourth as much fat ham as lean) very fine; pound in a mortar, and season with paprica and a little mixed mustard.', [I('bread', 1, 'piece', 'Bakery'), I('together', 2, 'pieces', 'Pantry'), I('mixed', 1, '', 'Pantry'), I('paprica', 1, '', 'Pantry'), I('mustard', 1, '', 'Herbs & Spices'), I('mixed mustard', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('meat', 1, '', 'Meat & Seafood'), I('fat ham', 1, '', 'Meat & Seafood')], ['Chop two parts of cold tongue and one part of cold ham (one-fourth as much fat ham as lean) very fine; pound in a mortar, and season with paprica and a little mixed mustard.', 'Spread butter on one piece of bread, the meat mixture on the other, and press the two pieces together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0187', 'Ham-and-Egg Sandwiches', 'American', ["section-savory-sandwiches"], 'pork', 'dessert', 45, 'Chop the ham and pound smooth in a mortar; pass the yolks of hard-boiled eggs through a sieve; mix the yolks with an equal amount of mayonnaise dressing.', [I('bread lightly', 1, 'piece', 'Bakery'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('ham', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('mayonnaise', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Chop the ham and pound smooth in a mortar; pass the yolks of hard-boiled eggs through a sieve; mix the yolks with an equal amount of mayonnaise dressing.', 'Butter one piece of bread lightly and spread with the ham, spread the other piece with the egg and dressing, and press the two together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0188', 'Corned-Beef Sandwiches', 'American', ["section-savory-sandwiches"], 'beef', 'toast', 45, 'Chop the cold meat very fine, using one-fourth of fat meat.', [I('mustard', 1, '', 'Herbs & Spices'), I('meat', 1, '', 'Meat & Seafood'), I('cold meat', 1, '', 'Meat & Seafood'), I('fat meat', 1, '', 'Meat & Seafood'), I('brownbread', 1, '', 'Bakery'), I('boston brownbread', 1, '', 'Bakery'), I('french mustard', 1, '', 'Herbs & Spices'), I('corned beef', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood')], ['Chop the cold meat very fine, using one-fourth of fat meat.', 'Work into the meat French mustard, or any "made" mustard, to taste, and prepare the sandwiches in the usual way.', 'Boston brownbread combines well with this preparation.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0189', 'Tongue-and-Veal (or Chicken) Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'dessert', 45, 'Use a little less of the chopped tongue than of the other kind of meat, and one-half as much chopped celery as meat.', [I('bread with butter', 1, 'piece', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('celery', 1, '', 'Produce'), I('tongue', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('meat', 1, '', 'Meat & Seafood'), I('salad dressing', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood')], ['Use a little less of the chopped tongue than of the other kind of meat, and one-half as much chopped celery as meat.', 'Mix with salad dressing.', 'Spread one piece of bread with butter, the other with the mixture, and press together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0190', 'Celery Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'dessert', 45, 'Chop crisp celery very fine and mix with salad dressing.', [I('bread with butter', 1, 'piece', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('celery', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('salad dressing', 1, '', 'Pantry')], ['Chop crisp celery very fine and mix with salad dressing.', 'Spread one piece of bread with butter, the other with a thin layer of the mixture.', 'With a sharp knife split open the round stems of celery tips and put them between the bread, so that the tips will just show on the edges.', 'Tie with narrow ribbon, light-green in color.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0191', 'Sardine Sandwiches', 'American', ["section-savory-sandwiches"], 'fish', 'toast', 45, 'Use, in bulk, equal parts of yolks of well-cooked eggs, rubbed to a smooth paste, and the flesh of sardines, freed from skin and bones and pounded in a mortar; season to taste with a few drops of tobasco sauce and lemon…', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('lemon juice', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery'), I('sardine', 1, '', 'Meat & Seafood')], ['Use, in bulk, equal parts of yolks of well-cooked eggs, rubbed to a smooth paste, and the flesh of sardines, freed from skin and bones and pounded in a mortar; season to taste with a few drops of tobasco sauce and lemon juice, and spread as usual.', 'Crackers may be used in the place of bread, if the sandwiches be prepared just before using, otherwise the crackers lose their crispness.', 'Garnish with slices of lemon and parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0192', 'Caviare Sandwich Rolls', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'To each two tablespoonfuls of caviare add ten drops of onion juice and a few drops of lemon juice, and mix together thoroughly.', [I('onion juice', 10, 'drops', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('caviare', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery'), I('rolls', 1, '', 'Bakery')], ['To each two tablespoonfuls of caviare add ten drops of onion juice and a few drops of lemon juice, and mix together thoroughly.', 'Remove the crust from a fresh, moist loaf of bread, cut in thin slices, spread each slice very delicately with butter and the caviare mixture, roll up in a roll and tie with ribbon one-fourth an inch wide, or pin with Chinese toothpicks.', 'The bread should not be more than twelve hours old.', 'If fear be lest the bread will not be sufficiently moist to roll, wrap the loaf, when taken from the oven, in a damp cloth and then in a dry one; keep in this fashion until ready for use.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0193', 'Russian Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Slightly butter thin slices of bread; moisten fine-chopped olives with mayonnaise dressing and spread upon the buttered slices; spread other slices with Neufchatel, or any cream cheese, and press together in pairs.', [I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('olives', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('mayonnaise', 1, '', 'Pantry'), I('neufchatel', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Slightly butter thin slices of bread; moisten fine-chopped olives with mayonnaise dressing and spread upon the buttered slices; spread other slices with Neufchatel, or any cream cheese, and press together in pairs.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0194', 'Mushroom-and-Lobster Sandwiches', 'American', ["section-savory-sandwiches"], 'seafood', 'toast', 45, 'Saute the caps of half a pound of mushrooms in a little butter about five minutes, adding half a sliced onion if desired.', [I('butter', 1, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('catsup', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('mushroom', 1, '', 'Produce')], ['Saute the caps of half a pound of mushrooms in a little butter about five minutes, adding half a sliced onion if desired.', 'Cover with highly seasoned stock and let simmer until very tender; chop and press through a sieve, and, if very moist, reduce to the consistency of a thick puree.', 'Add an equal quantity of lobster meat pounded smooth in a mortar.', 'Season to taste with salt, pepper, lemon juice and, if desired, tomato catsup.', 'When cool use as any filling.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0195', 'Cheese-and-English-Walnut Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'green', 45, 'INGREDIENTS.', [I('grated cheese', 0.25, 'pound', 'Dairy & Eggs'), I('butter', 0.25, 'pound', 'Dairy & Eggs'), I('English walnut meats', 0.25, 'pound', 'Produce'), I('Salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('English walnut meats', 0.25, 'pound', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('nuts', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('vegetable', 1, '', 'Pantry'), I('brownbread', 1, '', 'Bakery')], ['Work the butter to a cream, add the seasonings and the grated cheese gradually; then mix in the nuts, which should be _sliced_ very thin.', 'Spread the mixture upon bits of bread and press together in pairs.', 'Particularly good made of brownbread and served with a simple vegetable salad!'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0196', 'Egg-and-Spinach Sandwiches', 'American', ["section-savory-sandwiches"], 'eggs', 'dessert', 45, 'Use cold boiled spinach, which when hot was chopped very fine or pressed through a colander, and sifted yolks of well-cooked eggs.', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('spinach', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('sauce tartare', 1, '', 'Pantry')], ['Use cold boiled spinach, which when hot was chopped very fine or pressed through a colander, and sifted yolks of well-cooked eggs.', 'Mix the spinach with sauce tartare and spread on one bit of bread, spread the other with butter and sifted yolk of egg; press together.', 'Garnish the serving-dish with parsley and cooked eggs cut in quarters lengthwise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0197', 'Cress-and-Egg Sandwiches', 'American', ["section-savory-sandwiches"], 'eggs', 'toast', 45, 'Pick the leaves from fresh cress, chop or break apart, season with French dressing, and proceed as above.', [I('cress', 1, '', 'Produce'), I('french dressing', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Pick the leaves from fresh cress, chop or break apart, season with French dressing, and proceed as above.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0198', 'Imitation Pate-de-Foie-Gras Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'toast', 45, 'Chop half an onion and saute in a little butter; when delicately browned, add five or six chicken livers and saute them on both sides.', [I('butter', 1, '', 'Dairy & Eggs'), I('curry', 1, '', 'Herbs & Spices'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('mustard', 1, '', 'Herbs & Spices'), I('curry powder', 1, '', 'Herbs & Spices'), I('onion', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood'), I('pate de foie gras', 1, '', 'Pantry'), I('foie gras', 1, '', 'Pantry')], ['Chop half an onion and saute in a little butter; when delicately browned, add five or six chicken livers and saute them on both sides.', 'Cover with well-seasoned chicken stock and let simmer until tender.', 'Mash the livers fine with a wooden spoon and press them through a sieve; season with salt, paprica, mustard, or a dash of curry powder.', 'Press into a cup, pour melted butter over the top, and set away in a cool place.', 'When ready to serve, remove the butter and prepare the sandwiches after the usual manner.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0199', 'Chicken Rolls', 'American', ["section-savory-sandwiches"], 'chicken', 'toast', 45, 'INGREDIENTS.', [I('from the breast of chicken', 4, 'ounces', 'Meat & Seafood'), I('braised tongue', 4, 'ounces', 'Meat & Seafood'), I('celery salt', 0.5, 'teaspoonful', 'Produce'), I('cayenne', 1, 'grains', 'Herbs & Spices'), I('anchovy paste', 1, 'teaspoonful', 'Meat & Seafood'), I('mayonnaise or boiled dressing', 4, 'tablespoonfuls', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('boiled dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('rolls', 1, '', 'Bakery')], ['Chop the meat and pound to a paste in a mortar; add the seasonings and mix well.', 'Remove the crust from a loaf of moist bread; cut in very thin slices, trim each slice into a rectangular shape, spread lightly with soft butter and then with the mixture.', 'Roll the slices and tie them with ribbon.', 'Omit the anchovy paste, if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0200', 'Epicurean Sandwiches', 'American', ["section-savory-sandwiches"], 'seafood', 'dessert', 45, 'Cream four tablespoonfuls of butter and one teaspoonful of mustard.', [I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('mustard', 1, 'teaspoonful', 'Herbs & Spices'), I('together', 2, 'pieces', 'Pantry'), I('hard-boiled eggs', 4, '', 'Dairy & Eggs'), I('small pickles', 4, '', 'Pantry'), I('chives', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('pickles', 1, '', 'Pantry'), I('anchovies', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery')], ['Cream four tablespoonfuls of butter and one teaspoonful of mustard.', 'Press the yolks of four hard-boiled eggs through a sieve and add them to the butter and mustard.', 'Then add four boned anchovies, four small pickles, a teaspoonful of chives and a sprig of tarragon, chopped together until fine.', 'Cut stale bread in fingers or other fanciful shapes, and spread with the mixture.', 'Press two pieces together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0201', 'Halibut-and-Lettuce Sandwiches', 'American', ["section-savory-sandwiches"], 'fish', 'green', 45, 'Put a pound and a half of halibut, a slice of onion, a stalk of celery, four or five peppercorns, one teaspoonful of salt and one tablespoonful of lemon juice in boiling water, and cook, just below the boiling-point,…', [I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('lemon juice in boiling water', 1, 'tablespoonful', 'Produce'), I('thick cream', 0.5, 'cup', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('pepper', 1, '', 'Produce'), I('white pepper', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('mayonnaise', 1, '', 'Pantry'), I('salad dressing', 1, '', 'Pantry')], ['Put a pound and a half of halibut, a slice of onion, a stalk of celery, four or five peppercorns, one teaspoonful of salt and one tablespoonful of lemon juice in boiling water, and cook, just below the boiling-point, ten or fifteen minutes, according to thickness.', 'Remove bone and skin and rub the fish fine with a wooden spoon; add half a cup of thick cream, a teaspoonful of salt, a dash of white pepper and one tablespoonful of lemon juice.', 'Spread this mixture, when cold, on buttered slices of bread, put a lettuce leaf above the mixture, and spread a teaspoonful of mayonnaise or boiled salad dressing on the lettuce; finish with a slice of buttered bread and tie with ribbon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0202', 'Lobster Fingers', 'American', ["section-savory-sandwiches"], 'seafood', 'dessert', 45, 'Chop lobster meat very fine; season to taste with French dressing.', [I('parsley', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('french dressing', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Chop lobster meat very fine; season to taste with French dressing.', 'Cut the bread in pieces about four inches long and an inch and a half wide.', 'Finish as usual.', 'Garnish with parsley and the slender feelers of the lobster.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0203', 'Tower of Babel', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Pile a _variety_ of sandwiches in form of a pyramid (use bread of different colors).', [I('parsley', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('radish', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('rosebuds', 1, '', 'Pantry')], ['Pile a _variety_ of sandwiches in form of a pyramid (use bread of different colors).', 'Arrange a garnish of parsley and radish rosebuds around the base, and on the top a few sprigs of parsley, or celery plumes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0204', 'Nasturtium Folds', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Flavor the butter with nasturtium leaves and blossoms, and with it spread a thin slice of _moist_ bread, which is longer one way than the other.', [I('butter', 1, '', 'Dairy & Eggs'), I('nasturtium', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery')], ['Flavor the butter with nasturtium leaves and blossoms, and with it spread a thin slice of _moist_ bread, which is longer one way than the other.', 'Press fresh nasturtium leaves and blossoms upon the butter and fold one half over the other.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0205', 'Harlequin Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Spread a bit of brownbread with butter and French mustard, and a bit of white bread, cut to fit the former, with butter and cheese creamed together.', [I('mustard', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('brownbread', 1, '', 'Bakery'), I('french mustard', 1, '', 'Herbs & Spices')], ['Spread a bit of brownbread with butter and French mustard, and a bit of white bread, cut to fit the former, with butter and cheese creamed together.', 'Finish as usual.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0206', 'Harlequin Sandwiches, No. 2', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Spread the brownbread with butter and cheese creamed together, and the white bread with butter, then with cucumber, chopped fine and seasoned with French dressing, to which a few drops of onion juice have been added.', [I('onion juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cucumber', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('french dressing', 1, '', 'Pantry'), I('brownbread', 1, '', 'Bakery')], ['Spread the brownbread with butter and cheese creamed together, and the white bread with butter, then with cucumber, chopped fine and seasoned with French dressing, to which a few drops of onion juice have been added.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0207', 'Beet-and-Cream-Cheese Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'dessert', 45, 'Spread one piece of bread with cream cheese, the other with beets that have been chopped very fine and seasoned with French dressing.', [I('bread with cream cheese', 1, 'piece', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('beets', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('french dressing', 1, '', 'Pantry'), I('beet', 1, '', 'Produce')], ['Spread one piece of bread with cream cheese, the other with beets that have been chopped very fine and seasoned with French dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0208', 'Peanut Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Chop freshly roasted peanuts very fine; then pound them in a mortar until smooth; season with salt and moisten with thick cream.', [I('salt', 1, '', 'Herbs & Spices'), I('cream', 1, '', 'Dairy & Eggs'), I('peanuts', 1, '', 'Produce'), I('peanut', 1, '', 'Produce')], ['Chop freshly roasted peanuts very fine; then pound them in a mortar until smooth; season with salt and moisten with thick cream.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0209', 'Peanut Sandwiches, No. 2', 'American', ["section-savory-sandwiches"], 'veg', 'dessert', 45, 'Mix the prepared peanuts with mayonnaise dressing.', [I('bread', 2, 'pieces', 'Bakery'), I('butter', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('peanuts', 1, '', 'Produce'), I('peanut', 1, '', 'Produce'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Mix the prepared peanuts with mayonnaise dressing.', 'Butter two pieces of bread; spread one with the peanut mixture, the other with shredded lettuce, and press the two together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0210', 'Shad-Roe-and-Yellow-Butter Sandwiches', 'American', ["section-savory-sandwiches"], 'fish', 'toast', 45, 'INGREDIENTS.', [I('butter', 0.25, 'pound', 'Dairy & Eggs'), I('Sifted yolks of 4 eggs', 1, '', 'Dairy & Eggs'), I('paprica', 0.5, 'teaspoonful', 'Pantry'), I('tobasco sauce', 4, 'drops', 'Pantry'), I('very fine-chopped capers', 2, 'teaspoonfuls', 'Meat & Seafood'), I('egg yolks', 4, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('shad roe', 1, 'set', 'Pantry')], ['Cream the butter and add the other ingredients gradually.', 'Prepare as usual.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0211', 'Green-Butter Sandwiches', 'American', ["section-savory-sandwiches"], 'seafood', 'dessert', 45, 'INGREDIENTS.', [I('butter', 0.25, 'pound', 'Dairy & Eggs'), I('peck of spinach', 0.125, '', 'Produce'), I('very fine-chopped parsley', 2, 'tablespoonfuls', 'Produce'), I('anchovies', 6, '', 'Pantry'), I('very fine-chopped capers', 2, 'teaspoonfuls', 'Meat & Seafood'), I('oil', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('fish', 1, '', 'Meat & Seafood')], ['Boil the spinach, drain thoroughly, and press through a piece of muslin.', 'Beat the butter to a cream with a wooden spoon; beat into the butter enough of the spinach pulp to give the required tint of green.', 'Wipe the oil from the anchovies, remove the backbone, and pass through a hair sieve; then add to the colored butter, a little at a time; add also the parsley and capers; chill slightly and use as a filling for sandwiches.', 'These butters are used also to mask or decorate cooked fish for "cold service."'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0212', 'Chicken-Salad Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'green', 45, '(_Chou-paste boxes.', [I('celery', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood')], ['Bake _chou_ paste in long, slender shapes, like eclairs, but narrower and shorter; when cold split apart on the ends and one side and fill with chicken salad.', 'Put the top back in place, after inserting a celery plume at each end.', 'Garnish the serving-dish with celery leaves and pim-olas or olives.', 'Serve other salads in the same way.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0213', 'Mosaic Sandwiches', 'American', ["section-savory-sandwiches"], 'veg', 'dessert', 45, 'Cut the bread, white, brown and graham, as thin as possible, and use four or five pieces in each sandwich, putting them together so that the colors will contrast. Either butter or other filling is admissible.', [I('in each sandwich', 5, 'pieces', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['Cut the bread, white, brown and graham, as thin as possible, and use four or five pieces in each sandwich, putting them together so that the colors will contrast.', 'Either butter or other filling is admissible.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0214', 'Chicken-and-Nut Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'dessert', 45, 'Chop fine the white meat of a cooked chicken and pound to a paste in a mortar.', [I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('oil', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('pecan', 1, '', 'Pantry'), I('pecan nuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('meat', 1, '', 'Meat & Seafood')], ['Chop fine the white meat of a cooked chicken and pound to a paste in a mortar.', 'Season to taste with salt, paprica, oil and lemon juice and spread upon thin bits of bread.', 'Spread other bits of bread, corresponding in shape to the first, with butter; press into the butter English walnuts, pecan nuts or almonds, blanched and _sliced_ very thin.', 'Press corresponding pieces together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0215', 'Aspic Jelly for Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'dessert', 45, 'Soak one box (two ounces) of gelatine in one cup of cold chicken liquor until thoroughly softened.', [I('chicken stock', 3, 'cups', 'Meat & Seafood'), I('egg whites', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('chicken', 1, '', 'Meat & Seafood'), I('gelatine', 1, '', 'Pantry'), I('aspic', 1, '', 'Pantry'), I('aspic jelly', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('chicken liquor', 1, '', 'Meat & Seafood')], ['Soak one box (two ounces) of gelatine in one cup of cold chicken liquor until thoroughly softened.', 'Add to three cups of chicken stock, seasoned with vegetables and sweet herbs according to directions previously given, also the crushed shell and white of one egg, and proceed as for aspic jelly.', 'Turn the liquid jelly into rectangular pans, having it three-eighths of an inch or less in thickness, and set aside in a cool place to harden.', 'When ready to serve, dip the pan in hot water an instant, and turn the jelly on to a paper.', 'With a thin, sharp knife cut the jelly into squares or diamonds, or dip a cutter into hot water and stamp out into hearts or clubs.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0216', 'Lobster Sandwiches with Aspic', 'American', ["section-savory-sandwiches"], 'seafood', 'dessert', 45, 'Chop the lobster fine, mix with mayonnaise dressing to taste, spread upon a bit of aspic, cover with a crisp lettuce leaf, and above this place another piece of aspic spread with the lobster mixture.', [I('lettuce', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Chop the lobster fine, mix with mayonnaise dressing to taste, spread upon a bit of aspic, cover with a crisp lettuce leaf, and above this place another piece of aspic spread with the lobster mixture.', 'Serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0217', 'Halibut Sandwiches with Aspic', 'American', ["section-savory-sandwiches"], 'fish', 'dessert', 45, 'After the aspic is poured into the pans, sprinkle upon it some fine-cut Spanish pimentos.', [I('lettuce', 1, '', 'Produce'), I('cress', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('cucumbers', 1, '', 'Produce'), I('pimentos', 1, '', 'Pantry'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('shrimps', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('aspic', 1, '', 'Pantry'), I('mayonnaise', 1, '', 'Pantry'), I('sauce tartare', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry'), I('halibut', 1, '', 'Meat & Seafood')], ['After the aspic is poured into the pans, sprinkle upon it some fine-cut Spanish pimentos.', 'When ready to serve, prepare as lobster sandwiches with aspic, using fish in the place of lobster, and, if desired, sauce tartare in the place of mayonnaise.', 'Shrimps, salmon or other fish, chicken, veal, tongue, sweetbreads, etc., may be used either with lettuce or with chopped celery, cress, cucumbers, etc.', 'Or the vegetables may be used without either fish, flesh or fowl.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0218', 'Club Sandwiches', 'American', ["section-savory-sandwiches"], 'chicken', 'dessert', 45, '(_Steamer Priscilla style.', [I('lettuce', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('bacon', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery'), I('mayonnaise', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('mayonnaise dressing', 1, '', 'Pantry')], ['Have ready four triangular pieces of toasted bread spread with mayonnaise dressing; cover two of these with lettuce, lay thin slices of cold chicken (white meat) upon the lettuce, over this arrange slices of broiled breakfast bacon, then lettuce, and cover with the other triangles of toast spread with mayonnaise.', 'Trim neatly, arrange on a plate, and garnish with heart leaves of lettuce dipped in mayonnaise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0219', 'Wedding Sandwich Rolls', 'American', ["section-savory-sandwiches"], 'veg', 'toast', 45, 'Wrap bread as it is taken from the oven closely in a towel wrung out of cold water, cover with several thicknesses of dry cloth and set aside about four hours; then cut away the crust, and with a thin, sharp knife cut…', [I('butter', 1, '', 'Dairy & Eggs'), I('nuts', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('meat', 1, '', 'Meat & Seafood'), I('rolls', 1, '', 'Bakery')], ['Wrap bread as it is taken from the oven closely in a towel wrung out of cold water, cover with several thicknesses of dry cloth and set aside about four hours; then cut away the crust, and with a thin, sharp knife cut the loaf or loaves in slices as thin as possible and spread with butter, and, if desired, thin shavings of meat, potted meat or chopped nuts; roll the slices very closely and pile on a serving-dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0220', 'The Milwaukee Sandwich', 'American', ["section-savory-sandwiches"], 'turkey', 'dessert', 45, 'INGREDIENTS.', [I('thin rounds of white bread', 2, '', 'Bakery'), I('thin round of graham or rye bread', 1, '', 'Meat & Seafood'), I('large oysters, broiled or fried', 4, '', 'Meat & Seafood'), I('Breast of cooked chicken', 1, '', 'Meat & Seafood'), I('or turkey', 1, '', 'Meat & Seafood'), I('crisp bacon', 2, 'slices', 'Meat & Seafood'), I('Horseradish', 1, '', 'Produce'), I('small sweet pickles', 4, '', 'Pantry'), I('small radishes', 4, '', 'Produce'), I('tomato, skin removed', 1, '', 'Produce'), I('Tartare sauce', 1, '', 'Pantry'), I('large oysters', 4, '', 'Meat & Seafood'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('oyster', 1, '', 'Meat & Seafood'), I('bread crumbs', 1, '', 'Bakery'), I('mayonnaise', 1, '', 'Pantry'), I('boiled dressing', 1, '', 'Pantry'), I('sauce tartare', 1, '', 'Pantry'), I('sweet pickles', 1, '', 'Pantry')], ['Dip the bread in beaten egg, seasoned with salt and saute to a rich brown in hot butter.', 'Roll the oysters in grated bread crumbs (centre of the loaf) and broil them, or "egg and bread" them, and fry in deep fat.', 'Lay the first slice of bread on a plate over two or three lettuce leaves, put the oysters on the bread, a grating of horseradish on each oyster; cover with the graham or rye bread; on this lay the chicken or turkey cut in thin slices, season with salt and pepper, put on the bacon, and cover with the other slice of bread.', 'On top of the sandwich lay a slice of lemon cut square, and about this dispose the pickles and radishes, to form a star.', 'Serve the tomato on a lettuce leaf at the side.', 'Cut out the hard centre from the tomato and fill the opening with sauce tartare.', 'In making this sauce, add to mayonnaise or boiled dressing, onion, olives, sweet pickles and celery, chopped fine and squeezed dry in a cloth.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0221', 'Fig Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Chop one-fourth a pound of figs very fine, add one-fourth a cup of water, and cook to a smooth paste; add, also, one-third a cup of almonds, blanched, chopped very fine and pounded to a paste with a little rose-water,…', [I('figs very fine', 0.25, 'pound', 'Produce'), I('almonds', 0.3333333333333333, 'cup', 'Produce'), I('lemon', 1, '', 'Produce'), I('figs', 1, '', 'Produce'), I('dates', 1, '', 'Produce'), I('raisins', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('lady-fingers', 1, '', 'Pantry'), I('marmalade', 1, '', 'Pantry'), I('fig', 1, '', 'Produce')], ['Chop one-fourth a pound of figs very fine, add one-fourth a cup of water, and cook to a smooth paste; add, also, one-third a cup of almonds, blanched, chopped very fine and pounded to a paste with a little rose-water, also the juice of half a lemon.', 'When cold spread the mixture upon lady-fingers or cakelets, white or yellow, press another above the mixture, and serve upon a handsome doylie-covered plate.', 'Raisins, dates or marmalade may be used in the place of the figs.', 'The marmalade, of course, requires no cooking.', 'Bread may be used in the place of the cake.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0222', 'French Fruit Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Chop the fruit very fine; use a mixture of cherries, plums, pineapple and angelica root; moisten with wine, orange or lemon juice.', [I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('orange', 1, '', 'Produce'), I('pineapple', 1, '', 'Produce'), I('cherries', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery'), I('wine', 1, '', 'Pantry'), I('lady-fingers', 1, '', 'Pantry'), I('marmalade', 1, '', 'Pantry'), I('french fruit', 1, '', 'Produce')], ['Chop the fruit very fine; use a mixture of cherries, plums, pineapple and angelica root; moisten with wine, orange or lemon juice.', 'Use lady-fingers or bread for the covering.', 'If bread is used, spread lightly with butter; if cake be your choice, spread very lightly with marmalade.', 'Use just enough butter or marmalade to keep the coverings together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0223', 'Date-and-Ginger Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Chop the dates and preserved ginger; moisten with syrup from the ginger jar and a little lemon juice; cook as above, and use with bread or lady-fingers.', [I('lemon', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('ginger', 1, '', 'Herbs & Spices'), I('dates', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('lady-fingers', 1, '', 'Pantry'), I('date', 1, '', 'Produce')], ['Chop the dates and preserved ginger; moisten with syrup from the ginger jar and a little lemon juice; cook as above, and use with bread or lady-fingers.', 'Preserved ginger may be used alone and without cooking.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0224', 'Rose-Leaf Sandwiches', 'American', ["section-sweet-sandwiches"], 'eggs', 'toast', 45, 'Flavor the butter with rose petals according to the directions previously given.', [I('sugar', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('rose petals', 1, '', 'Pantry'), I('rosebuds', 1, '', 'Pantry'), I('lady-fingers', 1, '', 'Pantry')], ['Flavor the butter with rose petals according to the directions previously given.', 'Spread both bits of bread lightly with it and put upon them three or four candied rose petals.', 'If lady-fingers are used, brush them over with white of egg and sugar mixed together.', 'Use but little sugar--just enough to hold the fingers together.', 'The Turkish rose petals that come in little jars are particularly dainty, and adapted to this purpose.', 'Garnish the dish on which they are served with rosebuds and leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0225', 'Violet Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'Prepare in the same manner as in the last number, substituting candied violets for the rose petals, and violets with green leaves for a garnish.', [I('rose petals', 1, '', 'Pantry'), I('candied violets', 1, '', 'Pantry'), I('violets', 1, '', 'Pantry'), I('violet', 1, '', 'Pantry')], ['Prepare in the same manner as in the last number, substituting candied violets for the rose petals, and violets with green leaves for a garnish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0226', 'Honey Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'Spread one bit of white bread with honey pressed from the comb with a wooden spoon, the other bit with butter.', [I('butter', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('honey', 1, '', 'Pantry'), I('white clover', 1, '', 'Herbs & Spices')], ['Spread one bit of white bread with honey pressed from the comb with a wooden spoon, the other bit with butter.', 'Garnish with white clover blossoms and leaves.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0227', 'Puff-Paste Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Roll puff paste very thin (about one-eighth of an inch), cut in fanciful shapes and bake to a delicate brown; add chopped almonds to rich strawberry preserves, or peach marmalade, and spread the mixture between each two…', [I('peach', 1, '', 'Produce'), I('strawberry', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('puff paste', 1, '', 'Pantry'), I('marmalade', 1, '', 'Pantry')], ['Roll puff paste very thin (about one-eighth of an inch), cut in fanciful shapes and bake to a delicate brown; add chopped almonds to rich strawberry preserves, or peach marmalade, and spread the mixture between each two bits of pastry.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0228', 'Pineapple Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'INGREDIENTS.', [I('pineapple juice and pulp', 1, 'cup', 'Produce'), I('sugar', 0.75, 'cup', 'Pantry'), I('Juice of half a lemon', 1, '', 'Produce'), I('Lady-fingers', 1, '', 'Pantry'), I('pineapple juice', 1, 'cup', 'Produce'), I('lemon juice', 1, '', 'Produce')], ['Cook the pineapple, sugar and lemon juice until thick; let cool, and spread upon lady-fingers or sponge drops.', 'Press together in pairs and serve.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0229', 'Whipped-Cream Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'INGREDIENTS.', [I('heavy cream', 1, 'cup', 'Dairy & Eggs'), I('powdered sugar', 0.25, 'cup', 'Pantry'), I('vanilla extract', 0.25, 'teaspoonful', 'Herbs & Spices'), I('Lady-fingers', 1, '', 'Pantry'), I('whipped cream', 1, '', 'Dairy & Eggs')], ['Add the sugar and extract to the cream and beat until solid; let chill, then spread quite thick upon lady-fingers or sponge drops.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0230', 'Whipped-Cream Sandwiches with French Fruit', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'Soak half a cup of fine-cut candied fruit in wine an hour or more.', [I('cream', 1, '', 'Dairy & Eggs'), I('candied fruit', 1, '', 'Produce'), I('wine', 1, '', 'Pantry'), I('whipped cream', 1, '', 'Dairy & Eggs'), I('french fruit', 1, '', 'Produce')], ['Soak half a cup of fine-cut candied fruit in wine an hour or more.', 'Prepare the cream as above, and sprinkle the same with the fruit before putting the sandwiches together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0231', 'Fruit Jelly for Sweet Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'INGREDIENTS.', [I('gelatine', 1, 'box', 'Pantry'), I('cold water', 1, 'cup', 'Pantry'), I('boiling water', 1, 'cup', 'Pantry'), I('sugar', 1, 'cup', 'Pantry'), I('orange juice', 1.5, 'cups', 'Produce'), I('lemon juice', 0.25, 'cup', 'Produce')], ['Soak the gelatine in the cold water and dissolve in the boiling water; add the sugar and strain; when cold add the orange and lemon juice.', 'Mould in sheets three-eighths of an inch thick.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0232', 'Claret Jelly for Sweet Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Substitute claret for the orange juice and prepare as above.', [I('lemon juice', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('orange', 1, '', 'Produce'), I('claret', 1, '', 'Pantry')], ['Substitute claret for the orange juice and prepare as above.', 'Do not omit the lemon juice.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0233', 'Fruit or Claret Jelly Sandwiches with Nuts', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Slice blanched English walnuts and pecan nuts or almonds very thin, and stir into whipped cream.', [I('with the cream', 1, 'piece', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('whipped cream', 1, '', 'Dairy & Eggs'), I('walnuts', 1, '', 'Produce'), I('english walnuts', 1, '', 'Produce'), I('almonds', 1, '', 'Produce'), I('pecan', 1, '', 'Pantry'), I('pecan nuts', 1, '', 'Produce'), I('nuts', 1, '', 'Produce'), I('claret', 1, '', 'Pantry')], ['Slice blanched English walnuts and pecan nuts or almonds very thin, and stir into whipped cream.', 'Stamp out shapes from the jelly.', 'Spread one piece with the cream and nuts and cover with a second piece of jelly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0234', 'With French Fruit', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'Substitute candied fruit for the nuts and proceed as above, or use nuts and fruit together.', [I('nuts', 1, '', 'Produce'), I('candied fruit', 1, '', 'Produce'), I('french fruit', 1, '', 'Produce')], ['Substitute candied fruit for the nuts and proceed as above, or use nuts and fruit together.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0235', 'Cupid\'s Butter Sandwiches', 'American', ["section-sweet-sandwiches"], 'eggs', 'dessert', 45, 'INGREDIENTS.', [I('egg yolks', 1, '', 'Dairy & Eggs'), I('butter', 1, 'cup', 'Dairy & Eggs'), I('powdered sugar', 0.3333333333333333, 'cup', 'Pantry'), I('orange juice', 1, 'teaspoonful', 'Produce'), I('grating of orange rind', 1, '', 'Produce'), I('together', 2, 'slices', 'Pantry'), I('hard-boiled eggs', 4, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('potato', 1, '', 'Produce'), I('angel cake', 1, '', 'Pantry'), I('angel cakelets', 1, '', 'Pantry')], ['Cream the butter, gradually add the yolks of eggs, passed through a potato ricer or sieve, the sugar and orange juice.', 'Spread upon thin slices of angel cake, prepared for sandwiches, or upon angel cakelets or fingers; press two slices together and serve at once.', 'If allowed to stand any length of time, keep covered and in a cool place.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0236', 'Cheese-and-Bar-le-Duc Currant Sandwiches', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Spread wheat bread, prepared for sandwiches, with cream cheese; put two or three currants and a little syrup on each piece of bread, and press two pieces together.', [I('together', 2, 'pieces', 'Pantry'), I('syrup', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('cherries', 1, '', 'Pantry'), I('currants', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('maraschino', 1, '', 'Pantry'), I('honey', 1, '', 'Pantry'), I('bar-le-duc', 1, '', 'Pantry')], ['Spread wheat bread, prepared for sandwiches, with cream cheese; put two or three currants and a little syrup on each piece of bread, and press two pieces together.', 'These may be varied by using sliced maraschino cherries.', 'Either the currants or sliced cherries with a little of the syrup may be mixed with the cheese and then spread upon the bread.', 'Bar-le-Duc currants are imported from France in tiny glasses.', 'The seeds have been removed from the currants, which are cooked in honey.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0237', 'Hunter\'s Sandwich (Switzerland)', 'American', ["section-sweet-sandwiches"], 'veg', 'dessert', 45, 'Spread fresh bread, cut in thin slices, with fresh butter; over this spread a layer of Brie or other cream cheese, and over the cheese spread a layer of honey.', [I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('cream cheese', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('honey', 1, '', 'Pantry')], ['Spread fresh bread, cut in thin slices, with fresh butter; over this spread a layer of Brie or other cream cheese, and over the cheese spread a layer of honey.', 'Press two similarly shaped pieces together and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0238', 'Hunter\'s Sandwich (Ellwanger)', 'American', ["section-sweet-sandwiches"], 'veg', 'toast', 45, 'Prepare as above, substituting maple syrup (or sugar) for the honey.', [I('sugar', 1, '', 'Pantry'), I('honey', 1, '', 'Pantry'), I('maple syrup', 1, '', 'Pantry')], ['Prepare as above, substituting maple syrup (or sugar) for the honey.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0239', 'Two Loaves of Wheat Bread', 'American', ["section-bread-and-chou-paste"], 'veg', 'dessert', 45, 'To two cups of scalded milk or boiled water, in a mixing-bowl, add two tablespoonfuls of sugar, one teaspoonful of salt, and, when the liquid becomes lukewarm, one yeastcake dissolved in half a cup of water, boiled and…', [I('scalded milk or boiled water', 2, 'cups', 'Dairy & Eggs'), I('sugar', 2, 'tablespoonfuls', 'Pantry'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('milk', 1, '', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry'), I('yeastcake', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery')], ['To two cups of scalded milk or boiled water, in a mixing-bowl, add two tablespoonfuls of sugar, one teaspoonful of salt, and, when the liquid becomes lukewarm, one yeastcake dissolved in half a cup of water, boiled and cooled.', 'With a broad-bladed knife cut and mix in enough well-dried flour, sifted, to make a stiff dough (about seven cups).', 'Knead until the dough is elastic; cover, and set to rise in a temperature of about 70 deg.', 'Fahr.', 'When the dough has doubled in bulk, "cut down" and knead slightly without removing from the mixing-bowl.', 'When again double in bulk, shape into two double loaves and set to rise in buttered pans; when it has risen a third time, bake one hour.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0240', 'Entire-Wheat Bread', 'American', ["section-bread-and-chou-paste"], 'veg', 'bowl', 45, 'Use the preceding recipe without change other than in kind of flour and two additional tablespoonfuls of sugar.', [I('sugar', 1, '', 'Pantry'), I('flour', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery')], ['Use the preceding recipe without change other than in kind of flour and two additional tablespoonfuls of sugar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0241', 'Rice Bread', 'American', ["section-bread-and-chou-paste"], 'veg', 'bowl', 45, 'Add three-fourths a cup of rice, cooked until tender and still hot, and, also, two tablespoonfuls of butter, to the milk or water in the first recipe.', [I('rice', 0.75, 'cup', 'Pantry'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['Add three-fourths a cup of rice, cooked until tender and still hot, and, also, two tablespoonfuls of butter, to the milk or water in the first recipe.', 'Other cereals, as oatmeal or cerealine, may be used instead of rice.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0242', 'Salad Rolls', 'American', ["section-bread-and-chou-paste"], 'veg', 'dessert', 45, 'Make a sponge with one cup of milk, one yeastcake dissolved in one-fourth a cup of milk, and about one cup and a half of flour; beat thoroughly, cover, and set to rise in a temperature of about 70 deg.', [I('milk', 1, 'cup', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('melted butter', 0.25, 'cup', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('flour', 1.5, 'cups', 'Pantry'), I('yeastcake', 1, '', 'Pantry'), I('rolls', 1, '', 'Bakery')], ['Make a sponge with one cup of milk, one yeastcake dissolved in one-fourth a cup of milk, and about one cup and a half of flour; beat thoroughly, cover, and set to rise in a temperature of about 70 deg.', 'Fahr.', 'When light add half a teaspoonful of salt, one-fourth a cup of melted butter, and flour enough to knead.', 'Knead until elastic.', 'Set to rise in a temperature of 70 deg.', 'Fahr.', 'When doubled in bulk, cut down and shape into small balls.', 'Set to rise again, covered with a cloth and a dripping-pan.', 'When light press the handle of a small wooden spoon deeply across the centre of each ball, brush with butter and press the edges together.', 'Set the rolls close together in a baking-pan, after brushing over with butter the points of contact.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0243', 'Boston Brownbread', 'American', ["section-bread-and-chou-paste"], 'veg', 'bowl', 45, 'Sift together one cup, each, of yellow corn meal, rye meal and entire-wheat flour, one teaspoonful of salt and three teaspoonfuls of soda.', [I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('soda', 3, 'teaspoonfuls', 'Pantry'), I('molasses', 0.75, 'cup', 'Pantry'), I('thick', 1, 'pint', 'Pantry'), I('milk', 1, '', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry'), I('baking-powder', 1, '', 'Pantry'), I('corn', 1, '', 'Produce'), I('brownbread', 1, '', 'Bakery')], ['Sift together one cup, each, of yellow corn meal, rye meal and entire-wheat flour, one teaspoonful of salt and three teaspoonfuls of soda.', 'Add three-fourths a cup of molasses and one pint of thick, sour milk.', 'Beat thoroughly, and steam in a covered mould three hours and a half.', 'The quantity here given may be steamed in four baking-powder boxes in two hours.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0244', 'Baking-Powder Biscuit', 'American', ["section-bread-and-chou-paste"], 'veg', 'roast', 45, 'Pass through the sieve two or three times four cups of flour, one teaspoonful of salt, and, for each cup of flour, two level teaspoonfuls of baking-powder.', [I('flour', 4, 'cups', 'Pantry'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('butter', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('baking-powder', 1, '', 'Pantry'), I('biscuit', 1, '', 'Bakery')], ['Pass through the sieve two or three times four cups of flour, one teaspoonful of salt, and, for each cup of flour, two level teaspoonfuls of baking-powder.', 'With the tips of the fingers work into the flour one-third a cup of butter.', 'When the mixture looks like meal, mix in gradually nearly one pint of milk, cutting the dough with a knife until well mixed.', 'When it is of a consistency to handle, turn out on to a well-floured board, toss with the knife in the flour, then pat out into a sheet half an inch thick, and cut into rounds.', 'Let the heat of the oven be moderate at first, and increase after the dough has risen.', 'Bake about fifteen minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0245', 'Sandwich Biscuit', 'American', ["section-bread-and-chou-paste"], 'veg', 'toast', 45, 'Prepare the dough as above, roll to about three-eighths an inch in thickness, and cut into rounds.', [I('butter', 1, '', 'Dairy & Eggs'), I('biscuit', 1, '', 'Bakery')], ['Prepare the dough as above, roll to about three-eighths an inch in thickness, and cut into rounds.', 'Spread one half of these with softened butter, and press the others, unbuttered, upon them; bake fifteen or eighteen minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0246', 'Pulled Bread', 'American', ["section-bread-and-chou-paste"], 'veg', 'dessert', 45, '(_To serve with simple salads and cheese.', [I('cheese', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['Remove the crust from a fresh loaf of French bread.', 'Gash the loaf at the ends and pull apart into halves; then cut the halves and pull apart into quarters.', 'Repeat until the pieces are about the thickness of breadsticks.', 'Put on a rack in a dripping-pan, and dry out the moisture in a slow oven; then brown delicately.', 'Keep in a dry place (a tin box is suitable) and reheat in the oven before serving.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0247', 'Chou Paste', 'American', ["section-bread-and-chou-paste"], 'eggs', 'bowl', 45, 'Put a saucepan with half a cup of butter and one cup of boiling water over the fire.', [I('butter', 0.5, 'cup', 'Dairy & Eggs'), I('flour', 1, 'cup', 'Pantry'), I('small eggs', 4, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs')], ['Put a saucepan with half a cup of butter and one cup of boiling water over the fire.', 'When the mixture boils, beat into it one cup of flour.', 'When the dough cleaves from the sides of the saucepan, turn into a bowl and beat in, one at a time, three large or four small eggs.', '* * * * *'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0248', 'To Boil Salted Meats: Ham, Tongue, Etc', 'American', ["section-how-to-boil-meats-for-sandwiches"], 'pork', 'toast', 45, 'Cover the meat with cold water and bring the water slowly to the boiling-point; let boil five minutes, then _slightly_ bubble until the meat is tender.', [I('meat', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood')], ['Cover the meat with cold water and bring the water slowly to the boiling-point; let boil five minutes, then _slightly_ bubble until the meat is tender.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0249', 'To Boil Chicken, Lamb and Other Fresh Meat', 'American', ["section-how-to-boil-meats-for-sandwiches"], 'chicken', 'toast', 45, 'Cover the meat with boiling water, let boil rapidly five minutes, then keep the water just below the boiling-point, or just "quivering" at one side of the saucepan, until the meat is tender.', [I('salt', 1, '', 'Herbs & Spices'), I('meat', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('lamb', 1, '', 'Meat & Seafood')], ['Cover the meat with boiling water, let boil rapidly five minutes, then keep the water just below the boiling-point, or just "quivering" at one side of the saucepan, until the meat is tender.', 'When the meat is about half cooked, add a teaspoonful of salt for each quart of water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0250', 'Potted Meat and Fish for Sandwiches', 'American', ["section-how-to-boil-meats-for-sandwiches"], 'fish', 'toast', 45, 'INGREDIENTS.', [I('tender cooked meat or fish', 1, 'pound', 'Meat & Seafood'), I('fat cooked meat', 2, 'ounces', 'Meat & Seafood'), I('butter', 2, 'ounces', 'Dairy & Eggs'), I('Mace', 1, '', 'Herbs & Spices'), I('anchovy essence', 1, '', 'Meat & Seafood'), I('Pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('cream', 1, '', 'Dairy & Eggs')], ['Chop the meat or fish very fine, then pass through a puree sieve; cream the butter and with a wooden spoon work it into the meat or fish; add seasonings to taste, press the mixture solidly into small jars or cups, and pour melted butter to the depth of one-fourth an inch over the top of the meat.', 'Set aside in a cool place.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0251', 'Filtered Coffee', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'toast', 45, 'INGREDIENTS.', [I('coffee, ground very fine', 0.5, 'cup', 'Pantry'), I('boiling water', 3, 'cups', 'Pantry'), I('About 6 blocks of sugar', 1, '', 'Pantry'), I('cream', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('hot milk', 6, 'tablespoonfuls', 'Dairy & Eggs')], ['Put the coffee into the filter of a well-scalded coffee-pot.', 'Pour the boiling water over the coffee.', 'Serve as soon as the infusion has dripped through the filter.', 'For black coffee use double the quantity of coffee.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0252', 'Boiled Coffee', 'American', ["section-beverages-served-with-sandwiches"], 'eggs', 'toast', 45, 'INGREDIENTS.', [I('ground coffee', 1, 'tablespoonful', 'Pantry'), I('cold water', 1, 'cup', 'Pantry'), I('boiling water', 6, 'cups', 'Pantry'), I('cold water down the spout', 0.5, 'cup', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs')], ['Beat the white and crushed shell of the egg and half the cup of cold water together; mix with the coffee, pour over the boiling water, stir thoroughly, and boil from three to five minutes with the nozzle tightly closed; pour half a cup of cold water down the spout; stir in one tablespoonful of coffee and let stand on the range, without boiling, ten minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0253', 'Five-o\'clock Tea', 'American', ["section-beverages-served-with-sandwiches"], 'beef', 'toast', 45, 'INGREDIENTS.', [I('Tea', 1, '', 'Pantry'), I('Candied ox-heart cherries', 1, '', 'Meat & Seafood'), I('lemon', 1, '', 'Produce'), I('cherry', 1, '', 'Pantry')], ['Fill the tea-ball half full with tea, put the ball into the cup, with a cherry or a slice of lemon, and pour boiling water over them; remove the ball when the tea is of the desired strength.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0254', 'Rich Chocolate', 'American', ["section-beverages-served-with-sandwiches"], 'eggs', 'toast', 45, 'INGREDIENTS.', [I('chocolate', 4, 'ounces', 'Pantry'), I('granulated sugar', 4, 'tablespoonfuls', 'Pantry'), I('hot water', 0.25, 'cup', 'Pantry'), I('scalded milk', 1, 'quart', 'Dairy & Eggs'), I('vanilla extract', 1, 'teaspoonful', 'Herbs & Spices'), I('egg whites', 3, '', 'Dairy & Eggs'), I('thick cream', 1, 'pint', 'Dairy & Eggs'), I('powdered sugar', 0.3333333333333333, 'cup', 'Pantry'), I('eggs', 3, '', 'Dairy & Eggs')], ['Grate the chocolate, add the granulated sugar and hot water, and cook until smooth and glossy; with a whisk beat in the hot milk very gradually, and return to a double boiler to keep hot.', 'Beat the cream until solid.', 'Beat the whites of the eggs until dry, then beat in the powdered sugar and fold the cream into the egg and sugar.', 'Add half of the cream mixture to the chocolate with the vanilla, and mix while the cream is heating.', 'Serve the rest of the cream in spoonfuls upon the chocolate in the cups.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0255', 'Plain Chocolate', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'toast', 45, 'Prepare as in preceding recipe, omitting the cream mixture and such portion of the chocolate as is desired.', [I('cream', 1, '', 'Dairy & Eggs'), I('chocolate', 1, '', 'Pantry')], ['Prepare as in preceding recipe, omitting the cream mixture and such portion of the chocolate as is desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0256', 'Plain Cocoa', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'toast', 45, 'INGREDIENTS.', [I('cocoa', 4, 'teaspoonfuls', 'Pantry'), I('sugar', 4, 'teaspoonfuls', 'Pantry'), I('boiling water, 1 cup of hot milk', 1, 'cup', 'Dairy & Eggs'), I('Whipped cream', 1, '', 'Dairy & Eggs'), I('hot milk', 1, 'cup', 'Dairy & Eggs')], ['Mix the cocoa and sugar, pour over the boiling water, and when boiling again add the hot milk; beat the whipped cream into the hot cocoa, or serve a spoonful upon the top of each cup.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0257', 'Ceylon Cocoa', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'dessert', 45, 'Scald a two-inch piece of paper-bark cinnamon with the milk to be used in making the cocoa.', [I('cinnamon', 1, '', 'Herbs & Spices'), I('milk', 1, '', 'Dairy & Eggs'), I('cocoa', 1, '', 'Pantry')], ['Scald a two-inch piece of paper-bark cinnamon with the milk to be used in making the cocoa.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0258', 'Sultana Cocoa', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'toast', 45, 'Stem and wash half a pound of sultana raisins; let them stand, covered with one quart of boiling water, upon the back of the range an hour or more; filter the water through folds of cheese-cloth and use in making cocoa…', [I('sultana raisins', 0.5, 'pound', 'Produce'), I('cheese', 1, '', 'Dairy & Eggs'), I('raisins', 1, '', 'Produce'), I('chocolate', 1, '', 'Pantry'), I('cocoa', 1, '', 'Pantry')], ['Stem and wash half a pound of sultana raisins; let them stand, covered with one quart of boiling water, upon the back of the range an hour or more; filter the water through folds of cheese-cloth and use in making cocoa or chocolate.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0259', 'Egg Lemonade', 'American', ["section-beverages-served-with-sandwiches"], 'eggs', 'toast', 45, 'INGREDIENTS.', [I('egg', 1, '', 'Dairy & Eggs'), I('sugar', 4, 'tablespoonfuls', 'Pantry'), I('Juice of 2 lemons', 1, '', 'Produce'), I('water', 2, 'cups', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lemon', 1, '', 'Produce')], ['Beat the egg until white and yolk are well mixed; then beat in the sugar, the lemon juice and the water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0260', 'Fruit Punch', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'dessert', 45, 'INGREDIENTS.', [I('pineapple', 1, '', 'Produce'), I('sugar', 4, 'cups', 'Pantry'), I('boiling water', 3, 'cups', 'Pantry'), I('tea, freshly made', 1, 'cup', 'Pantry'), I('lemons', 5, '', 'Produce'), I('oranges', 6, '', 'Produce'), I('strawberry or grape juice', 1, 'pint', 'Produce'), I('maraschino cherries', 0.5, 'pint', 'Pantry'), I('Apollinaris water', 1, 'bottle', 'Pantry'), I('water', 6, 'quarts', 'Pantry'), I('ice', 1, '', 'Pantry'), I('mint', 1, '', 'Pantry'), I('banana', 1, '', 'Produce'), I('strawberries', 1, '', 'Pantry')], ['Grate the pineapple, add the boiling water and the sugar, and boil fifteen minutes; add the tea and strain into the punch-bowl.', 'When cold add the fruit juice, the cherries and the cold water.', 'A short time before serving, add a piece of ice, and, on serving, the Apollinaris water.', 'Strawberries, mint leaves, or slices of banana may be used in the place of the cherries.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0261', 'Punch a la Nantes', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'dessert', 45, 'INGREDIENTS.', [I('rhubarb', 2, 'pounds', 'Pantry'), I('water', 1, 'pint', 'Pantry'), I('bay leaf', 1, '', 'Herbs & Spices'), I('sugar', 1, 'cup', 'Pantry'), I('orange juice', 1, 'cup', 'Produce'), I('lemon juice', 0.25, 'cup', 'Produce'), I('ginger syrup', 0.25, 'cup', 'Herbs & Spices'), I('ice', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs')], ['Cut the rhubarb into pieces without peeling; add the bay leaf and water, and let simmer until the rhubarb is tender; strain through a cheese-cloth.', 'Boil the juice with the sugar five minutes.', 'When cold add the orange and lemon juice, with one-fourth a cup of syrup from a jar of preserved ginger, and a piece of ice.', 'Add water as needed.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0262', 'Home-made Soda Water', 'American', ["section-beverages-served-with-sandwiches"], 'eggs', 'dessert', 45, 'INGREDIENTS.', [I('granulated sugar', 2.25, 'pounds', 'Pantry'), I('tartaric acid', 1.75, 'ounces', 'Pantry'), I('water', 1, 'pint', 'Pantry'), I('egg whites', 3, '', 'Dairy & Eggs'), I('ounce of ginger extract', 0.5, '', 'Herbs & Spices'), I('bicarbonate of soda for each glass', 0.25, 'teaspoonful', 'Pantry'), I('eggs', 3, '', 'Dairy & Eggs'), I('lemon juice', 1, '', 'Produce'), I('lemon', 1, '', 'Produce')], ['Boil the sugar, water and tartaric acid five minutes.', 'When nearly cold beat into the syrup the whites of the eggs, beaten until foamy, and the flavoring extract.', 'Store in a fruit jar, closely covered.', 'To use, put three tablespoonfuls into a glass half full of cold water, stir in one-fourth a teaspoonful of soda, and drink while effervescing.', 'A pint of any kind of fruit juice may displace the water, when a teaspoonful of lemon juice should be added to the contents of each glass before stirring in the soda.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0263', 'Spanish Chocolate', 'American', ["section-beverages-served-with-sandwiches"], 'eggs', 'toast', 45, '(_To serve 60.', [I('milk', 6, 'quarts', 'Dairy & Eggs'), I('blades of mace', 3, '', 'Herbs & Spices'), I('five-inch stick of cinnamon', 1, '', 'Herbs & Spices'), I('12 cloves', 1, '', 'Herbs & Spices'), I('20 pounded almonds', 1, '', 'Produce'), I('chocolate', 1, 'pound', 'Pantry'), I('sugar', 3, 'cups', 'Pantry'), I('boiling water', 2, 'quarts', 'Pantry'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('nuts', 1, '', 'Produce')], ['Scald the milk with the spices and nuts.', 'Break up the chocolate and melt over hot water; add the sugar, mix thoroughly, then gradually stir in the boiling water; let cook two or three minutes after all the water has been added, then turn into the hot milk; let stand over hot water until ready to serve, then add the beaten yolks of eggs, diluted with half a cup of water, milk or cream, and strain through a cheese-cloth.', 'Keep hot over hot water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0264', 'Claret Cup', 'American', ["section-beverages-served-with-sandwiches"], 'veg', 'dessert', 45, 'INGREDIENTS.', [I('claret', 2, 'quarts', 'Pantry'), I('sugar', 1, 'cup', 'Pantry'), I('water', 1, 'cup', 'Pantry'), I('lemons', 5, '', 'Produce'), I('whole cloves', 1, 'dozen', 'Herbs & Spices'), I('charged Apollinaris or soda water', 2, 'qts', 'Pantry'), I('brandy, sherry or maraschino', 0.25, 'cup', 'Pantry'), I('Ice', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('liqueur', 1, '', 'Pantry'), I('charged apollinaris', 1, '', 'Pantry')], ['Boil the sugar and water about six minutes; let cool, then add the lemon slices, with seeds removed, and the cloves; let stand some hours in a cold place.', 'When ready to serve, add the claret, water and liqueur, all chilled on ice.', 'Put a piece of ice in the pitcher and pour over it the mixture.', 'The beverage should not be sweet.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0265', 'How to Make Sauces', 'American', ["section-chafing-dish-sauces"], 'veg', 'skillet', 45, 'Let hunger move thy appetyte, and not savory sauces.', [I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('flour', 0.25, 'cup', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('pepper', 0.25, 'teaspoonful', 'Produce'), I('liquid', 1, 'pint', 'Pantry'), I('sauce', 1, 'cup', 'Pantry'), I('cold milk', 1, 'cup', 'Dairy & Eggs'), I('cayenne', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('stock', 1, '', 'Pantry'), I('white sauce', 1, '', 'Pantry'), I('brown sauce', 1, '', 'Pantry')], ['Let hunger move thy appetyte, and not savory sauces.--_Babees Book._', '"Change is the sauce that sharpens appetite."', 'As so many dishes are prepared in the chafing-dish that require the use of a simple sauce, we give in this place the methods usually followed in the preparation of common sauces.', 'For one cup of sauce, put two tablespoonfuls of butter into the blazer; let the butter simply melt, without coloring, if for a white sauce, but cook until brown for a brown sauce.', 'Mix together two tablespoonfuls of flour, one-fourth a teaspoonful of salt and a dash of black or white pepper, or a few grains of cayenne or paprica, and beat it into the bubbling butter; let the mixture cook two or three minutes, then stir into it, rather gradually at first, and beating constantly, one cup of cold milk, water or stock.', 'Now, when the sauce boils up once after all the liquid is in, it is ready for use.', 'In making a white sauce some cooks add, from time to time while the sauce is being stirred, a few drops of lemon juice, which they claim makes the sauce much whiter.', 'Sometimes we make the sauce after another fashion, using the same proportions of the various', 'In making a brown sauce, first brown the butter, then brown the flour in the butter, and, whenever it is convenient, use brown stock as the liquid.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0266', 'Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'Put into the blazer twenty-five to fifty choice oysters.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('oysters', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery')], ['Put into the blazer twenty-five to fifty choice oysters.', 'As soon as they are hot and look plump, add salt, pepper and butter.', 'Serve on buttered toast or crackers.', 'Add two tablespoonfuls of cream or half a tablespoonful of lemon juice before serving, if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0267', 'Oysters, No. 2', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('solid oysters', 1, 'pint', 'Meat & Seafood'), I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('scant teaspoonful of salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, 'grains', 'Herbs & Spices'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery')], ['Put the oysters into the blazer.', 'When they look plump and the edges curl, put the blazer into the hot-water pan and add the seasonings.', 'Add a few spoonfuls of the liquor from the pan to the yolks of the eggs, and, after mixing well, pour into the chafing-dish.', 'Stir constantly until the liquor thickens, then serve on thin slices of buttered toast or on thin crackers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0268', 'Oysters a la D\'Uxelles', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('parboiled and drained oysters', 1, 'pint', 'Meat & Seafood'), I('oyster liquor or chicken stock', 1, 'pint', 'Meat & Seafood'), I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('chopped mushrooms', 4, 'tablespoonfuls', 'Produce'), I('flour', 4, 'tablespoonfuls', 'Pantry'), I('onion juice', 1, 'drops', 'Produce'), I('cayenne', 1, 'grains', 'Herbs & Spices'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery'), I('chicken stock', 1, '', 'Meat & Seafood'), I('oyster liquor', 1, '', 'Meat & Seafood')], ['Let the oysters be parboiled and drained beforehand.', '(To parboil, heat quickly to the boiling-point in their own liquor.) Melt the butter in the blazer, add the flour, salt and pepper, and cook till frothy; add the oyster liquor or chicken stock and cook until the boiling-point is reached.', 'Now add the oysters, and, as soon as they are heated thoroughly, put the blazer into the bath and add the beaten yolks, the onion and lemon juice and the mushrooms.', 'As soon as the eggs thicken the sauce a little, serve on toast or crackers.', 'If uncooked mushrooms are used, cook them in the butter two or three minutes before the flour and seasonings are added.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0269', 'Curried Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('oysters', 1, 'pint', 'Meat & Seafood'), I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 1, 'tablespoonful', 'Pantry'), I('oyster liquor', 0.5, 'cup', 'Meat & Seafood'), I('curry powder', 0.5, 'teaspoonful', 'Herbs & Spices'), I('chopped onion', 0.5, 'teaspoonful', 'Produce'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('pepper', 1, 'saltspoonful', 'Produce'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery')], ['Cook the onion and butter in the blazer a few moments.', 'Mix the flour and curry powder and stir into the butter.', 'When frothy add the oyster liquor.', 'As soon as the sauce boils up once, add the salt, pepper and cream, and, in a moment, the oysters.', 'When the oysters are thoroughly heated, serve on buttered toast or crackers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0270', 'Curried Oysters, No. 2', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('oysters', 1, 'quart', 'Meat & Seafood'), I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('small mild onion', 1, '', 'Produce'), I('curry powder', 1, 'tablespoonful', 'Herbs & Spices'), I('flour', 0.25, 'cup', 'Pantry'), I('oyster liquor', 1, 'cup', 'Meat & Seafood'), I('white stock', 1, 'cup', 'Pantry'), I('thick tomato pulp', 0.5, 'cup', 'Produce'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery')], ['Bring the oysters to the boiling-point in their own liquor, skim, drain, and set aside.', 'Heat the butter in the blazer, saute in it the onion cut in slices, stir in the flour and curry powder mixed with the salt and pepper, and, when frothy, add the oyster liquor, stock and tomato pulp (a pint of pulp reduced by slow cooking to half a cup).', 'When the sauce boils, add the oysters; and when hot serve on buttered toast or fried bread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0271', 'Fricassee of Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('oysters', 1, 'quart', 'Meat & Seafood'), I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('chopped parsley', 0.5, 'teaspoonful', 'Produce'), I('flour', 1, 'tablespoonful', 'Pantry'), I('Pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('eggs', 2, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['Brown the butter and add to it the parsley, seasonings and flour; let heat, then add the well-drained oysters, and, when the edges begin to curl, add the well-beaten yolks.', 'Serve on warmed plates, with fried bread and parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0272', 'Creamed Dishes', 'American', ["section-oyster-dishes"], 'seafood', 'dessert', 45, '(_Oysters, shrimps, lobsters, sweetbreads, chicken, veal, fish, mushrooms, asparagus tips, peas, etc.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 4, 'tablespoonfuls', 'Pantry'), I('salt', 2, 'saltspoonfuls', 'Herbs & Spices'), I('cream', 2, 'cups', 'Dairy & Eggs'), I('milk', 2, 'cups', 'Dairy & Eggs'), I('pepper', 1, 'saltspoonful', 'Produce'), I('fish, meat, etc', 1, 'pint', 'Meat & Seafood'), I('mushrooms', 2, 'tablespoonfuls', 'Produce'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('onion juice', 1, 'teaspoonful', 'Produce'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('asparagus tips', 1, '', 'Produce'), I('lobsters', 1, '', 'Meat & Seafood'), I('shrimps', 1, '', 'Meat & Seafood'), I('oysters', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood')], ['Prepare the sauce in the usual manner.', 'If oysters are used, they should have been parboiled previously and drained, and, if large, cut in pieces.', 'Fish should be flaked when hot, and meats cut into dice when cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0273', 'Devilled Dishes', 'American', ["section-oyster-dishes"], 'seafood', 'fish', 45, 'Season any of the creamed dishes highly with cayenne, onion juice, mustard, and Worcestershire or other sauce.', [I('cayenne', 1, '', 'Herbs & Spices'), I('mustard', 1, '', 'Herbs & Spices'), I('onion juice', 1, '', 'Produce'), I('worcestershire', 1, '', 'Pantry'), I('onion', 1, '', 'Produce')], ['Season any of the creamed dishes highly with cayenne, onion juice, mustard, and Worcestershire or other sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0274', 'Scrambled Eggs with Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'Cream together two tablespoonfuls of butter and one tablespoonful of anchovy paste.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('anchovy paste', 1, 'tablespoonful', 'Meat & Seafood'), I('eggs', 0.5, 'dozen', 'Dairy & Eggs'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('oysters', 0.5, 'pint', 'Meat & Seafood'), I('paprica', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('anchovy', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Cream together two tablespoonfuls of butter and one tablespoonful of anchovy paste.', 'Melt in the blazer, then add half a dozen eggs, beaten slightly with one-fourth a teaspoonful of salt and a dash of paprica.', 'Stir and cook, and, when beginning to thicken, add half a pint of oysters, parboiled, "bearded," and cut fine.', 'When scrambled, serve on sippets of toast, lightly spread with anchovy paste.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0275', 'Panned Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'With a fork pressed into a butter ball, rub over the bottom of the hot blazer.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('oysters', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['With a fork pressed into a butter ball, rub over the bottom of the hot blazer.', 'Then cover the surface with small rounds of toast, and put one or two uncooked oysters on each round; cover, and cook until plump, dust with salt and pepper, and put a bit of butter on each oyster.', 'Serve, when the butter has melted, with slices of lemon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0276', 'Panned Oysters with Maitre d\'Hotel Butter', 'American', ["section-oyster-dishes"], 'seafood', 'fish', 45, 'Cook as before.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('oysters', 1, '', 'Meat & Seafood'), I('maitre d\'hotel butter', 1, '', 'Dairy & Eggs')], ['Cook as before.', 'Have ready two tablespoonfuls of butter beaten to a cream; add a few grains of salt and paprica, one tablespoonful of chopped parsley, and, by degrees, the juice of half a lemon.', 'Spread upon the oysters before serving.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0277', 'Oyster Cromeskies', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'Scald the oysters in their own liquor over a quick fire.', [I('oysters', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('bacon', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Scald the oysters in their own liquor over a quick fire.', 'When plump wrap each oyster in a slice of bacon, and fasten with a small skewer (wooden toothpick).', 'Saute in the blazer, heated very hot.', 'Serve on thin rounds of toast.', 'These cromeskies are most easily cooked in a double broiler, resting on a dripping-pan, in a hot oven.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0278', 'Oysters Saute', 'American', ["section-oyster-dishes"], 'seafood', 'fish', 45, 'Wash and drain the oysters, season with salt and pepper, roll in fine crumbs, dip in beaten egg, then roll in crumbs again.', [I('olive', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('olive oil', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('oysters', 1, '', 'Meat & Seafood')], ['Wash and drain the oysters, season with salt and pepper, roll in fine crumbs, dip in beaten egg, then roll in crumbs again.', 'Put a little olive oil or clarified butter in the blazer; when it is heated, put in the oysters, brown them on one side, turn, and brown on the other side.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0279', 'Oyster Canapes', 'American', ["section-oyster-dishes"], 'seafood', 'toast', 45, 'Scald a cup of cream, add two tablespoonfuls of fine-grated bread crumbs, a tablespoonful of butter, a dash of paprica and a grating of nutmeg; then add two dozen oysters, washed, drained and chopped.', [I('fine-grated bread crumbs', 2, 'tablespoonfuls', 'Bakery'), I('oysters', 2, 'dozen', 'Meat & Seafood'), I('paprica', 1, '', 'Pantry'), I('nutmeg', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('olives', 1, '', 'Produce'), I('gherkins', 1, '', 'Pantry'), I('oyster', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery')], ['Scald a cup of cream, add two tablespoonfuls of fine-grated bread crumbs, a tablespoonful of butter, a dash of paprica and a grating of nutmeg; then add two dozen oysters, washed, drained and chopped.', 'Stir until the oysters are thoroughly heated, but without boiling the mixture.', 'Spread rounds of toast with butter, and then with the oyster mixture.', 'Serve at once accompanied by olives, pim-olas or gherkins.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0280', 'Escalloped Oysters', 'American', ["section-oyster-dishes"], 'seafood', 'fish', 45, 'Stir one cup of cracker crumbs into half a cup of melted butter.', [I('melted butter', 0.5, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('oysters', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('cracker crumbs', 1, '', 'Bakery'), I('oyster liquor', 1, '', 'Meat & Seafood')], ['Stir one cup of cracker crumbs into half a cup of melted butter.', 'Heat half a cup of cream or strained oyster liquor in the blazer, put in a layer of oysters (about a cup), washed and drained, and sprinkle with a part of the prepared crumbs, salt and pepper; add another layer of oysters, the rest of the crumbs, and salt and pepper.', 'Cover, and cook nearly ten minutes.', 'Do not stir the oysters.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0281', 'Buttered Lobster', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'dessert', 45, 'Pick the meat from a boiled lobster and cut it into small pieces; sift over it the coral; mix with it also the liver, two tablespoonfuls of vinegar or three of lemon juice, one-third a cup of butter and one-fourth a…', [I('butter', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('cayenne', 1, '', 'Herbs & Spices'), I('mustard', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('lettuce', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('meat', 1, '', 'Meat & Seafood'), I('made mustard', 1, '', 'Herbs & Spices')], ['Pick the meat from a boiled lobster and cut it into small pieces; sift over it the coral; mix with it also the liver, two tablespoonfuls of vinegar or three of lemon juice, one-third a cup of butter and one-fourth a teaspoonful, each, of cayenne and made mustard; heat in the blazer until thoroughly hot.', 'Serve on cup-shaped leaves of lettuce with a quarter of a hard-boiled _egg_ on the top of each portion.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0282', 'Lobster a la Newburgh', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('Meat of 2 medium-sized lobsters', 1, '', 'Meat & Seafood'), I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('pepper', 0.25, 'teaspoonful', 'Produce'), I('sherry wine', 2, 'tablespoonfuls', 'Pantry'), I('brandy', 2, 'tablespoonfuls', 'Pantry'), I('Grating of nutmeg', 1, '', 'Produce'), I('egg yolks', 4, '', 'Dairy & Eggs'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('lobster', 1, '', 'Meat & Seafood')], ['Remove the meat from the shells and cut it into delicate slices.', 'Put the butter in the blazer, and, when it melts, put the lobster into it and cook four or five minutes.', 'Add the salt, pepper, nutmeg, wine and brandy.', 'Stir the cream into the beaten yolks, and then stir both into the lobster mixture.', 'Serve as soon as the eggs thicken the sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0283', 'Plain Lobster', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'Pour three tablespoonfuls of lemon juice over the meat of one lobster and season with salt and pepper.', [I('lobster', 1, '', 'Meat & Seafood'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('meat', 1, '', 'Meat & Seafood')], ['Pour three tablespoonfuls of lemon juice over the meat of one lobster and season with salt and pepper.', 'Put three tablespoonfuls of butter in the blazer, and, when it is melted, add the prepared lobster; stir until hot and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0284', 'Clams a la Newburgh', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'Use one quart of clams.', [I('clams', 1, 'quart', 'Meat & Seafood'), I('lobster', 1, '', 'Meat & Seafood'), I('oyster', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('turkey', 1, '', 'Meat & Seafood'), I('sweetbread', 1, '', 'Meat & Seafood')], ['Use one quart of clams.', 'Separate the hard from the soft parts of the clams.', 'Chop the hard parts fine.', 'Substitute the soft and the chopped parts of the clams for the lobster and proceed as for lobster a la Newburgh.', 'Oyster, chicken, turkey or sweetbread a la Newburgh may be prepared by substituting one of the above'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0285', 'Lobster a la Bordelaise', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('garlic', 2, 'cloves', 'Produce'), I('1 sliced carrot', 1, '', 'Produce'), I('butter', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('glasses of white wine', 2, '', 'Pantry'), I('Meat of 2 lobsters', 1, '', 'Meat & Seafood'), I('glass of brandy', 1, '', 'Pantry'), I('sliced carrot', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('cayenne', 1, '', 'Herbs & Spices'), I('cloves', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('white wine', 1, '', 'Pantry')], ['Melt the butter in the blazer and in it cook the onion and carrot about five minutes.', 'Remove the carrot; add the wine, lobster and seasonings.', 'When thoroughly heated, add the butter, parsley and brandy and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0286', 'Hawaiian Lobster Curry', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'dessert', 45, '(ADA D.', [I('butter', 1.5, 'tablespoonfuls', 'Dairy & Eggs'), I('onion', 0.5, '', 'Produce'), I('small piece of', 1, '', 'Pantry'), I('cornstarch', 1.5, 'tablespoonfuls', 'Produce'), I('curry powder', 1.5, 'tablespoonfuls', 'Herbs & Spices'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('grated cocoanut', 1, '', 'Produce'), I('Salt', 2, 'pounds', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('garlic', 1, 'clove', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('ginger', 1, '', 'Herbs & Spices'), I('lobster', 1, '', 'Meat & Seafood'), I('meat', 1, '', 'Meat & Seafood')], ['Grate the cocoanut and set it aside to soak an hour in one pint of milk.', 'Saute the onion and garlic in the butter, add the cornstarch and seasonings, and cook until frothy; add the milk strained from the cocoanut, gradually, and, when the sauce boils up once, add the lobster; salt and pepper to taste.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0287', 'Lobster a la Bechamel', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('Meat of 2 lobsters', 1, '', 'Meat & Seafood'), I('butter', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 4, 'tablespoonfuls', 'Pantry'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('Grating of nutmeg', 1, '', 'Produce'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('yolks of eggs', 4, '', 'Dairy & Eggs'), I('white stock, seasoned with mace, bay leaf, etc', 1, 'cup', 'Herbs & Spices'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('Dried', 1, '', 'Pantry'), I('sifted coral', 1, '', 'Pantry'), I('white stock', 1, 'cup', 'Pantry'), I('bay leaf', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('lobster', 1, '', 'Meat & Seafood'), I('oysters', 1, '', 'Meat & Seafood'), I('clams', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('turkey', 1, '', 'Meat & Seafood'), I('sweetbread', 1, '', 'Meat & Seafood'), I('bechamel', 1, '', 'Meat & Seafood')], ['Cut the lobster in delicate slices or in dice, as preferred.', 'Make a bechamel sauce, after the usual manner, of the butter, flour, seasonings, cream and stock.', 'Add the lobster, and, when heated thoroughly, add the beaten yolks mixed with a few spoonfuls of the sauce from the blazer.', 'Add the lemon juice, and sprinkle the dried and sifted coral or some chopped parsley over the top of the mixture as it is served.', 'Oysters, clams, sweetbread, chicken or turkey may be served a la Bordelaise or Bechamel.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0288', 'Lobster a la Poulette', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('butter', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('flour', 0.3333333333333333, 'cup', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('Dash of paprica', 1, '', 'Pantry'), I('white pepper', 0.25, 'teaspoonful', 'Produce'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('well-seasoned chicken stock', 1, 'cup', 'Meat & Seafood'), I('Juice of half a lemon', 1, '', 'Produce'), I('hard-boiled eggs', 2, '', 'Dairy & Eggs'), I('diced lobster meat', 1, 'pint', 'Meat & Seafood'), I('egg whites', 1, '', 'Dairy & Eggs'), I('lemon juice', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery'), I('chicken stock', 1, '', 'Meat & Seafood'), I('white sauce', 1, '', 'Pantry')], ['Prepare a white sauce, using the ingredients mentioned, and adding the lemon juice by degrees.', 'Add the lobster to the sauce.', 'Cut the whites of the hard-boiled eggs in rings and pass the yolks through a sieve.', 'Serve the lobster on bits of toast, or on thin crackers, with a sprinkling of the yolks over the lobster, and circles of the whites around it.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0289', 'Oyster Crabs a la Hollandaise', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Remove the meat from one pint of oyster crabs; put this, with a little of the liquor, into the blazer, add two tablespoonfuls of butter, a dash of paprica and a scant half-teaspoonful of salt, and let cook three or four…', [I('oyster crabs', 1, 'pint', 'Meat & Seafood'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('paprica', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('oyster', 1, '', 'Meat & Seafood'), I('crabs', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('hollandaise', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Remove the meat from one pint of oyster crabs; put this, with a little of the liquor, into the blazer, add two tablespoonfuls of butter, a dash of paprica and a scant half-teaspoonful of salt, and let cook three or four minutes without boiling.', 'Set the blazer over hot water and add three-fourths a cup of hollandaise sauce (either hot or cold).', 'Stir until the mixture is heated, then add one tablespoonful of lemon juice and one teaspoonful of chopped parsley.', 'Serve on toast, in Swedish timbale cases or in patty cases.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0290', 'Hollandaise Sauce', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'Put one-fourth a cup of vinegar, two tablespoonfuls of butter, a grating of nutmeg and a dash of paprica over hot water to heat.', [I('vinegar', 0.25, 'cup', 'Pantry'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 4, '', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('nutmeg', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('fish', 1, '', 'Meat & Seafood'), I('lobsters', 1, '', 'Meat & Seafood'), I('shrimps', 1, '', 'Meat & Seafood'), I('oysters', 1, '', 'Meat & Seafood'), I('hollandaise', 1, '', 'Pantry')], ['Put one-fourth a cup of vinegar, two tablespoonfuls of butter, a grating of nutmeg and a dash of paprica over hot water to heat.', 'Beat the yolks of four eggs, add the hot vinegar to them, return to the fire, and stir constantly while the mixture thickens; then add two more tablespoonfuls of butter in bits.', 'Shrimps, oysters, lobsters and delicate fish are all good when served after this recipe.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0291', 'Devilled Crabs', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Melt one tablespoonful of butter, add one tablespoonful of flour, and, when blended, one cup of milk.', [I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('flour', 1, 'tablespoonful', 'Pantry'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('crab meat', 1, 'cup', 'Meat & Seafood'), I('canned mushrooms cut in quarters', 0.25, 'cup', 'Produce'), I('hard-boiled eggs', 2, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('mustard', 1, '', 'Herbs & Spices'), I('lemon juice', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('crab', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('wine', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('crabs', 1, '', 'Meat & Seafood')], ['Melt one tablespoonful of butter, add one tablespoonful of flour, and, when blended, one cup of milk.', 'Add the yolks of two hard-boiled eggs rubbed through a sieve, and season to taste with salt, paprica, a teaspoonful of lemon juice and wine; cayenne, mustard and tobasco sauce are approved by some.', 'Add one cup of crab meat and one-fourth a cup of canned mushrooms cut in quarters.', 'Serve on toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0292', 'Oyster Crabs', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('oyster crabs', 1, 'pint', 'Meat & Seafood'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('onion', 0.5, '', 'Produce'), I('flour', 1, 'tablespoonful', 'Pantry'), I('white stock', 1, 'cup', 'Pantry'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('yolk of egg', 1, '', 'Dairy & Eggs'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('crab', 1, '', 'Meat & Seafood'), I('meat', 1, '', 'Meat & Seafood')], ['Melt the butter in the blazer, add the onion, and let cook until a light-brown color; add the flour and mix until smooth; add the stock and stir until it thickens.', 'Add the crab meat, lemon juice, parsley, salt and pepper.', 'Beat the yolk of the egg and add two or three spoonfuls of the sauce to it; mix well, add to the ingredients in the blazer, stir constantly, and serve as soon as heated.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0293', 'Crabs a la Creole', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'INGREDIENTS.', [I('green pepper', 1, '', 'Produce'), I('garlic', 1, 'clove', 'Produce'), I('small onion', 1, '', 'Produce'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('tomatoes', 1, 'cup', 'Produce'), I('crab meat', 1, 'cup', 'Meat & Seafood'), I('Pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('toast', 1, '', 'Bakery'), I('crabs', 1, '', 'Meat & Seafood')], ['Put the butter in the blazer; when melted, add the garlic, onion, salt, pepper and tomatoes, and let cook ten minutes; add the crab meat (fresh or canned).', 'Serve when hot on sippets of toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0294', 'Shrimps a la Poulette', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Make a sauce of one-fourth a cup, each, of butter and flour, half a teaspoonful of salt, a dash of pepper and one cup and a half of white stock; add one tablespoonful of anchovy essence and a quart of shelled shrimps.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('white stock', 1.5, 'cups', 'Pantry'), I('anchovy essence', 1, 'tablespoonful', 'Meat & Seafood'), I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('shrimps', 1, '', 'Meat & Seafood'), I('anchovy', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry')], ['Make a sauce of one-fourth a cup, each, of butter and flour, half a teaspoonful of salt, a dash of pepper and one cup and a half of white stock; add one tablespoonful of anchovy essence and a quart of shelled shrimps.', 'When hot add the beaten yolks of two eggs, with half a cup of cream.', 'Lastly, add a tablespoonful of lemon juice and serve, _without_ boiling, on sippets of toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0295', 'Shrimps with Peas', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'A pint of shrimps and a cup of peas, heated in a cup and a half of cream sauce, are particularly good.', [I('cream', 1, '', 'Dairy & Eggs'), I('peas', 1, '', 'Produce'), I('shrimps', 1, '', 'Meat & Seafood')], ['A pint of shrimps and a cup of peas, heated in a cup and a half of cream sauce, are particularly good.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0296', 'Anchovy Toast', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Put about two tablespoonfuls of clarified butter into the blazer.', [I('anchovy paste', 1, '', 'Meat & Seafood'), I('butter', 1, '', 'Dairy & Eggs'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery')], ['Put about two tablespoonfuls of clarified butter into the blazer.', 'When hot add bread cut as for sandwiches.', 'Brown the bread on one side, turn, and brown the other side.', 'Spread with anchovy paste and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0297', 'Anchovy Toast with Eggs', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Prepare the anchovy toast in one chafing-dish, and, at the same time, the eggs in another.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('cream or milk', 0.5, 'cup', 'Dairy & Eggs'), I('eggs', 5, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('anchovy', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Prepare the anchovy toast in one chafing-dish, and, at the same time, the eggs in another.', 'Beat five eggs slightly, add half a teaspoonful of salt, a dash of pepper and half a cup of cream or milk.', 'Put a large tablespoonful of butter in the blazer; when melted, add the egg mixture.', 'Stir until the egg is creamy, and serve on the anchovy toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0298', 'Anchovy Toast with Spinach', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Press cooked spinach, chopped fine, through a puree sieve; reheat with a little butter, salt and two or three drops of tobasco sauce.', [I('tobasco sauce', 3, 'drops', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('anchovy paste', 1, '', 'Meat & Seafood'), I('egg', 1, '', 'Dairy & Eggs'), I('spinach', 1, '', 'Produce'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery')], ['Press cooked spinach, chopped fine, through a puree sieve; reheat with a little butter, salt and two or three drops of tobasco sauce.', 'Saute rounds of bread to a golden brown in a little hot butter, spread with anchovy paste, and over this spread the puree of spinach.', 'Press into the spinach on each round of bread a quarter of a hard-boiled egg cut lengthwise, having the yolk uppermost.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0299', 'Anchovies with Olives', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'All the preparations for this dish, with the exception of sauteing the bread, may be made some hours before serving.', [I('anchovies', 5, '', 'Pantry'), I('chives', 1, '', 'Pantry'), I('paprica', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('mayonnaise', 1, '', 'Pantry'), I('parsley', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('olive', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery')], ['All the preparations for this dish, with the exception of sauteing the bread, may be made some hours before serving.', 'Thoroughly wash the anchovies, cut off the fillets, and chop very fine with a sprig of parsley and a few chives, or a slice or two of Bermuda onion; put the whole into a mortar and pound well, adding, meanwhile, a little paprica.', 'Cut some large selected olives in halves, take out the stones, and fill them with the anchovy mixture.', 'Cut small rounds of bread an inch and a half in diameter and an inch in thickness; remove a crumb, similar in shape to the olive, from the centre of each.', 'Put a little butter into the blazer, and, when hot, saute the rounds of bread on both sides; drain on soft paper, put an olive in the centre of each and a little mayonnaise over the whole.', 'Five anchovies will suffice to stuff a dozen olives.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0300', 'Sardine Canapes', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'toast', 45, 'Have ready yolks of eggs, cooked until firm, and an equal bulk of sardines, each rubbed to a paste.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('sardine', 1, '', 'Meat & Seafood'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery')], ['Have ready yolks of eggs, cooked until firm, and an equal bulk of sardines, each rubbed to a paste.', 'Mix thoroughly, and season with salt, pepper and lemon juice.', 'Prepare some bread in the blazer as for anchovy toast; then spread with the sardine mixture and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0301', 'Curried Sardines', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'dessert', 45, 'Mix together one teaspoonful, each, of sugar and curry powder and a saltspoonful of salt.', [I('cream', 1, 'cup', 'Dairy & Eggs'), I('lemon juice', 0.5, 'teaspoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('sugar', 1, '', 'Pantry'), I('oil', 1, '', 'Pantry'), I('curry powder', 1, '', 'Herbs & Spices'), I('curry', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('apple', 1, '', 'Produce'), I('apples', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('sardine', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery')], ['Mix together one teaspoonful, each, of sugar and curry powder and a saltspoonful of salt.', 'Put these into the blazer with one cup of cream and half a teaspoonful of lemon juice.', 'Stir until the mixture is hot, then put into it ten or twelve sardines.', 'In the mean time, heat some butter or oil in a second blazer, and in it saute some bits of bread a little larger than the sardines, and round slices of tart apple.', 'Serve each sardine on a bit of bread; pour a little of the sauce over the top and garnish with a round of apple.', 'The slices of apple will keep their shape, if the apples be cored and then cut into rounds without paring.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0302', 'Sardines', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, '(_French fashion.', [I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('egg yolks', 4, '', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('mustard', 1, '', 'Herbs & Spices'), I('oil', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon vinegar', 1, '', 'Pantry'), I('cider vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('yolks', 1, '', 'Dairy & Eggs'), I('olives', 1, '', 'Produce'), I('sardines', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('made mustard', 1, '', 'Herbs & Spices')], ['Remove the skins and tails from about a dozen sardines and heat them in the oven.', 'Heat some butter or oil in the blazer of one chafing-dish, and in it saute some bits of bread of suitable shape to serve under the sardines.', 'Put in the blazer of another chafing-dish, over hot water, the well-beaten yolks of four eggs, one teaspoonful, each, of tarragon vinegar, cider vinegar and made mustard, one-fourth a teaspoonful of salt and one tablespoonful of butter.', 'Stir the sauce until it is quite thick, then serve the sardines on the bread with the sauce poured over them.', 'Olives are agreeable with this dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0303', 'Moulded Halibut with Creamed Peas', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'Two chafing-dishes will be requisite for preparing this delicious luncheon dish.', [I('raw halibut', 1, 'pound', 'Meat & Seafood'), I('white pepper', 0.25, 'teaspoonful', 'Produce'), I('thick cream', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('salt', 1.25, 'teaspoonfuls', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('cayenne', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('peas', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood')], ['Two chafing-dishes will be requisite for preparing this delicious luncheon dish.', 'Have ready one pound of raw halibut chopped very fine; beat the yolk of an egg, add to it one teaspoonful and a fourth of salt, one-fourth a teaspoonful of white pepper and a few grains of cayenne or paprica.', 'Blend a teaspoonful of cornstarch with a little milk; then add milk to make two-thirds a cup, stir gradually into the egg and seasonings, and then very slowly into the fish.', 'Lastly, fold into the mixture one-third a cup of thick cream, beaten until stiff.', 'Butter dariole moulds thoroughly, arrange a circle of cooked peas around the bottom of each mould, and fill with the fish preparation two-thirds full.', 'Set into the blazer, surrounded with boiling water; after the water is again boiling, turn down the flame so that the water will barely quiver, and let cook about twenty minutes.', 'Prepare, in the mean time, in the second blazer, creamed peas.', 'Turn the fish from the moulds and surround with the'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0304', 'Creamed Peas', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'Have ready one can of peas, drained, rinsed, covered with boiling water and drained again.', [I('peas', 1, 'can', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('sugar', 1, 'teaspoonful', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('milk', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry')], ['Have ready one can of peas, drained, rinsed, covered with boiling water and drained again.', 'Melt two tablespoonfuls of butter; add one tablespoonful of flour with one teaspoonful of sugar and half a teaspoonful of salt; add the peas and one-third a cup of milk, stir, and let cook until the liquid begins to bubble.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0305', 'Puree of Fish', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'soup', 45, 'Scald one quart of milk, with half an onion and a stalk of celery; strain into a pitcher and keep hot if convenient.', [I('milk', 1, 'quart', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('soup', 3, 'pints', 'Pantry'), I('pepper', 1, '', 'Produce'), I('celery', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('salmon', 1, '', 'Meat & Seafood'), I('crackers', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry'), I('vegetable', 1, '', 'Pantry')], ['Scald one quart of milk, with half an onion and a stalk of celery; strain into a pitcher and keep hot if convenient.', 'Add to the remnants of cold boiled white fish enough canned salmon to make two cups; chop fine and rub through a puree sieve.', 'Cook together in the blazer two tablespoonfuls of butter, three of flour, one teaspoonful of salt and a dash of pepper.', 'Add the milk gradually, and, when all is added and the contents of the blazer are boiling, put a few spoonfuls of the sauce into the fish and beat until smooth; add more sauce, and, when well diluted and smooth, turn the whole into the blazer.', 'Stir, and let cook until very hot; then serve with crackers, split, buttered, and browned in the oven.', 'These proportions give three pints of soup.', 'Vegetable purees may be prepared in the same way.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0306', 'Salt Codfish with Tomato Sauce', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'dessert', 45, 'Saute one clove of garlic and half an onion, grated or chopped fine, in three tablespoonfuls of butter; add two tablespoonfuls of flour, one-fourth a teaspoonful of paprica and one pimento, chopped fine; also, add one…', [I('garlic', 1, 'clove', 'Produce'), I('butter', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('tomato pulp', 1, 'cup', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('clove of garlic', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('pimento', 1, '', 'Pantry'), I('codfish', 1, '', 'Meat & Seafood'), I('salt codfish', 1, '', 'Meat & Seafood'), I('brownbread', 1, '', 'Bakery'), I('tomato sauce', 1, '', 'Produce')], ['Saute one clove of garlic and half an onion, grated or chopped fine, in three tablespoonfuls of butter; add two tablespoonfuls of flour, one-fourth a teaspoonful of paprica and one pimento, chopped fine; also, add one cup of tomato pulp, and, when the sauce boils, half a pound of "hatcheled" codfish, or any salt codfish picked into small pieces and freshened in one quart of cold water.', 'Serve, while hot, with brownbread sandwiches, and pickles or pim-olas.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0307', 'Salt Codfish in Cream Sauce', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'green', 45, 'Pick enough salt codfish into bits to make one cup.', [I('cream sauce', 1, 'cup', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('lettuce', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('codfish', 1, '', 'Meat & Seafood'), I('salt codfish', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('flour', 1.5, 'tablespoonfuls', 'Pantry')], ['Pick enough salt codfish into bits to make one cup.', 'Let stand in cold water about half an hour.', 'Make one cup of cream sauce, using one tablespoonful and a half of flour, two tablespoonfuls of butter and one cup of cream; remove all the water from the fish by wringing in a cheese-cloth, add the fish to the sauce, and, when heated, stir in a lightly beaten egg.', 'Serve upon rounds of toast, with olives, or plain lettuce, or tomato salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0308', 'Rechauffe of Fish', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'pasta', 45, 'INGREDIENTS.', [I('cooked fish, flaked', 1, 'cup', 'Meat & Seafood'), I('macaroni, cooked, and still hot', 1, 'cup', 'Pantry'), I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('tomato puree', 1, 'cup', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('Dash of pepper', 1, '', 'Produce'), I('tobasco sauce', 8, 'drops', 'Pantry'), I('cooked fish', 1, 'cup', 'Meat & Seafood')], ['Melt the butter in the blazer and toss about in it the macaroni and fish; add the seasonings and the tomato puree, which should be well reduced.', 'Serve when thoroughly heated.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0309', 'Rechauffe of Fish, No. 2', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'fish', 45, 'INGREDIENTS.', [I('cooked fish, flaked and seasoned', 1, 'pint', 'Meat & Seafood'), I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('flour', 0.25, 'cup', 'Pantry'), I('fish stock', 1, 'cup', 'Meat & Seafood'), I('cream and milk combined', 1, 'cup', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('anchovy paste', 1, 'teaspoonful', 'Meat & Seafood'), I('paprica', 0.5, 'teaspoonful', 'Pantry'), I('oil', 2, 'tablespoonfuls', 'Pantry'), I('lemon juice', 2, 'tablespoonfuls', 'Produce'), I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('cooked fish', 1, 'pint', 'Meat & Seafood'), I('pepper', 1, '', 'Produce'), I('onion juice', 1, '', 'Produce'), I('onion', 1, '', 'Produce')], ['Marinate the fish while hot with salt, pepper, oil and lemon juice, adding, also, a few drops of onion juice, if desired.', 'At serving-time make a sauce of the butter, flour, salt, paprica, stock and cream; add the paste and the fish, and, when the fish is thoroughly heated, turn down the flame of the lamp or set the blazer into hot water.', 'Sprinkle with the parsley and serve.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0310', 'Sardines on Toast', 'American', ["section-lobster-and-other-sea-fish"], 'seafood', 'dessert', 45, 'Melt two tablespoonfuls of butter in the blazer; add two tablespoonfuls of flour and a dash of paprica, and stir until smooth and browned a little; then add half a cup of stock and half a cup of sherry; stir until…', [I('flour', 2, 'tablespoonfuls', 'Pantry'), I('stock', 0.5, 'cup', 'Pantry'), I('sherry', 0.5, 'cup', 'Pantry'), I('paprica', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('sardines', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Melt two tablespoonfuls of butter in the blazer; add two tablespoonfuls of flour and a dash of paprica, and stir until smooth and browned a little; then add half a cup of stock and half a cup of sherry; stir until thickened, then let simmer a few minutes, and add nearly a cup of sardines, from which the bones and skin have been removed and the flesh separated into small pieces.', 'Let stand until very hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0311', 'Welsh Rarebit', 'American', ["section-cheese-confections"], 'eggs', 'toast', 45, 'INGREDIENTS.', [I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('cheese', 0.5, 'pound', 'Dairy & Eggs'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('paprica', 1, 'dash', 'Pantry'), I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery'), I('biscuit', 1, '', 'Bakery')], ['Melt the butter, add the cheese and seasonings, and stir until melted; then add the eggs, diluted with the cream, and stir until smooth and slightly thickened.', '_Do not allow the mixture to boil_ at any time in the cooking; if necessary, cook over hot water.', 'Serve on thin crackers, hot shredded-wheat or granose biscuit, or on bread toasted on but one side, placing the rarebit on the untoasted side.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0312', 'Welsh Rarebit, No. 2', 'American', ["section-cheese-confections"], 'veg', 'bowl', 45, 'INGREDIENTS.', [I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('cornstarch', 0.5, 'teaspoonful', 'Produce'), I('thin cream', 0.5, 'cup', 'Dairy & Eggs'), I('mild cheese', 0.5, 'pound', 'Dairy & Eggs'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('mustard', 0.5, 'saltspoonful', 'Herbs & Spices'), I('cayenne', 1, 'grains', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry')], ['Melt the butter; add to it the cream in which the cornstarch has been stirred.', 'Let cook two minutes, and add the cheese broken into bits.', 'Stir until the cheese is melted and the mixture perfectly smooth.', 'Add the salt, mustard and paprica, and serve at once as above.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0313', 'Welsh Rarebit with Ale', 'American', ["section-cheese-confections"], 'eggs', 'skillet', 45, 'INGREDIENTS.', [I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('salt', 0.3333333333333333, 'teaspoonful', 'Herbs & Spices'), I('mustard', 1, 'teaspoonful', 'Herbs & Spices'), I('cayenne', 1, 'grains', 'Herbs & Spices'), I('ale', 0.5, 'cup', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('soft American cheese', 0.5, 'pound', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs')], ['Put the butter into the chafing-dish (using the bath); when melted, add the cheese and ale.', 'Mix the salt, mustard and cayenne, add the egg, and beat thoroughly.', 'When the cheese is melted, add the egg mixture and let cook until it thickens.', 'Serve as before.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0314', 'Halibut Rarebit', 'American', ["section-cheese-confections"], 'fish', 'toast', 45, 'Marinate a cup of cooked halibut, flaked, with one tablespoonful of olive oil, a few drops of onion juice, one tablespoonful of lemon juice, one-fourth a teaspoonful of salt and a dash of paprica.', [I('olive oil', 1, 'tablespoonful', 'Produce'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('grated cheese', 0.6666666666666666, 'cup', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('onion juice', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('olive', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('halibut', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood')], ['Marinate a cup of cooked halibut, flaked, with one tablespoonful of olive oil, a few drops of onion juice, one tablespoonful of lemon juice, one-fourth a teaspoonful of salt and a dash of paprica.', 'Make a sauce of two tablespoonfuls, each, of butter and flour, one-fourth a teaspoonful of salt and half a cup, each, of chicken stock and cream.', 'Add two-thirds a cup of grated cheese and the halibut.', 'Serve, as soon as the fish is hot and the cheese melted, on the untoasted side of bread toasted on one side.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0315', 'Oyster Rarebit', 'American', ["section-cheese-confections"], 'seafood', 'toast', 45, 'Clean and remove the hard muscles from half a pint of oysters; parboil the oysters in the chafing-dish in their own liquor until their edges curl, then remove to a hot bowl.', [I('oysters', 0.5, 'pint', 'Meat & Seafood'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('cheese broken in small bits', 0.5, 'pound', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('mustard', 1, '', 'Herbs & Spices'), I('cheese', 1, '', 'Dairy & Eggs'), I('oyster', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('oyster liquor', 1, '', 'Meat & Seafood')], ['Clean and remove the hard muscles from half a pint of oysters; parboil the oysters in the chafing-dish in their own liquor until their edges curl, then remove to a hot bowl.', 'Put one tablespoonful of butter, half a pound of cheese broken in small bits, one-fourth a teaspoonful, each, of salt and mustard and a few grains of cayenne into the chafing-dish.', 'While the cheese is melting, beat two eggs slightly, and add to them the oyster liquor; mix this gradually with the melted cheese, add the oysters, and turn at once over hot toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0316', 'Sardine Rarebit', 'American', ["section-cheese-confections"], 'fish', 'toast', 45, 'Melt two tablespoonfuls of butter, add half a pound of fresh cheese, grated or broken into bits, and stir constantly while it melts; then add gradually the beaten yolk of an egg, diluted with two-thirds a cup of cream.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('fresh cheese', 0.5, 'pound', 'Dairy & Eggs'), I('cream', 0.6666666666666666, 'cup', 'Dairy & Eggs'), I('paprica', 0.5, 'teaspoonful', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('tabasco', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('sardines', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('sardine', 1, '', 'Meat & Seafood')], ['Melt two tablespoonfuls of butter, add half a pound of fresh cheese, grated or broken into bits, and stir constantly while it melts; then add gradually the beaten yolk of an egg, diluted with two-thirds a cup of cream.', 'Stir until smooth and slightly thickened; season with a scant half a teaspoonful of paprica, one-fourth a teaspoonful of salt and a few drops of tabasco sauce.', 'Have ready a box of sardines, drained, broiled carefully and laid on the untoasted side of bread toasted on one side; pour the rarebit over the sardines and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0317', 'Golden Buck', 'American', ["section-cheese-confections"], 'eggs', 'toast', 45, 'Prepare a rarebit in one chafing-dish; break some eggs into the blazer of another containing salted water just "off the boil.', [I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('toast', 1, '', 'Bakery')], ['Prepare a rarebit in one chafing-dish; break some eggs into the blazer of another containing salted water just "off the boil." When the eggs are poached and the rarebit ready, place an egg above the rarebit on each slice of toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0318', 'Yorkshire Rarebit', 'American', ["section-cheese-confections"], 'pork', 'skillet', 45, 'Add two slices of broiled or fried bacon to each service of golden buck.', [I('bacon', 1, '', 'Meat & Seafood'), I('golden buck', 1, '', 'Pantry')], ['Add two slices of broiled or fried bacon to each service of golden buck.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0319', 'Mock-Crab Toast', 'American', ["section-cheese-confections"], 'seafood', 'toast', 45, 'Melt a tablespoonful of butter in the blazer, turning it about so as to butter the surface thoroughly.', [I('mild cheese', 0.5, 'pound', 'Dairy & Eggs'), I('lemon juice or vinegar', 2, 'tablespoonfuls', 'Produce'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('egg yolks', 3, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('mustard', 1, '', 'Herbs & Spices'), I('vinegar', 1, '', 'Pantry'), I('lemon juice', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('made mustard', 1, '', 'Herbs & Spices'), I('anchovy sauce', 1, '', 'Meat & Seafood'), I('crab', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Melt a tablespoonful of butter in the blazer, turning it about so as to butter the surface thoroughly.', 'Put in half a pound of mild cheese, grated, and stir until the cheese is melted; then add the yolks of three eggs, beaten and diluted with a tablespoonful of anchovy sauce, a teaspoonful of made mustard, two tablespoonfuls of lemon juice or vinegar and one-fourth a teaspoonful of paprica.', 'Stir until smooth.', 'Serve upon the untoasted side of sippets of bread toasted on one side.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0320', 'Cheese Fondue', 'American', ["section-cheese-confections"], 'eggs', 'bowl', 45, 'INGREDIENTS.', [I('cheese broken into bits', 0.25, 'pound', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 1, 'tablespoonful', 'Pantry'), I('soda', 1, 'saltspoonful', 'Pantry'), I('mustard', 1, 'saltspoonful', 'Herbs & Spices'), I('milk', 0.75, 'cup', 'Dairy & Eggs'), I('cayenne or paprica', 1, 'grains', 'Herbs & Spices'), I('stale bread crumbs', 0.5, 'cup', 'Bakery'), I('eggs', 3, '', 'Dairy & Eggs'), I('bread crumbs', 1, '', 'Bakery')], ['Sift the soda, mustard and cayenne into the flour and cook in the butter until frothy, then add the milk gradually; when the sauce boils, after all the milk has been added, put the blazer into the bath, add the crumbs and cheese, and cook and stir until the cheese is melted and the mixture becomes smooth; add the eggs, beaten until light, and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0321', 'English Monkey', 'American', ["section-cheese-confections"], 'eggs', 'roast', 45, 'INGREDIENTS.', [I('milk', 1, 'cup', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('to 1 whole cup of cheese', 0.75, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('bread crumbs', 1, 'cup', 'Bakery')], ['Melt the butter, add the cheese, and stir while melting; then add the bread crumbs, which have been soaked in the milk and the egg lightly beaten.', 'EGGS.', 'New-laid eggs, with Baucis\' busy care Turned by a gentle fire, and roasted rare. --_Dryden._'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0322', 'Scrambled Eggs with Cheese', 'American', ["section-eggs"], 'eggs', 'bowl', 45, 'Beat six eggs until whites and yolks are well mixed; add half a teaspoonful of salt, a dash of paprica and six tablespoonfuls of milk or cream.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('milk or cream', 6, 'tablespoonfuls', 'Dairy & Eggs'), I('grated Parmesan cheese', 0.5, 'cup', 'Dairy & Eggs'), I('eggs', 6, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry')], ['Beat six eggs until whites and yolks are well mixed; add half a teaspoonful of salt, a dash of paprica and six tablespoonfuls of milk or cream.', 'Melt two tablespoonsful of butter in the blazer, pour in the egg mixture, and stir and scrape from the blazer as it thickens.', 'Just before it comes to the proper consistency, sprinkle in half a cup of grated Parmesan cheese, still stirring as before, and turn down the flame or set the blazer into the bath.', 'American dairy cheese may be used instead of the Parmesan.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0323', 'Scrambled Eggs with Smoked Salmon', 'American', ["section-eggs"], 'fish', 'fish', 45, 'Cook half a cup of smoked salmon, cut into thin strips, in a tablespoonful of butter three or four minutes; then add to the eggs just before the cooking is finished.', [I('smoked salmon', 0.5, 'cup', 'Meat & Seafood'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('salmon', 1, '', 'Meat & Seafood')], ['Cook half a cup of smoked salmon, cut into thin strips, in a tablespoonful of butter three or four minutes; then add to the eggs just before the cooking is finished.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0324', 'Scrambled Eggs a la Union Club', 'American', ["section-eggs"], 'eggs', 'toast', 45, 'Heat one can of pimentos (sweet red peppers) in boiling salted water; drain, and serve on rounds of buttered toast the pimentos filled with eggs scrambled with mushrooms or truffles.', [I('madeira has been added', 0.3333333333333333, 'cup', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('truffles', 1, '', 'Pantry'), I('pimentos', 1, '', 'Pantry'), I('toast', 1, '', 'Bakery'), I('brown sauce', 1, '', 'Pantry')], ['Heat one can of pimentos (sweet red peppers) in boiling salted water; drain, and serve on rounds of buttered toast the pimentos filled with eggs scrambled with mushrooms or truffles.', 'Pour around the pimentos a pint of well-seasoned brown sauce, to which one-third a cup of madeira has been added.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0325', 'Scrambled Eggs with Dried Beef', 'American', ["section-eggs"], 'beef', 'bowl', 45, 'Cut half a pound of dried beef, sliced thin, into short match-like strips, cover with boiling water, drain at once, and add six eggs, beaten slightly, and one-fourth a cup of milk.', [I('dried beef', 0.5, 'pound', 'Meat & Seafood'), I('milk', 0.25, 'cup', 'Dairy & Eggs'), I('eggs', 6, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('beef', 1, '', 'Meat & Seafood')], ['Cut half a pound of dried beef, sliced thin, into short match-like strips, cover with boiling water, drain at once, and add six eggs, beaten slightly, and one-fourth a cup of milk.', 'Put two tablespoonfuls of butter into the blazer; when hot add the eggs and other ingredients, and stir and cook until the eggs are set.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0326', 'Scrambled Eggs with Tomatoes', 'American', ["section-eggs"], 'eggs', 'toast', 45, 'Have ready a pint of tomato pulp, from which the seeds have been removed, seasoned with onion, celery or parsley, and sweet herbs.', [I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('pepper', 0.5, 'saltspoonful', 'Produce'), I('eggs', 6, '', 'Dairy & Eggs'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('celery', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('toast', 1, '', 'Bakery'), I('brownbread', 1, '', 'Bakery'), I('tomatoes', 1, '', 'Produce')], ['Have ready a pint of tomato pulp, from which the seeds have been removed, seasoned with onion, celery or parsley, and sweet herbs.', 'Put a generous tablespoonful of butter into the blazer; add the tomato, and, when hot, six eggs, slightly beaten, half a teaspoonful of salt and half a saltspoonful of pepper.', 'Stir until the contents are of a creamy consistency.', 'Serve with brownbread toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0327', 'Eggs and Mushrooms a la Dauphine', 'American', ["section-eggs"], 'eggs', 'toast', 45, 'INGREDIENTS.', [I('thick tomato sauce, highly seasoned', 1, 'pint', 'Produce'), I('mushrooms', 1, 'pint', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('pepper', 0.5, 'saltspoonful', 'Produce'), I('eggs', 6, '', 'Dairy & Eggs'), I('thick tomato sauce', 1, 'pint', 'Produce'), I('egg whites', 1, '', 'Dairy & Eggs'), I('tomato sauce', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('toast', 1, '', 'Bakery')], ['Cook the mushrooms in the tomato sauce until tender; add the seasoning and the eggs, which have been broken into a bowl.', 'Lift the whites carefully with a silver or wooden fork while cooking, until they are set; then prick the yolks and let them mix with the tomato, whites of the eggs and mushrooms.', 'Serve quite soft on toast.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0328', 'Scotch Woodcock', 'American', ["section-eggs"], 'seafood', 'fish', 45, 'Make a cup of white sauce; add one tablespoonful of essence of anchovies and five hard-boiled eggs cut into quarters lengthwise.', [I('essence of anchovies', 1, 'tablespoonful', 'Pantry'), I('hard-boiled eggs', 5, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('anchovies', 1, '', 'Pantry'), I('white sauce', 1, '', 'Pantry')], ['Make a cup of white sauce; add one tablespoonful of essence of anchovies and five hard-boiled eggs cut into quarters lengthwise.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0329', 'Eggs a la Italienne', 'American', ["section-eggs"], 'eggs', 'pasta', 45, 'INGREDIENTS.', [I('eggs', 5, '', 'Dairy & Eggs'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('boiled spaghetti', 0.5, 'cup', 'Pantry'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('fresh mushrooms', 0.5, 'cup', 'Produce'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('scant teaspoonful of salt', 1, '', 'Herbs & Spices'), I('White pepper', 1, '', 'Produce'), I('fresh mushrooms', 0.5, 'cup', 'Produce')], ['Melt the butter in the blazer and saute in it the sliced mushrooms; add the milk and spaghetti, and, when heated thoroughly, put the blazer in the bath and add the beaten eggs.', 'Stir and cook until the eggs have thickened; then add the parsley and seasoning, and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0330', 'Eggs a la Parisienne', 'American', ["section-eggs"], 'pork', 'bowl', 45, 'Butter thickly the inner sides of as many dariole moulds as there are individuals to serve.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('tomatoes', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood')], ['Butter thickly the inner sides of as many dariole moulds as there are individuals to serve.', 'Then sprinkle them thickly with fine-chopped parsley, ham or tongue.', 'Break an egg into each mould, taking care not to break the yolk; sprinkle over the tops a little salt and pepper, and set in the blazer surrounded by hot water to two-thirds the height of the moulds.', 'If, after a time, the water boils, even with the lamp turned low, put the blazer into the bath and continue cooking, until the eggs are set.', 'The eggs should be covered while cooking.', 'When cooked, turn from the moulds and serve with a puree of tomatoes.', 'Half a cup of sliced mushrooms added to the puree improves this dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0331', 'Curried Eggs', 'American', ["section-eggs"], 'chicken', 'toast', 45, '(See cut facing page 186.', [I('eggs, cooked, in water just below the', 6, '', 'Dairy & Eggs'), I('stock', 0.5, 'cup', 'Pantry'), I('milk', 0.5, 'cup', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('cornstarch', 1, 'teaspoonful', 'Produce'), I('curry-powder', 0.5, 'teaspoonful', 'Herbs & Spices'), I('onion', 1, 'slice', 'Produce'), I('Teaspoonful of lemon juice', 1, '', 'Produce'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('lemon juice', 1, '', 'Produce'), I('fish', 1, '', 'Meat & Seafood'), I('lobsters', 1, '', 'Meat & Seafood'), I('oysters', 1, '', 'Meat & Seafood'), I('chicken', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Cook the onion in the butter a few minutes, then remove it and add the flour and curry powder; when frothy add the milk and stock.', 'As soon as the boiling-point is reached, set the blazer into the hot-water pan and add the eggs cut in quarters.', 'Season with salt and serve on sippets of toast.', 'Light meats, fish, oysters and lobsters may be prepared in the same way, omitting the half-cup of milk in the case of oysters.', 'Chickens\' livers may also be prepared by the same recipe, in which case the livers should have been cooked previously.', 'Or they may be sauted in a little hot butter in one dish, while the sauce is made in another.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0332', 'Shirred Eggs', 'American', ["section-eggs"], 'chicken', 'bowl', 45, 'Butter four or five shirring-dishes.', [I('grated bread crumbs', 0.5, 'cup', 'Bakery'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery')], ['Butter four or five shirring-dishes.', 'To half a cup of grated bread crumbs and half a cup of chopped chicken or ham add enough cream to mix to a smooth, moist consistency, like butter.', 'Season to taste with salt and pepper.', 'Put a tablespoonful of the mixture into each dish, break in an egg, season with a dash of salt and pepper, cover with more of the mixture, and cook in the same manner as eggs a la Parisienne.', 'Serve in the cups.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0333', 'Eggs', 'American', ["section-eggs"], 'eggs', 'toast', 45, '(_Creole style.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('tomatoes', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('toast', 1, '', 'Bakery')], ['Have prepared on a hot serving-dish a can of tomatoes, stewed until they are reduced to a scant pint, and upon the tomatoes rounds of buttered toast for each egg to be served.', 'Break some eggs, one by one, into a cup, and turn them into the blazer two-thirds filled with hot water; turn the flame low and put on the chafing-dish cover; if the water boils, turn down the flame.', 'When the eggs are nicely poached, remove with a skimmer to the toast.', 'Pour out the water and melt in the blazer, browning if desired, two tablespoonfuls of butter; add one tablespoonful of lemon juice; heat to the boiling-point, dust the eggs with salt and pepper, pour over the sauce, and serve.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0334', 'Egg Canapes', 'American', ["section-eggs"], 'seafood', 'toast', 45, 'Have ready, cooked beforehand, four hard-boiled eggs; cut them carefully into halves lengthwise, remove the yolks, and press them through a small sieve.', [I('capers', 0.5, 'teaspoonful', 'Pantry'), I('tarragon vinegar', 1, 'teaspoonful', 'Pantry'), I('hard-boiled eggs', 4, '', 'Dairy & Eggs'), I('anchovies', 2, '', 'Pantry'), I('cooked mushrooms', 3, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('paprica', 1, '', 'Pantry'), I('vinegar', 1, '', 'Pantry'), I('tarragon', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('anchovy', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery')], ['Have ready, cooked beforehand, four hard-boiled eggs; cut them carefully into halves lengthwise, remove the yolks, and press them through a small sieve.', 'Soak two anchovies, then dry and remove the bones and chop them with two or three cold cooked mushrooms and half a teaspoonful of capers; mix in the sifted yolks, add a seasoning of salt, pepper and paprica, and one teaspoonful of tarragon vinegar.', 'This work may be done some hours before the time of serving.', 'Have a little oil or clarified butter in the blazer, and saute in it some rounds of bread--one for each half of an egg.', 'When the bread is of good color on one side, turn it and place half an egg--the space from which the yolk was taken being filled with the anchovy mixture--on the bread; cover the blazer, and, when the second side of the bread is browned nicely and the egg hot, serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0335', 'Eggs with Asparagus', 'American', ["section-eggs"], 'eggs', 'dessert', 45, 'INGREDIENTS.', [I('asparagus peas', 1, 'cup', 'Produce'), I('asparagus liquor', 1, 'cup', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('Paprica', 1, '', 'Pantry'), I('or 4 eggs', 3, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('nutmeg', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery')], ['Cut the asparagus in pieces of the size of a pea and cook until tender.', 'In cooking, reserve the tips until the other pieces are partially cooked, or, being more tender, they will become broken while the others are still uncooked.', 'Make a sauce of the butter, flour, salt, paprica, and water in which the asparagus was cooked, or use half a cup of cream in the place of part of the asparagus liquor.', 'When the sauce boils, add the asparagus and mix lightly with the sauce; break the eggs, one after another, into a cup and slide them carefully on to the top of the asparagus.', 'Season with a sprinkling of salt and pepper, and, if desired, a grating of nutmeg.', 'Set the blazer into the bath and put on the cover.', 'When the eggs are nicely poached, remove the eggs, with the asparagus below, on to rounds of toasted and buttered bread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0336', 'Eggs with Spinach', 'American', ["section-eggs"], 'eggs', 'bowl', 45, 'Prepare in the same manner, using for one cup of chopped spinach one-third the quantity of sauce given above.', [I('milk', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('spinach', 1, '', 'Produce'), I('stock', 1, '', 'Pantry')], ['Prepare in the same manner, using for one cup of chopped spinach one-third the quantity of sauce given above.', 'If convenient, the eggs may be poached in a second dish, and in milk, water or stock.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0337', 'Eggs', 'American', ["section-eggs"], 'seafood', 'pasta', 45, '(_Italian Style.', [I('grated Parmesan cheese', 0.5, 'cup', 'Dairy & Eggs'), I('white sauce', 2, 'cups', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('onion juice', 1, '', 'Produce'), I('anchovy essence', 1, '', 'Meat & Seafood'), I('parsley', 1, '', 'Produce'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('anchovy', 1, '', 'Meat & Seafood'), I('macaroni', 1, '', 'Pantry'), I('hard-boiled eggs', 1, '', 'Dairy & Eggs')], ['Cut six cold, hard-boiled eggs into eighths lengthwise; add these, with a cup of cooked macaroni and half a cup of grated Parmesan cheese, to two cups of white sauce, at the boiling-point, in the blazer.', 'Set over hot water, add a teaspoonful of onion juice, a teaspoonful of chopped parsley, salt and anchovy essence to taste, and serve very hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0338', 'Macaroni a la Italienne', 'American', ["section-dishes-largely-vegetarian"], 'beef', 'pasta', 45, 'Have ready one-fourth a pound of macaroni, cooked until tender, but not broken, in boiling salted water, and then drained, and rinsed in cold water.', [I('macaroni', 0.25, 'pound', 'Pantry'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 1, 'tablespoonful', 'Pantry'), I('well-seasoned stock', 0.5, 'cup', 'Pantry'), I('well-reduced tomato pulp', 0.5, 'cup', 'Produce'), I('grated Parmesan cheese', 0.25, 'cup', 'Dairy & Eggs'), I('cold tongue cut in thin slices', 0.75, 'cup', 'Meat & Seafood'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('cheese', 1, '', 'Dairy & Eggs'), I('parmesan', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce'), I('tomatoes', 1, '', 'Produce'), I('tongue', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry')], ['Have ready one-fourth a pound of macaroni, cooked until tender, but not broken, in boiling salted water, and then drained, and rinsed in cold water.', 'Make a sauce of two tablespoonfuls of butter, one tablespoonful of flour, one-fourth a teaspoonful, each, of salt and paprica, half a cup of well-seasoned stock and half a cup of well-reduced tomato pulp.', 'Add the drained macaroni and stir occasionally, while it becomes thoroughly heated, then add one-fourth a cup of grated Parmesan cheese.', 'Lift the macaroni with a fork and spoon so as to mix thoroughly with the cheese, and serve at once.', 'Strain the tomatoes through a sieve sufficiently fine to keep back the seeds, and cook the pulp, very slowly, until reduced to at least half its bulk.', 'A more hearty dish may be served by adding, just before the cheese, three-fourths a cup of cold tongue cut in thin slices and then stamped into small fanciful shapes with a French cutter; or the tongue may be cut simply in small cubes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0339', 'Asparagus Peas', 'American', ["section-dishes-largely-vegetarian"], 'eggs', 'dessert', 45, 'Scrape the scales from the stalks of asparagus and cut the tender portions into pieces one-fourth an inch long.', [I('drawn-butter sauce', 1, 'cup', 'Dairy & Eggs'), I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('peas', 1, '', 'Produce'), I('asparagus', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('stock', 1, '', 'Pantry'), I('biscuit', 1, '', 'Bakery')], ['Scrape the scales from the stalks of asparagus and cut the tender portions into pieces one-fourth an inch long.', 'Cook in boiling salted water until tender; drain, and keep the peas hot.', 'For three cups of peas make one cup of drawn-butter sauce, using as liquid the water in which the asparagus was cooked, or white stock.', 'Add the peas to the sauce; beat the yolks of two eggs, add half a cup of cream, and stir into the sauce and peas; add, also, one tablespoonful of butter.', 'Serve on croutons of fried bread, or in cases made of shredded-wheat biscuit.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0340', 'Fresh Mushrooms and Sweetbreads', 'American', ["section-dishes-largely-vegetarian"], 'chicken', 'dessert', 45, 'Soak one pair of sweetbreads in cold water; cover with boiling salted water and let boil three minutes, then simmer twenty minutes; cool, and cut in small cubes.', [I('sweetbreads in cold water', 1, 'pair', 'Meat & Seafood'), I('chicken stock', 1, 'cup', 'Meat & Seafood'), I('cream', 0.5, 'cup', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('cream or sherry', 0.25, 'cup', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('mushroom', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry'), I('biscuit', 1, '', 'Bakery')], ['Soak one pair of sweetbreads in cold water; cover with boiling salted water and let boil three minutes, then simmer twenty minutes; cool, and cut in small cubes.', 'Saute in two tablespoonfuls of hot butter sufficient mushroom caps, peeled and broken into pieces, to make with the sweetbreads two cups and a half.', 'Make a sauce in the blazer, using one-fourth a cup, each, of butter and flour, one cup of chicken stock and half a cup of cream; add the sweetbreads and mushrooms, one tablespoonful of lemon juice, and, if desired, the yolks of two eggs, beaten and diluted with one-fourth a cup of cream or sherry.', 'Serve on toast, in patty cases, or in cases of shredded-wheat biscuit.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0341', 'Mushroom Cromeskies', 'American', ["section-dishes-largely-vegetarian"], 'pork', 'toast', 45, '(See cut facing page 198.', [I('mushroom', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('bacon', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Peel the caps of fresh mushrooms; wrap each mushroom in a slice of bacon, pinning the bacon around the mushroom with a wooden toothpick.', 'Saute in a hot blazer and serve on toast.', 'These are particularly good, cooked in a hot oven in a double broiler resting over a baking-pan.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0342', 'Creamed Mushrooms', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'dessert', 45, 'Wipe carefully half a pound of mushrooms; peel the caps and break them in pieces.', [I('mushrooms', 0.5, 'pound', 'Produce'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery')], ['Wipe carefully half a pound of mushrooms; peel the caps and break them in pieces.', 'Reserve the stems for another dish.', 'Melt three tablespoonfuls of butter in the blazer and in it saute the mushrooms; dust with salt and pepper, add two tablespoonfuls of flour, and, when cooked in the butter, one cup of cream, gradually; stir until the sauce boils, let simmer a few minutes, then serve with toast or crackers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0343', 'Artichokes a la Bordelaise', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'bowl', 45, '(MRS. E.', [I('butter', 0.25, 'cup', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('rich', 0.5, 'pint', 'Pantry'), I('cayenne', 1, '', 'Herbs & Spices'), I('lemon juice', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('artichokes', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery')], ['(MRS.', 'E.', 'M.', 'LUCAS.)', 'Put one-fourth a cup of butter and half a cup of sifted bread crumbs into the blazer and light the lamp; when the crumbs are well moistened with the butter, add a teaspoonful of fine-minced parsley, one pint of cooked artichokes cut into small cubes, half a teaspoonful of salt, a dash of cayenne and half a pint of rich, sweet cream.', 'Let boil up once and put out the flame; add a teaspoonful of lemon juice and half a teaspoonful of the grated rind of a lemon (or omit the grated rind); stir well and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0344', 'Puff-balls Sauted', 'American', ["section-dishes-largely-vegetarian"], 'eggs', 'skillet', 45, 'Heat three tablespoonfuls of butter or oil in the blazer.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('bread', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery'), I('puff-balls', 1, '', 'Pantry')], ['Heat three tablespoonfuls of butter or oil in the blazer.', 'Cut the puff-balls in slices half an inch in thickness, season with salt and pepper, dip in egg and bread crumbs, and saute in the blazer to a golden brown.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0345', 'Mushrooms and Macaroni', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'dessert', 45, '(_Italian style.', [I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('macaroni', 0.25, 'pound', 'Pantry'), I('grated cheese', 0.25, 'cup', 'Dairy & Eggs'), I('lemon juice', 1, '', 'Produce'), I('milk', 1.25, 'cups', 'Dairy & Eggs'), I('cheese', 1, '', 'Dairy & Eggs'), I('mushrooms', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('flour', 1, '', 'Pantry')], ['Put one tablespoonful of butter and one teaspoonful of lemon juice into the blazer; add a dozen peeled mushrooms, broken into pieces and blanched, and cook slowly, covered, five or six minutes.', 'Then add one cup and one-fourth of milk, and, when scalded, stir in two tablespoonfuls, each, of butter and flour, creamed together.', 'When the sauce boils, add one-fourth a pound of macaroni, cooked and blanched in the usual manner; heat over hot water, and, just before serving, add one-fourth a cup of grated cheese.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0346', 'Canned Peas with Egg', 'American', ["section-dishes-largely-vegetarian"], 'eggs', 'bowl', 45, 'Rinse, drain, and rinse again in boiling water one can of peas.', [I('peas', 1, 'can', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('sugar', 1, 'teaspoonful', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('cream', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs')], ['Rinse, drain, and rinse again in boiling water one can of peas.', 'Add two tablespoonfuls of butter, one teaspoonful of sugar, half a teaspoonful of salt and a dash of pepper.', 'Beat the yolk of an egg, dilute with four tablespoonfuls of cream, and stir into the peas.', 'Serve as soon as the egg thickens slightly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0347', 'Curried Vegetables', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'curry', 45, 'Make a sauce of one-fourth a cup, each, of butter and flour, one tablespoonful of curry powder, half a teaspoonful of salt, a dash of pepper and a pint of milk; add half a teaspoonful of onion juice, one cup of cooked…', [I('curry powder', 1, 'tablespoonful', 'Herbs & Spices'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('onion juice', 0.5, 'teaspoonful', 'Produce'), I('cooked peas', 1, 'cup', 'Produce'), I('pepper', 1, '', 'Produce'), I('curry', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('carrots', 1, '', 'Produce'), I('potato', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('turnips', 1, '', 'Produce'), I('flour', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry')], ['Make a sauce of one-fourth a cup, each, of butter and flour, one tablespoonful of curry powder, half a teaspoonful of salt, a dash of pepper and a pint of milk; add half a teaspoonful of onion juice, one cup of cooked peas, half a cup, each, of potato balls, turnips cut into cubes or fanciful shapes, and carrots cut into straws.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0348', 'Potatoes a la Maitre d\'Hotel', 'American', ["section-dishes-largely-vegetarian"], 'eggs', 'bowl', 45, 'INGREDIENTS.', [I('milk', 1, 'cup', 'Dairy & Eggs'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('yolks of eggs', 2, '', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('parsley, finely', 1, 'tablespoonful', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('pepper', 1, 'dash', 'Produce'), I('potato balls', 1, 'pint', 'Produce'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('potatoes', 1, '', 'Produce')], ['Heat the milk and potatoes in the blazer over hot water.', 'Cream the butter and add the yolks of the eggs, beating them in well; add the parsley and seasonings, mix thoroughly, and, when the potatoes are hot and have absorbed part of the milk, stir the egg and butter into them; add the lemon juice and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0349', 'White Hashed Potatoes', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'bowl', 45, 'Butter the blazer and put into it about three cups of cold chopped potato, salted during the chopping.', [I('chopped potato', 3, 'cups', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('potato', 1, '', 'Produce'), I('stock', 1, '', 'Pantry'), I('potatoes', 1, '', 'Produce')], ['Butter the blazer and put into it about three cups of cold chopped potato, salted during the chopping.', 'Pour over the potato a little hot stock, or water, and scatter some bits of butter over the top.', 'Cover, and cook slowly, without stirring or browning, until thoroughly heated.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0350', 'String Beans a la Lyonnaise', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'skillet', 45, 'Melt three tablespoonfuls of butter in the blazer; add a fine-sliced onion and saute to a delicate brown; add a quart of string beans, cooked, a dash of pepper, a grating of nutmeg and a little salt; heat thoroughly,…', [I('pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('lemon juice', 1, '', 'Produce'), I('nutmeg', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('string beans', 1, '', 'Produce'), I('beans', 1, '', 'Produce'), I('lemon', 1, '', 'Produce')], ['Melt three tablespoonfuls of butter in the blazer; add a fine-sliced onion and saute to a delicate brown; add a quart of string beans, cooked, a dash of pepper, a grating of nutmeg and a little salt; heat thoroughly, tossing the beans occasionally; add a teaspoonful of chopped parsley, a tablespoonful of lemon juice and another tablespoonful of butter, in bits, and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0351', 'Tomato Sandwich', 'American', ["section-dishes-largely-vegetarian"], 'veg', 'dessert', 45, 'INGREDIENTS.', [I('shredded-wheat biscuit', 6, '', 'Bakery'), I('medium-sized tomatoes', 4, '', 'Produce'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('sugar', 8, 'teaspoonfuls', 'Pantry'), I('mayonnaise dressing', 8, 'teaspoonfuls', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('salad dressing', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce')], ['Peel the tomatoes, cut in small pieces, add the salt, and sugar, if used, and set aside in a cool place.', 'Split the biscuits, dip the inside lightly into cold water without wetting the outside, put the halves together, and arrange in a buttered blazer; cover, and heat over hot water; then separate the halves, and, using a knife dipped in hot water, spread with butter.', 'Put a layer of tomatoes on the bottom half, if sugar has not been used, add the salad dressing, and cover with the top of the biscuit, pressing it down lightly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0352', 'Kornlet Oysters', 'American', ["section-dishes-largely-vegetarian"], 'seafood', 'fish', 45, 'To one cup of kornlet add two well-beaten eggs, two tablespoonfuls of flour, a scant half teaspoonful of salt and a dash of paprica.', [I('flour', 2, 'tablespoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs'), I('kornlet', 1, '', 'Pantry'), I('oysters', 1, '', 'Meat & Seafood')], ['To one cup of kornlet add two well-beaten eggs, two tablespoonfuls of flour, a scant half teaspoonful of salt and a dash of paprica.', 'Drop, by spoonfuls, into a hot, well-oiled blazer and cook to a golden brown, turn, and brown the other side.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0353', 'Kornlet Oysters, No. 2', 'American', ["section-dishes-largely-vegetarian"], 'seafood', 'fish', 45, 'To one can of kornlet add a teaspoonful of soda, two well-beaten eggs, salt and pepper, and enough fine cracker crumbs to hold the mixture together.', [I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('eggs', 1, '', 'Dairy & Eggs'), I('kornlet', 1, '', 'Pantry'), I('cracker crumbs', 1, '', 'Bakery'), I('soda', 1, '', 'Pantry'), I('oysters', 1, '', 'Meat & Seafood')], ['To one can of kornlet add a teaspoonful of soda, two well-beaten eggs, salt and pepper, and enough fine cracker crumbs to hold the mixture together.', 'Drop from a spoon and cook as above.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0354', 'Corned-Beef Hash', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'green', 45, '(_Spanish style.', [I('stock', 1, '', 'Pantry'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('potato', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('olives', 1, '', 'Produce'), I('pickles', 1, '', 'Pantry'), I('corned beef', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood'), I('vegetable', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Chop together very fine the corned beef and potatoes and a half or a whole green pepper, after having removed the seeds and veins; put two tablespoonfuls of butter into the blazer (over hot water), add the chopped ingredients, and season to suit the taste, adding a little stock or milk to moisten; mix thoroughly, then cover, and stir occasionally until heated through.', 'Put a few bits of butter here and there over the top, and serve when melted.', 'Use an equal quantity of meat and potato, or twice as much potato as meat.', 'Serve with olives, pickles or a light vegetable salad.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0355', 'Mock Terrapin', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'toast', 45, 'Have ready cooked half a calf\'s liver (it may be boiled or braised with vegetables).', [I('flour', 2, 'tablespoonfuls', 'Pantry'), I('paprica', 0.25, 'teaspoonful', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('water or stock', 1, 'cup', 'Pantry'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('cream', 0.25, 'cup', 'Dairy & Eggs'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('hard-boiled eggs', 2, '', 'Dairy & Eggs'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('toast', 1, '', 'Bakery'), I('stock', 1, '', 'Pantry'), I('vegetables', 1, '', 'Pantry')], ['Have ready cooked half a calf\'s liver (it may be boiled or braised with vegetables).', 'Cut it into small cubes.', 'Put one-fourth a cup of butter into the blazer; when colored a little add the cubes of liver dredged with two tablespoonfuls of flour, one-fourth a teaspoonful of paprica and half a teaspoonful of salt.', 'Stir and cook until the flour is blended with the butter; then add one cup of water or stock and one teaspoonful of chopped parsley.', 'As soon as the sauce boils, add one-fourth a cup of cream, two hard-boiled eggs chopped fine, and one teaspoonful of lemon juice.', 'Serve on toast, with quarters of lemon cut lengthwise.', '_Note._--Cream may be used in the place of stock, and the yolks of two uncooked eggs instead of the cooked eggs.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0356', 'Spaghetti', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'dessert', 45, '(_Queen style.', [I('cream', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('yolks', 1, '', 'Dairy & Eggs'), I('chicken', 1, '', 'Meat & Seafood'), I('turkey', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery'), I('crackers', 1, '', 'Bakery'), I('spaghetti', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Cut cold cooked chicken or turkey and cooked tongue (enough to make one cup of meat) in dice; cut into inch-length pieces cooked spaghetti enough to make one cup.', 'Put one cup and a half of thin cream into the blazer over hot water, and, when hot, add the meat and spaghetti.', 'Beat the yolks of two eggs, add two tablespoonfuls of cream, and stir into the hot mixture; add, also, half a teaspoonful (scant) of salt and a dash of paprica.', 'Stir constantly until the mixture thickens slightly, then serve at once with toast or crackers.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0357', 'Scrambled Ham and Eggs', 'American', ["section-rechauffes-and-olla-podrida"], 'pork', 'bowl', 45, 'Put a tablespoonful of butter in the blazer.', [I('eggs', 6, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('ham', 1, '', 'Meat & Seafood')], ['Put a tablespoonful of butter in the blazer.', 'Break six eggs into a bowl, add six tablespoonfuls of water, and beat until you can take up a spoonful.', 'Add about a cup of fine-chopped ham and mix well.', 'Pour into the blazer, and cook until creamy, stirring constantly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0358', 'Chicken Klopps with Bechamel Sauce', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'bowl', 45, 'INGREDIENTS.', [I('cold chicken', 2, 'cups', 'Meat & Seafood'), I('celery pepper', 0.25, 'teaspoonful', 'Produce'), I('chopped parsley', 1, 'teaspoonful', 'Produce'), I('unbeaten whites of 4 eggs', 1, '', 'Dairy & Eggs'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('egg whites', 4, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('bechamel', 1, '', 'Meat & Seafood')], ['When ready to cook, mix the ingredients together thoroughly and form into round balls.', 'Place the balls carefully in water _just off the boil_, and, in about five minutes, or as soon as the egg seems poached, remove the klopps with a skimmer.', 'Serve with'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0359', 'BECHAMEL SAUCE', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'bowl', 45, 'INGREDIENTS.', [I('butter', 0.3333333333333333, 'cup', 'Dairy & Eggs'), I('flour', 0.3333333333333333, 'cup', 'Pantry'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('chicken stock', 1, 'cup', 'Meat & Seafood'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('paprica', 1, 'dash', 'Pantry'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('bechamel', 1, '', 'Meat & Seafood')], ['Make the sauce in the usual manner, but _do not let it boil after the yolks of the eggs are added_.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0360', 'Minced Ham a la Poulette', 'American', ["section-rechauffes-and-olla-podrida"], 'pork', 'toast', 45, 'To each cup of fine-chopped ham add one tablespoonful of fine bread crumbs, softened with cream or milk.', [I('fine bread crumbs', 1, 'tablespoonful', 'Bakery'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('ham', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('toast', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery')], ['To each cup of fine-chopped ham add one tablespoonful of fine bread crumbs, softened with cream or milk.', 'Season with salt and pepper.', 'Heat thoroughly and spread on rounds of moist buttered toast.', 'Place a poached _egg_ on each slice.', 'Use two dishes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0361', 'Epicurean Canapes', 'American', ["section-rechauffes-and-olla-podrida"], 'veg', 'toast', 45, 'Heat a little butter in the blazer; saute in it some narrow strips of bread and spread them thickly with the mixture used for epicurean sandwiches.', [I('butter', 1, '', 'Dairy & Eggs'), I('olive', 1, '', 'Produce'), I('bread', 1, '', 'Bakery')], ['Heat a little butter in the blazer; saute in it some narrow strips of bread and spread them thickly with the mixture used for epicurean sandwiches.', 'Press a pitted olive in the centre of each and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0362', 'Aberdeen Sandwiches', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'dessert', 45, 'Heat one-fourth a cup of chopped cold tongue or ham, and half a cup of chopped veal or chicken, with half a cup of good sauce and two tablespoonfuls of curry paste (curry powder mixed with just enough water to form a…', [I('cold tongue or ham', 0.25, 'cup', 'Meat & Seafood'), I('chopped veal or chicken', 0.5, 'cup', 'Meat & Seafood'), I('good sauce', 0.5, 'cup', 'Pantry'), I('together', 2, 'pieces', 'Pantry'), I('curry powder', 1, '', 'Herbs & Spices'), I('curry', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('tongue', 1, '', 'Meat & Seafood'), I('veal', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery')], ['Heat one-fourth a cup of chopped cold tongue or ham, and half a cup of chopped veal or chicken, with half a cup of good sauce and two tablespoonfuls of curry paste (curry powder mixed with just enough water to form a paste).', 'Let the mixture simmer five minutes, stirring constantly; then set aside to become cool.', 'Have some bits of bread prepared as for sandwiches.', 'Heat some clarified butter in the blazer, and in it saute the bread a delicate brown, and drain on soft paper.', 'Spread with the cold mixture, press two pieces together, and heat over hot water five or ten minutes.', 'Serve hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0363', 'Calf\'s Head en Tortue', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'dessert', 45, 'Peel a dozen mushrooms; break the caps in pieces and chop the stems very fine.', [I('butter', 3, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 0.25, 'cup', 'Pantry'), I('tomato juice', 0.25, 'cup', 'Produce'), I('meat from a calf\'s head', 1, 'pint', 'Meat & Seafood'), I('salt', 1, '', 'Herbs & Spices'), I('paprica', 1, '', 'Pantry'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('mushrooms', 1, '', 'Produce'), I('calf\'s head', 1, '', 'Pantry'), I('stock', 1.5, 'cups', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Peel a dozen mushrooms; break the caps in pieces and chop the stems very fine.', 'Saute in three tablespoonfuls of butter, adding, if desired, half an onion cut fine.', 'Sprinkle in one-fourth a cup of flour, half a teaspoonful, each, of salt and paprica, and, when the ingredients are well blended, add gradually one cup and a half of stock and one-fourth a cup of tomato juice.', 'Let simmer a few moments, after the sauce boils; then add one pint of meat from a calf\'s head, cooked and cut in cubes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0364', 'Woodcock Toast', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'toast', 45, 'Pound to a paste the freshly boiled livers of two fowls (ducks preferred), one teaspoonful of anchovy paste (or one anchovy may be pounded with the livers), half a teaspoonful of sugar, one tablespoonful of butter,…', [I('sugar', 0.5, 'teaspoonful', 'Pantry'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('spiced pepper', 0.25, 'teaspoonful', 'Produce'), I('pepper', 1, '', 'Produce'), I('anchovy paste', 1, '', 'Meat & Seafood'), I('cream', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('yolks', 1, '', 'Dairy & Eggs'), I('anchovy', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Pound to a paste the freshly boiled livers of two fowls (ducks preferred), one teaspoonful of anchovy paste (or one anchovy may be pounded with the livers), half a teaspoonful of sugar, one tablespoonful of butter, one-fourth a teaspoonful of spiced pepper and the yolks of two raw eggs.', 'Pass through a sieve, dilute with a little hot cream from a cup of cream heated over hot water, stir, and return to the rest of the cream.', 'Stir until thickened, then pour over sippets or rounds of toast sauted a golden brown in a little butter.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0365', 'Scotch Woodcock', 'American', ["section-rechauffes-and-olla-podrida"], 'seafood', 'toast', 45, 'Beat thoroughly three eggs and three teaspoonfuls of anchovy paste.', [I('anchovy paste', 3, 'teaspoonfuls', 'Meat & Seafood'), I('milk', 0.75, 'cup', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('anchovy', 1, '', 'Meat & Seafood'), I('toast', 1, '', 'Bakery')], ['Beat thoroughly three eggs and three teaspoonfuls of anchovy paste.', 'Put this into the chafing-dish over hot water with three-fourths a cup of milk and stir until thick.', 'Spread sippets of toast with butter and then with anchovy paste, and turn the woodcock upon them.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0366', 'Calves\' Brains and Mushrooms a la Poulette', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'dessert', 45, 'Saute a clove of garlic, cut fine, in two tablespoonfuls of butter; add half a pound of mushrooms, peeled and broken in pieces, one-fourth a cup of flour, and saute until well browned.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('mushrooms', 0.5, 'pound', 'Produce'), I('flour', 0.25, 'cup', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('chopped parsley', 1, 'tablespoonful', 'Produce'), I('egg yolks', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('paprica', 1, '', 'Pantry'), I('garlic', 1, '', 'Produce'), I('clove of garlic', 1, '', 'Produce'), I('mace', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('yolks', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('brains', 1, '', 'Pantry'), I('bread', 1, '', 'Bakery'), I('stock', 1.5, 'cups', 'Pantry'), I('calves\' brains', 1, '', 'Pantry')], ['Saute a clove of garlic, cut fine, in two tablespoonfuls of butter; add half a pound of mushrooms, peeled and broken in pieces, one-fourth a cup of flour, and saute until well browned.', 'Then add one-fourth a teaspoonful, each, of mace and paprica, half a teaspoonful of salt and one cup and a half of stock, and cook five or six minutes.', 'Then add the yolks of two eggs, one tablespoonful of lemon juice, one tablespoonful of chopped parsley and three calves\' brains, cooked, and cut in dice.', 'Serve in timbale cases, or upon croustades of bread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0367', 'Beef Tea in Chafing-dish', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'dessert', 45, 'Cut juicy round steak into pieces about two inches square.', [I('salt', 1, '', 'Herbs & Spices'), I('lemon', 1, '', 'Produce'), I('meat', 1, '', 'Meat & Seafood'), I('beef', 1, '', 'Meat & Seafood'), I('tea', 1, '', 'Pantry')], ['Cut juicy round steak into pieces about two inches square.', 'Heat the blazer very hot; heat also a wooden lemon-squeezer in hot water or in any way that is most convenient.', 'Put the meat into the hot blazer, turn again and again with a fork, keeping the blazer very hot.', 'When the bits of meat are heated throughout, squeeze them, one by one, with the lemon-squeezer, into a _hot_ bowl.', 'Season with salt and serve at once.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0368', 'Salmi of Duck or Game', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'dessert', 45, 'INGREDIENTS.', [I('Pieces of game', 1, '', 'Pantry'), I('butter', 1, 'cup', 'Dairy & Eggs'), I('flour', 1, 'cup', 'Pantry'), I('carrot', 1, 'tablespoonful', 'Produce'), I('onion slices', 1, 'tablespoonful', 'Produce'), I('rich brown stock, highly seasoned', 2, 'cups', 'Pantry'), I('madeira', 0.25, 'cup', 'Pantry'), I('peas or flageolets, cooked', 1, 'cup', 'Produce'), I('rich brown stock', 2, 'cups', 'Pantry'), I('peas or flageolets', 1, 'cup', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('meat', 1, '', 'Meat & Seafood'), I('duck', 1, '', 'Meat & Seafood')], ['Cook the butter, onion and carrot in the blazer until well browned.', 'Skim out the onion and carrot and add the flour, pepper and salt.', 'Add the stock.', 'As soon as the sauce is cooked, add the madeira, the pieces of game, and the peas or flageolets.', 'Serve as soon as the meat is hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0369', 'Salmi of Duck, No. 2', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'dessert', 45, 'INGREDIENTS.', [I('thin slices of duck', 1, 'pint', 'Meat & Seafood'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('brown stock', 1, 'pint', 'Pantry'), I('catsup', 1, 'tablespoonful', 'Pantry'), I('or 15 drops of onion juice', 10, '', 'Produce'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('mushrooms', 6, '', 'Produce'), I('currant jelly', 1, 'tablespoonful', 'Produce'), I('Salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('onion juice', 15, 'drops', 'Produce')], ['Brown the butter and make a sauce with the flour, seasoning and stock.', 'Add the duck and mushrooms, simmer twenty minutes, add the currant jelly, and garnish with croutons.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0370', 'Sweetbreads Sauted', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'dessert', 45, 'Split parboiled sweetbreads into two pieces.', [I('Wipe dry', 2, 'pieces', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('oil', 1, '', 'Pantry'), I('olive oil', 1, '', 'Produce'), I('tomato sauce', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('olive', 1, '', 'Produce'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry')], ['Split parboiled sweetbreads into two pieces.', 'Wipe dry, sprinkle with salt, pepper and flour; or season with salt and pepper, and egg-and-bread-crumb them.', 'Saute in the blazer in hot olive oil, or butter, until nicely browned on both sides.', 'Serve with French peas or tomato sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0371', 'Chicken with Mushrooms', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'bowl', 45, 'Melt one-fourth a cup of butter in the blazer; add six mushroom caps, peeled and sliced, and cook slowly, with a teaspoonful of grated onion, about six minutes; add two tablespoonfuls of flour, stir until smooth, then…', [I('flour', 2, 'tablespoonfuls', 'Pantry'), I('cream', 1, 'cup', 'Dairy & Eggs'), I('chicken', 1, 'pint', 'Meat & Seafood'), I('mushroom', 6, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('mace', 1, '', 'Herbs & Spices'), I('butter', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('veal', 1, '', 'Meat & Seafood'), I('lamb', 1, '', 'Meat & Seafood'), I('sweetbreads', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('mushrooms', 1, '', 'Produce')], ['Melt one-fourth a cup of butter in the blazer; add six mushroom caps, peeled and sliced, and cook slowly, with a teaspoonful of grated onion, about six minutes; add two tablespoonfuls of flour, stir until smooth, then add one cup of cream, stock or milk, pepper and salt, and a few grains of mace.', 'When the sauce boils, stir in one pint of chicken, finely chopped, and serve as soon as hot.', 'Sweetbreads, lamb or veal may be served in the same manner.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0372', 'Chopped Beef', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'roast', 45, 'Chop half a pound of raw beef, from the tender part of the round, very fine.', [I('raw beef', 0.5, 'pound', 'Meat & Seafood'), I('grated onion', 1, 'teaspoonful', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('potatoes', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood'), I('bread', 1, '', 'Bakery'), I('flour', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Chop half a pound of raw beef, from the tender part of the round, very fine.', 'Rub the bottom of the hot blazer with butter, put in the meat with one teaspoonful of grated onion, stir, and cook four or five minutes; add two tablespoonfuls of butter, salt and pepper, and serve at once.', 'This is good with bread, but better with baked potatoes.', 'A pound of beef may be cooked at one time in a chafing-dish of good size, and the grated onion increased to suit the taste.', 'The juice, of which there will be a large quantity, may be thickened with flour and butter creamed together; but it is better unthickened.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0373', 'Chicken Timbales', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'bowl', 45, 'Pass the breast of a raw chicken through a meat-chopper five or six times; beat in, one at a time, the whites of two small eggs (the whites of the eggs are _not_ to be previously beaten), then beat in very gradually one…', [I('thick cream', 1, 'cup', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('white pepper', 0.25, 'teaspoonful', 'Produce'), I('egg whites', 1, '', 'Dairy & Eggs'), I('small eggs', 2, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('eggs', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('meat', 1, '', 'Meat & Seafood')], ['Pass the breast of a raw chicken through a meat-chopper five or six times; beat in, one at a time, the whites of two small eggs (the whites of the eggs are _not_ to be previously beaten), then beat in very gradually one cup of thick cream.', 'Season with half a teaspoonful of salt and one-fourth a teaspoonful of white pepper.', 'Turn the mixture into buttered moulds, set them in the blazer, and cook, surrounded with hot water to two-thirds their height and covered, about twenty minutes.', 'The water should not boil; if, with the flame turned low, it still boils, set the blazer into the bath, in which the water may boil vigorously without harm to the timbales.', 'Serve with'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0374', 'BECHAMEL SAUCE', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'bowl', 45, 'Melt two tablespoonfuls of butter, add two tablespoonfuls of flour, one-fourth a teaspoonful of salt, a dash of pepper and half a cup, each, of chicken stock and cream; add the beaten yolk of one egg and let stand over…', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 2, 'tablespoonfuls', 'Pantry'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs'), I('chicken', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood'), I('bechamel', 1, '', 'Meat & Seafood')], ['Melt two tablespoonfuls of butter, add two tablespoonfuls of flour, one-fourth a teaspoonful of salt, a dash of pepper and half a cup, each, of chicken stock and cream; add the beaten yolk of one egg and let stand over hot water five minutes.', 'Or,'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0375', 'MUSHROOM SAUCE', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'skillet', 45, 'Make as above, substituting one-fourth a cup of mushroom liquor for a part of the chicken stock, and adding with the egg half a can of mushrooms, or a cup of fresh mushrooms sauted in two tablespoonfuls of butter.', [I('mushrooms', 0.5, 'can', 'Produce'), I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('mushroom', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('chicken stock', 1, '', 'Meat & Seafood')], ['Make as above, substituting one-fourth a cup of mushroom liquor for a part of the chicken stock, and adding with the egg half a can of mushrooms, or a cup of fresh mushrooms sauted in two tablespoonfuls of butter.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0376', 'Supreme of Chicken', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'bowl', 45, 'Chop fine the breast of a raw chicken.', [I('cream', 1, 'pint', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('white pepper', 1, '', 'Produce'), I('black pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('mushroom', 1, '', 'Produce'), I('truffles', 1, '', 'Pantry'), I('chicken', 1, '', 'Meat & Seafood'), I('bechamel', 1, '', 'Meat & Seafood')], ['Chop fine the breast of a raw chicken.', 'Beat one egg, add the chicken, and continue beating until smooth; then add three eggs, one at a time, beating each egg in thoroughly.', 'Add a generous teaspoonful of salt, a saltspoonful of white pepper, a dash of black pepper and one pint of cream.', 'Butter twelve small moulds and ornament them with truffles.', 'Fill with the chicken mixture, cover with buttered paper, and steam twenty minutes.', 'Or, put in a pan of boiling water and cook in a moderate oven till the centres are firm.', 'Serve with mushroom or bechamel sauce.', 'These can be cooked and left in the moulds and then reheated.', 'It will take about fifteen minutes to reheat.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0377', 'Egg Timbales', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'bowl', 45, 'Beat six eggs without separating, add a scant teaspoonful of salt, a dash of pepper, a teaspoonful of chopped parsley, twenty drops of onion juice and one cup and a half of rich milk.', [I('rich milk', 1.5, 'cups', 'Dairy & Eggs'), I('eggs', 6, '', 'Dairy & Eggs'), I('pepper', 1, '', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('onion juice', 1, '', 'Produce'), I('parsley', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('egg', 1, '', 'Dairy & Eggs')], ['Beat six eggs without separating, add a scant teaspoonful of salt, a dash of pepper, a teaspoonful of chopped parsley, twenty drops of onion juice and one cup and a half of rich milk.', 'Stir till well mixed.', 'Butter small-sized timbale moulds and fill two-thirds full with the mixture.', 'Place moulds in the blazer, pour boiling water about them three-fourths to the tops of the moulds, and let cook about twenty minutes, or till the centres are firm; turn out of the moulds on to a warm platter, and pour about them a thin bread sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0378', 'BREAD SAUCE', 'American', ["section-rechauffes-and-olla-podrida"], 'veg', 'bowl', 45, 'To one pint of milk add half a cup of fine, stale bread crumbs, a small onion with six cloves stuck in it, half a teaspoonful of salt and a few grains of cayenne.', [I('milk add half a cup of fine', 1, 'pint', 'Dairy & Eggs'), I('stuck in it', 6, 'cloves', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('rather coarse bread crumbs', 0.6666666666666666, 'cup', 'Bakery'), I('cloves', 6, '', 'Herbs & Spices'), I('cayenne', 1, '', 'Herbs & Spices'), I('parsley', 1, '', 'Produce'), I('milk', 1, '', 'Dairy & Eggs'), I('onion', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('bread crumbs', 1, '', 'Bakery')], ['To one pint of milk add half a cup of fine, stale bread crumbs, a small onion with six cloves stuck in it, half a teaspoonful of salt and a few grains of cayenne.', 'Cook in the double boiler for about an hour; stir occasionally.', 'Remove the onion, beat well, and add one tablespoonful of butter.', 'Put one tablespoonful of butter over the fire in a small saucepan; when hot add two-thirds a cup of rather coarse bread crumbs; stir over a hot fire till they are brown and crisp.', 'Sprinkle over the timbales and sauce.', 'Add a sprig of parsley to the top of each timbale.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0379', 'Pan-Broiling', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'skillet', 45, 'Chops, birds, venison, hamburg, sirloin and other steaks, even spring chickens, may be cooked successfully in the chafing-dish; but they are not the dishes upon which an amateur should begin his experiments.', [I('oil', 1, '', 'Pantry'), I('olive oil', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('olive', 1, '', 'Produce'), I('lamb', 1, '', 'Meat & Seafood'), I('venison', 1, '', 'Pantry'), I('chops', 1, '', 'Meat & Seafood')], ['Chops, birds, venison, hamburg, sirloin and other steaks, even spring chickens, may be cooked successfully in the chafing-dish; but they are not the dishes upon which an amateur should begin his experiments.', 'Heat the blazer very hot, brush over the surface with a brush dipped in olive oil (or use a butter-ball and a fork), lay in the article to be cooked, sear upon one side, turn and sear upon the other; repeat, turning and cooking until done to taste; five minutes will suffice for small lamb chops.', 'Serve with'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0380', 'Maitre d\'Hotel Butter', 'American', ["section-rechauffes-and-olla-podrida"], 'veg', 'bowl', 45, 'Beat four tablespoonfuls of butter to a cream; add half a teaspoonful of salt and a few grains of pepper, also one tablespoonful of parsley, chopped very fine, and one tablespoonful of lemon juice, very slowly.', [I('butter to a cream', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('parsley', 1, 'tablespoonful', 'Produce'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce')], ['Beat four tablespoonfuls of butter to a cream; add half a teaspoonful of salt and a few grains of pepper, also one tablespoonful of parsley, chopped very fine, and one tablespoonful of lemon juice, very slowly.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0381', 'Fillets of Beef, Mushroom Sauce', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'skillet', 45, 'Have half a dozen slices cut crosswise from a neatly trimmed fillet of beef.', [I('butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('flour', 4, 'tablespoonfuls', 'Pantry'), I('very rich brown stock', 0.5, 'cup', 'Pantry'), I('mushrooms', 0.5, 'bottle', 'Produce'), I('salt', 1, '', 'Herbs & Spices'), I('tabasco', 1, '', 'Pantry'), I('kitchen bouquet', 1, '', 'Meat & Seafood'), I('mushroom', 1, '', 'Produce'), I('beef', 1, '', 'Meat & Seafood'), I('stock', 1, '', 'Pantry'), I('brown sauce', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood')], ['Have half a dozen slices cut crosswise from a neatly trimmed fillet of beef.', 'The slices may be cut of any thickness desired, but from half to three-fourths an inch is preferable for chafing-dish cookery.', 'Melt two tablespoonfuls of butter in a hot blazer; lay in the meat, and cook four or five minutes, turning every ten seconds.', 'The heat should be well maintained throughout the cooking.', 'Season with salt when half cooked.', 'In another blazer make a cup of brown sauce; brown two tablespoonfuls of butter, add four tablespoonfuls of flour, and, when this is well browned, add half a cup of very rich brown stock and half a cup of liquid from the mushroom can.', 'Season to taste with Kitchen Bouquet, salt, and a few drops of tabasco sauce, then add half a bottle of mushrooms, cut in halves.', 'Serve as soon as the mushrooms are hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0382', 'Fillets of Lamb, Cherry Sauce', 'American', ["section-rechauffes-and-olla-podrida"], 'turkey', 'skillet', 45, 'For the fillets use either the fillet from the loin or the top of a "best end of a loin" boned.', [I('sherry wine', 0.5, 'cup', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('butter', 1, '', 'Dairy & Eggs'), I('cherries', 1, '', 'Pantry'), I('turkey', 1, '', 'Meat & Seafood'), I('beef', 1, '', 'Meat & Seafood'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry'), I('maraschino', 1, '', 'Pantry'), I('meat', 1, '', 'Meat & Seafood'), I('cherry', 1, '', 'Pantry'), I('lamb', 1, '', 'Meat & Seafood')], ['For the fillets use either the fillet from the loin or the top of a "best end of a loin" boned.', 'Cut the meat in slices or rounds, and saute in hot butter in the blazer.', 'Season with salt and pepper and pour into the blazer half a cup of maraschino cherries with half a cup of the liquid from the bottle.', 'Candied cherries that have stood half an hour in half a cup of boiling water, on the back of the range, and then mixed with half a cup of sherry wine, may be used in place of the maraschino cherries.', 'This sauce may also be used with fillets of beef or young turkey.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0383', 'Ham Timbales', 'American', ["section-rechauffes-and-olla-podrida"], 'pork', 'bowl', 45, 'INGREDIENTS.', [I('milk or thin cream', 1.5, 'cups', 'Dairy & Eggs'), I('cold, cooked ham', 1, 'cup', 'Meat & Seafood'), I('fine bread crumbs', 0.25, 'cup', 'Bakery'), I('egg yolks', 1, '', 'Dairy & Eggs'), I('raw eggs', 2, '', 'Dairy & Eggs'), I('tabasco sauce', 1, 'drops', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('tomato sauce', 1, '', 'Produce'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('peas', 1, '', 'Produce'), I('bread crumbs', 1, '', 'Bakery')], ['Take the bread crumbs from the centre of a stale loaf.', 'Pass the cooked yolks of eggs through a sieve.', 'Add the ham, crumbs, yolks, salt and tabasco to the raw eggs beaten and mixed with the milk.', 'When thoroughly mixed turn into timbale moulds very carefully buttered.', 'Fit papers into the bottoms of the moulds before buttering.', 'Set these in the blazer, surround with hot water, letting it come half way to the top of the moulds.', 'Heat the water to the boiling-point, then set the blazer into the hot-water pan partly filled with boiling water, cover and cook until the mixture is firm in the centre.', 'Serve, turned from the moulds, with cream or tomato sauce, flavored with onion, or with peas heated in a cream sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0384', 'Fillets of Chicken', 'American', ["section-rechauffes-and-olla-podrida"], 'chicken', 'dessert', 45, '(_Chafing-dish Style.', [I('chicken stock', 0.3333333333333333, 'cup', 'Meat & Seafood'), I('stock', 1, 'cup', 'Pantry'), I('salt', 1, '', 'Herbs & Spices'), I('pepper', 1, '', 'Produce'), I('white pepper', 1, '', 'Produce'), I('catsup', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce'), I('mushroom', 1, '', 'Produce'), I('lemon', 1, '', 'Produce'), I('chicken', 1, '', 'Meat & Seafood'), I('ham', 1, '', 'Meat & Seafood'), I('bacon', 1, '', 'Meat & Seafood'), I('flour', 1, '', 'Pantry'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry')], ['Remove the breast from a plump and tender chicken and separate from the bone and skin.', 'Detach the small fillets, then cut each side into two or three lengthwise slices the size of the small fillets.', 'Keep covered closely until ready to cook.', 'Heat the blazer very hot, butter slightly, and in it lay the fillets and sprinkle with the juice of half a lemon, salt and white pepper; add, also, one-third a cup of chicken stock and a tablespoonful of sherry.', 'Cover and let cook about ten minutes.', 'In the meantime prepare a sauce in a second chafing-dish, using two tablespoonfuls, each, of butter and flour, a dash of salt and pepper, and one cup of stock, in making which a small piece of ham or bacon was used.', 'Add also a tablespoonful of mushroom or tomato catsup and a tablespoonful of sherry wine.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0385', 'Mutton Rechauffe', 'American', ["section-rechauffes-and-olla-podrida"], 'beef', 'pasta', 45, '(_Creole Style.', [I('flour', 3, 'tablespoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('brown stock', 1, 'cup', 'Pantry'), I('cooked macaroni', 0.5, 'cup', 'Pantry'), I('mushrooms', 3, '', 'Produce'), I('pepper', 1, '', 'Produce'), I('catsup', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('tomato', 1, '', 'Produce'), I('onion', 1, '', 'Produce'), I('mushroom', 1, '', 'Produce'), I('mutton', 1, '', 'Meat & Seafood'), I('macaroni', 1, '', 'Pantry'), I('stock', 1, '', 'Pantry')], ['Melt three tablespoonfuls of butter in the blazer and saute in this a tablespoonful, each, of green pepper and onion, chopped fine; add three tablespoonfuls of flour and half a teaspoonful of salt, and stir and cook until frothy; then add, gradually, one cup of brown stock and half a cup of tomato puree (cooked tomato strained).', 'Let boil two or three minutes, then set over hot water and stir in one cup of cold roast mutton cut in strips or cubes, and half a cup of cooked macaroni, blanched and drained.', 'Two or three mushrooms or a tablespoonful of mushroom catsup improves this dish.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0386', 'BABA', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'dessert', 45, 'This cake may be made some days in advance, and when wished reheated in a sauce made in the chafing-dish.', [I('flour', 1, 'lb', 'Pantry'), I('compressed yeast', 1, 'cake', 'Pantry'), I('water', 0.5, 'cup', 'Pantry'), I('butter', 10, 'oz', 'Dairy & Eggs'), I('salt', 0.25, 'teaspoonful', 'Herbs & Spices'), I('sugar', 0.5, 'cup', 'Pantry'), I('eggs', 8, '', 'Dairy & Eggs'), I('currants, sultanas or sliced citron', 0.5, 'cup', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('baba', 1, '', 'Pantry')], ['This cake may be made some days in advance, and when wished reheated in a sauce made in the chafing-dish.', 'Baba is baked in a large mould and cut in slices, or in individual cylindrical or baba moulds.', 'Make a sponge of the yeast, softened in the water, and flour to knead.', 'Knead the little ball of dough until elastic, and put into a small saucepan of lukewarm water.', 'Meanwhile add the butter, sugar, salt and three of the eggs to the rest of the flour, and beat with the hand until all are evenly blended; then add the rest of the eggs, one after another.', 'When the ball of dough rises to the top of the water and is light, remove from the water with a skimmer and beat it into the egg paste; beat for some minutes, then beat in the fruit.', 'Turn the mixture into the mould or moulds, leaving room for the cake to double in bulk.', 'Let rise in a temperature of 68 deg.', 'F.', 'When nearly doubled in bulk, bake from twenty to fifty minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0387', 'SAUCE FOR BABA', 'American', ["section-rechauffes-and-olla-podrida"], 'veg', 'dessert', 45, 'Let two cups of sugar and one cup of water boil in the blazer about six minutes, then add one-fourth a cup, or more, of maraschino, rum or sherry wine.', [I('sugar', 2, 'cups', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('whipped cream', 1, '', 'Dairy & Eggs'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry'), I('rum', 1, '', 'Pantry'), I('maraschino', 1, '', 'Pantry'), I('baba', 1, '', 'Pantry'), I('quince', 1, '', 'Pantry'), I('marmalade', 1, '', 'Pantry'), I('apricot', 1, '', 'Pantry'), I('quince marmalade', 1, '', 'Pantry')], ['Let two cups of sugar and one cup of water boil in the blazer about six minutes, then add one-fourth a cup, or more, of maraschino, rum or sherry wine.', 'Lay the baba, sliced or in individual forms, into the hot syrup and let stand a few minutes, basting the cake with the syrup.', 'When hot, serve with or without whipped cream.', 'Half a cup of apricot or quince marmalade may be added with the wine.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0388', 'Fig Toast', 'American', ["section-rechauffes-and-olla-podrida"], 'veg', 'dessert', 45, '(See cut facing page 198.', [I('pulled figs', 0.5, 'pound', 'Produce'), I('hot butter', 2, 'tablespoonfuls', 'Dairy & Eggs'), I('thick cream', 0.6666666666666666, 'cup', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce'), I('peaches', 1, '', 'Produce'), I('strawberry', 1, '', 'Produce'), I('figs', 1, '', 'Produce'), I('bread', 1, '', 'Bakery'), I('sponge cake', 1, '', 'Pantry'), I('prunes', 1, '', 'Pantry'), I('apricots', 1, '', 'Pantry'), I('pears', 1, '', 'Produce'), I('fig', 1, '', 'Produce'), I('toast', 1, '', 'Bakery')], ['Wash carefully and cook in boiling water half a pound of pulled figs until tender; add one fourth a cup of sugar and the grated rind and juice of half a lemon.', 'Cook until the syrup is well reduced.', 'Cut the crust from a thick slice of bread and saute to a golden brown, first on one side, then on the other, in two tablespoonfuls of hot butter.', 'Drain the bread on soft paper; then heap the figs upon it, cover with two-thirds a cup of thick cream and a scant fourth a cup of sugar, beaten until stiff.', 'Serve at once.', 'Prunes, apricots, peaches, pears, or strawberry preserves, may be prepared in the same manner.', 'If preserves be used, omit the sugar from the cream.', 'Sponge cake may be used in the place of bread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0389', 'Pineapple Sponge', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'bowl', 45, 'Heat one pint of grated pineapple over hot water, sprinkle into it one-third a cup of fine tapioca (a quick-cooking kind), mixed with two-thirds a cup of sugar, and half a teaspoonful of salt; when the tapioca is…', [I('grated pineapple over hot water', 1, 'pint', 'Produce'), I('sugar', 0.6666666666666666, 'cup', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('egg whites', 2, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('lemon', 1, '', 'Produce'), I('pineapple', 1, '', 'Produce'), I('tapioca', 1, '', 'Pantry')], ['Heat one pint of grated pineapple over hot water, sprinkle into it one-third a cup of fine tapioca (a quick-cooking kind), mixed with two-thirds a cup of sugar, and half a teaspoonful of salt; when the tapioca is transparent, add the juice of a lemon, and fold in the whites of two eggs, beaten until dry.', 'Serve with cream and sugar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('hill-0390', 'Tapioca-and-Banana Sponge', 'American', ["section-rechauffes-and-olla-podrida"], 'eggs', 'dessert', 45, 'Sprinkle half a cup of tapioca and two-thirds a cup of sugar into one pint of boiling water; add half a teaspoonful of salt and cook over hot water, stirring occasionally.', [I('tapioca', 0.5, 'cup', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('egg whites', 2, '', 'Dairy & Eggs'), I('lemons', 2, '', 'Produce'), I('eggs', 2, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('whites', 1, '', 'Pantry'), I('bananas', 1, '', 'Produce'), I('peaches', 1, '', 'Produce'), I('apricots', 1, '', 'Pantry'), I('banana', 1, '', 'Produce')], ['Sprinkle half a cup of tapioca and two-thirds a cup of sugar into one pint of boiling water; add half a teaspoonful of salt and cook over hot water, stirring occasionally.', 'When the tapioca is transparent, add the juice of two lemons, and fold in the whites of two eggs, beaten until dry.', 'Serve spread over sliced bananas, with cream and sugar, or with a cold boiled custard, previously made.', 'This dish may be prepared with canned peaches, apricots or quinces, using the juice of the fruit instead of water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
];

